#!/usr/bin/env python3
"""Parse captured help output into structured JSON (development helper)."""
import json, re, sys, os

def parse(text):
    lines = text.split('\n')
    if lines and lines[-1] == '':
        lines = lines[:-1]
    res = {'synopsis': [], 'desc': [], 'options': [], 'tail': [], 'raw_after_opts': []}
    i = 0
    assert lines[0] == 'SYNOPSIS', lines[0]
    i = 2
    while i < len(lines) and lines[i] != '':
        res['synopsis'].append(lines[i]); i += 1
    i += 1
    if i < len(lines) and lines[i] == 'DESCRIPTION':
        i += 2
        while i < len(lines) and lines[i] != 'OPTIONS':
            res['desc'].append(lines[i]); i += 1
        # strip trailing blank
        while res['desc'] and res['desc'][-1] == '':
            res['desc'].pop()
    if i < len(lines) and lines[i] == 'OPTIONS':
        i += 2
        section = None
        cur = None
        while i < len(lines):
            l = lines[i]
            if l.startswith('Options to specify input files:'):
                section = 'in'
            elif l.startswith('Options to specify input/output files:'):
                section = 'inout'
            elif l.startswith('Options to specify output files:'):
                section = 'out'
            elif l.startswith('Other options:'):
                section = 'other'
            elif l == '':
                pass
            elif l.startswith(' -'):
                cur = parse_optline(l)
                cur['section'] = section
                cur['desc'] = []
                res['options'].append(cur)
            elif l.startswith('           ') and cur is not None:
                cur['desc'].append(l[11:])
            else:
                break
            i += 1
        # back up over blank lines
        while i > 0 and lines[i-1] == '':
            i -= 1
        res['tail'] = lines[i:]
    return res

def parse_optline(l):
    m = re.match(r'^ (-\S+)(\s+)(.*)$', l)
    if not m:
        m2 = re.match(r'^ (-\S+)$', l)
        return {'name': m2.group(1), 'type': '', 'default': None, 'flags': None, 'line': l}
    name = m.group(1)
    rest = m.group(3)
    o = {'name': name, 'line': l}
    if name.startswith('-[no]'):
        o['name'] = '-' + name[5:]
        o['kind'] = 'bool'
        mm = re.match(r'^\((yes|no)\)$', rest.strip())
        o['type'] = ''
        o['default'] = mm.group(1)
        o['flags'] = None
        return o
    # type token
    if rest.startswith('['):
        # bracket matching
        depth = 0
        for j, ch in enumerate(rest):
            if ch == '[': depth += 1
            elif ch == ']':
                depth -= 1
                if depth == 0:
                    break
        typ = rest[:j+1]
        rest = rest[j+1:]
    else:
        mm = re.match(r'^(<[^>]*>( \[\.\.\.\])?)(.*)$', rest)
        typ = mm.group(1)
        rest = mm.group(3)
    o['type'] = typ
    rest = rest.strip()
    o['default'] = None
    o['flags'] = None
    # default value in parentheses, flags in parentheses
    parts = re.findall(r'\(([^()]*)\)', rest)
    if parts:
        if parts[-1] in ('Opt.', 'Lib.', 'Opt., Lib.'):
            o['flags'] = parts[-1]
            parts = parts[:-1]
        if parts:
            o['default'] = parts[0]
            # vector defaults may contain spaces; handled
    return o

if __name__ == '__main__':
    out = {}
    hdir, ndir = sys.argv[1], sys.argv[2]
    for fn in sorted(os.listdir(hdir)):
        if not fn.endswith('.txt'): continue
        name = fn[:-4]
        if name.startswith('sel'): continue
        th = open(os.path.join(hdir, fn)).read()
        tn = open(os.path.join(ndir, fn)).read()
        if name == 'help':
            continue
        ph = parse(th); pn = parse(tn)
        visible = set(o['name'] for o in pn['options'])
        for o in ph['options']:
            o['hidden'] = o['name'] not in visible
        assert ph['desc'] == pn['desc'], name
        ph['synopsis_visible'] = pn['synopsis']
        ph['tail_visible'] = pn['tail']
        out[name] = ph
    json.dump(out, open(sys.argv[3], 'w'), indent=1)
