namespace gmx
{

extern const char* const kVersionString;

typedef float real;

// ---------------------------------------------------------------------------
// Program context
struct ProgramInfo
{
    std::string fullPath;    // resolved path of the binary
    std::string binaryName;  // basename of argv[0]
    std::string cwd;         // working directory
    std::string commandLine; // quoted command line
    std::string displayName; // "gmx editconf" or binary name
    bool        quiet   = false;
    bool        backup  = true;
    bool        headerPrinted = false;
};

ProgramInfo& prog();

// ---------------------------------------------------------------------------
// Errors
enum class ErrKind
{
    InvalidInput,      // "Error in user input"
    InconsistentInput, // "Inconsistency in user input"
    FileIO,            // "System I/O error"
    Fatal,             // "Fatal error" (gmx_fatal)
    InvalidValue,      // "Invalid value"?
    Internal,          // "Internal error"
    NotImplemented,    // "Feature not implemented"
    RangeError,        // "Range checking error"? (gmx_fatal with range)
    APIError,          // "API error"
    SimulationInstability
};

struct ErrNode
{
    std::string          msg;
    std::vector<ErrNode> children;
};

class GmxError : public std::exception
{
public:
    ErrKind     kind;
    ErrNode     root;
    std::string srcFile;
    int         line = 0;
    std::string func;
    int         exitCode = 1;

    GmxError(ErrKind k, std::string m, std::string src = "", int l = 0, std::string fn = "") :
        kind(k), srcFile(std::move(src)), line(l), func(std::move(fn))
    {
        root.msg = std::move(m);
    }
    const char* what() const noexcept override { return root.msg.c_str(); }
};

// Exits with code (used for clean early exits that should still unwind).
struct ExitRequest
{
    int code;
};

[[noreturn]] void gmx_fatal(const char* src, int line, const char* fmt, ...);
[[noreturn]] void throwInputError(const std::string& msg, const char* src, int line, const char* func);
[[noreturn]] void throwInconsistent(const std::string& msg, const char* src, int line, const char* func);
[[noreturn]] void throwFileIO(const std::string& msg, const char* src, int line, const char* func);

void printError(const GmxError& e);

// ---------------------------------------------------------------------------
// Text utilities
std::string formatStr(const char* fmt, ...);
std::string vformatStr(const char* fmt, va_list ap);
std::vector<std::string> wrapText(const std::string& text, int width, int indent = 0);
std::string wrapToString(const std::string& text, int width, int indent = 0);
