// Greedy wrapping similar to the GROMACS TextLineWrapper.  Explicit newlines
// are honored; leading whitespace of explicit lines is kept.
std::vector<std::string> wrapText(const std::string& text, int width, int indent)
{
    std::vector<std::string> out;
    std::string              ind(indent, ' ');
    for (const std::string& line : splitLines(text))
    {
        if (line.empty())
        {
            out.push_back("");
            continue;
        }
        size_t pos   = 0;
        bool   first = true;
        while (pos < line.size())
        {
            if (!first)
            {
                while (pos < line.size() && line[pos] == ' ')
                {
                    pos++;
                }
                if (pos >= line.size())
                {
                    break;
                }
            }
            int    avail = width - indent;
            size_t rem   = line.size() - pos;
            if ((int)rem <= avail)
            {
                out.push_back(ind + line.substr(pos));
                break;
            }
            // find last space at or before pos+avail
            size_t brk = std::string::npos;
            for (size_t k = pos + avail; k > pos; k--)
            {
                if (line[k] == ' ')
                {
                    brk = k;
                    break;
                }
            }
            if (brk == std::string::npos)
            {
                // no space found: break at next space after
                size_t k = line.find(' ', pos + avail);
                if (k == std::string::npos)
                {
                    out.push_back(ind + line.substr(pos));
                    break;
                }
                brk = k;
            }
            size_t e = brk;
            while (e > pos && line[e - 1] == ' ')
            {
                e--;
            }
            out.push_back(ind + line.substr(pos, e - pos));
            pos   = brk;
            first = false;
        }
    }
    return out;
}

std::string wrapToString(const std::string& text, int width, int indent)
{
    std::string r;
    for (const auto& l : wrapText(text, width, indent))
    {
        r += l;
        r += '\n';
    }
    return r;
}

