static const char* errKindTitle(ErrKind k)
{
    switch (k)
    {
        case ErrKind::InvalidInput: return "Error in user input";
        case ErrKind::InconsistentInput: return "Inconsistency in user input";
        case ErrKind::FileIO: return "System I/O error";
        case ErrKind::Fatal: return "Fatal error";
        case ErrKind::InvalidValue: return "Invalid value";
        case ErrKind::Internal: return "Internal error";
        case ErrKind::NotImplemented: return "Feature not implemented";
        case ErrKind::RangeError: return "Range checking error";
        case ErrKind::APIError: return "API error";
        case ErrKind::SimulationInstability: return "Simulation instability";
    }
    return "Error";
}

static void formatNode(std::string& out, const ErrNode& n, int indent)
{
    int childIndent = indent;
    if (!n.msg.empty())
    {
        out += wrapToString(n.msg, 78, indent);
        childIndent = indent + 2;
    }
    else
    {
        childIndent = indent + 2;
    }
    for (const auto& c : n.children)
    {
        formatNode(out, c, childIndent);
    }
}

void printError(const GmxError& e)
{
    std::string s;
    s += "\n-------------------------------------------------------\n";
    s += "Program:     " + prog().displayName + ", version " + kVersionString + "\n";
    if (!e.srcFile.empty())
    {
        s += formatStr("Source file: %s (line %d)\n", e.srcFile.c_str(), e.line);
    }
    if (!e.func.empty())
    {
        s += "Function:    " + e.func + "\n";
    }
    s += "\n";
    s += std::string(errKindTitle(e.kind)) + ":\n";
    // Root message at indent 0; children: nodes with empty message only add indentation
    if (!e.root.msg.empty())
    {
        s += wrapToString(e.root.msg, 78, 0);
    }
    for (const auto& c : e.root.children)
    {
        formatNode(s, c, e.root.msg.empty() ? 0 : 2);
    }
    s += "\n";
    s += "For more information and tips for troubleshooting, please check the GROMACS\n";
    s += "website at https://manual.gromacs.org/current/user-guide/run-time-errors.html\n";
