void throwInputError(const std::string& msg, const char* src, int line, const char* func)
{
    throw GmxError(ErrKind::InvalidInput, msg, src, line, func);
}
void throwInconsistent(const std::string& msg, const char* src, int line, const char* func)
{
    throw GmxError(ErrKind::InconsistentInput, msg, src, line, func);
}
void throwFileIO(const std::string& msg, const char* src, int line, const char* func)
{
    throw GmxError(ErrKind::FileIO, msg, src, line, func);
}

