std::string headerText(bool forModule, const std::string& prefix)
{
    const ProgramInfo& p     = prog();
    std::string        title = ":-) GROMACS - " + p.displayName + ", " + kVersionString + " (-:";
    int                pad   = (80 - (int)title.size()) / 2;
    if (pad < 0)
    {
        pad = 0;
    }
    std::string s;
    s += prefix + std::string(pad, ' ') + title + "\n";
    s += prefix + "\n";
    s += prefix + "Executable:   " + p.fullPath + "\n";
    s += prefix + "Data prefix:  " + dataPrefix() + "\n";
    s += prefix + "Working dir:  " + p.cwd + "\n";
    s += prefix + "Command line:\n";
    s += prefix + "  " + p.commandLine + "\n";
    if (forModule)
    {
        s += "\n";
    }
    return s;
}

void printHeader(FILE* fp, bool forModule)
{
    fputs(headerText(forModule, "").c_str(), fp);
    prog().headerPrinted = true;
}

void printCopyright(FILE* fp)
{
    const ProgramInfo& p     = prog();
    std::string        title = ":-) GROMACS - " + p.displayName + ", " + kVersionString + " (-:";
    int                pad   = (80 - (int)title.size()) / 2;
    if (pad < 0)
    {
        pad = 0;
    }
    std::string s;
    s += std::string(pad, ' ') + title + "\n\n";
    s += kCopyrightText;
    s += "GROMACS:      " + p.displayName + ", version " + kVersionString + "\n";
    s += "Executable:   " + p.fullPath + "\n";
    s += "Data prefix:  " + dataPrefix() + "\n";
    s += "Working dir:  " + p.cwd + "\n";
    s += "Command line:\n";
    s += "  " + p.commandLine + "\n";
    fputs(s.c_str(), fp);
}

