static unsigned long long g_rngState = 0;
static bool               g_rngInit  = false;

static unsigned long long nextRand()
{
    if (!g_rngInit)
    {
        g_rngState = (unsigned long long)time(nullptr) * 6364136223846793005ULL + 1442695040888963407ULL;
        g_rngInit  = true;
    }
    g_rngState ^= g_rngState >> 12;
    g_rngState ^= g_rngState << 25;
    g_rngState ^= g_rngState >> 27;
    return g_rngState * 2685821657736338717ULL;
}

std::string randomQuote()
{
    if (kNumQuotes == 0)
    {
        return "\"Thanx for Using GROMACS - Have a Nice Day\"";
    }
    return kQuotes[nextRand() % kNumQuotes];
}

std::string randomPhrase()
{
    if (kNumPhrases == 0)
    {
        return "GROningen MAchine for Chemical Simulation";
    }
    return kPhrases[(nextRand() >> 7) % kNumPhrases];
}

