    fprintf(fp, "\nGROMACS reminds you: %s\n\n", randomQuote().c_str());
}

// ---------------------------------------------------------------------------
bool fileExists(const std::string& name)
{
    struct stat st;
    return stat(name.c_str(), &st) == 0 && !S_ISDIR(st.st_mode);
}

std::string dataPrefix()
{
    return "/usr/local/gromacs";
}

std::string libSearchFile(const std::string& name, bool fatalIfMissing)
{
    if (fileExists(name))
    {
        return name;
    }
    std::vector<std::string> searched;
    searched.push_back(prog().cwd + " (current dir)");
    const char* gmxlib = getenv("GMXLIB");
    if (gmxlib && *gmxlib)
    {
        std::string libs = gmxlib;
        size_t      start = 0;
        while (start <= libs.size())
        {
            size_t      p   = libs.find(':', start);
            std::string dir = libs.substr(start, p == std::string::npos ? std::string::npos : p - start);
            if (!dir.empty())
            {
                if (fileExists(dir + "/" + name))
                {
                    return dir + "/" + name;
                }
                searched.push_back(dir + " (GMXLIB)");
            }
            if (p == std::string::npos)
            {
                break;
            }
            start = p + 1;
        }
    }
    std::string def = dataPrefix() + "/share/gromacs/top";
    if (fileExists(def + "/" + name))
    {
        return def + "/" + name;
    }
    searched.push_back(def + " (default)");
    if (!fatalIfMissing)
    {
        return "";
    }
    std::string msg = "Library file '" + name + "' not found in current dir nor in the default directories.\n";
    msg += "The following paths were searched:";
    for (const auto& s : searched)
    {
        msg += "\n  " + s;
    }
    msg += "\nYou can set additional directories to search with the GMXLIB path variable.";
    throw GmxError(ErrKind::FileIO, msg, "src/gromacs/utility/datafilefinder.cpp", 213,
                   "std::filesystem::__cxx11::path gmx::DataFileFinder::findFile(const "
                   "gmx::DataFileOptions&) const");
}

std::string fileExtension(const std::string& name)
{
    size_t slash = name.rfind('/');
    size_t dot   = name.rfind('.');
    if (dot == std::string::npos || (slash != std::string::npos && dot < slash))
    {
        return "";
    }
    return name.substr(dot);
}

std::string stripExtension(const std::string& name)
{
    std::string e = fileExtension(name);
    return name.substr(0, name.size() - e.size());
}

void makeBackup(const std::string& name)
{
    if (!prog().backup)
    {
        return;
    }
    if (!fileExists(name))
    {
        return;
    }
    int         maxBackup = 99;
    const char* env       = getenv("GMX_MAXBACKUP");
    if (env)
    {
        maxBackup = atoi(env);
        if (maxBackup <= 0)
        {
            return;
        }
    }
    size_t      slash = name.rfind('/');
    std::string dir   = slash == std::string::npos ? "" : name.substr(0, slash + 1);
    std::string base  = slash == std::string::npos ? name : name.substr(slash + 1);
    std::string bname;
    int         i;
    for (i = 1; i <= maxBackup; i++)
    {
        bname = (dir.empty() ? std::string("./") : dir) + "#" + base + "." + std::to_string(i) + "#";
        if (!fileExists(bname))
        {
            break;
        }
    }
    if (i > maxBackup)
    {
        gmx_fatal("src/gromacs/utility/futil.cpp", 325,
                  "Won't make more than %d backups of %s for you.\n"
                  "The env.var. GMX_MAXBACKUP controls this maximum, -1 disables backups.",
                  maxBackup, name.c_str());
    }
    if (rename(name.c_str(), bname.c_str()) == 0)
    {
        fprintf(stderr, "\nBack Off! I just backed up %s to %s\n", name.c_str(), bname.c_str());
    }
}

FILE* openOutput(const std::string& name, const char* mode)
{
    if (mode[0] == 'w')
    {
        makeBackup(name);
    }
    FILE* fp = fopen(name.c_str(), mode);
    if (!fp)
    {
        int         err = errno;
        std::string msg = formatStr("Could not open file '%s'\n  Reason: %s\n  (call to fopen() returned error code %d)",
                                    name.c_str(), strerror(err), err);
        throw GmxError(ErrKind::FileIO, msg, "src/gromacs/utility/futil.cpp", 472, "");
    }
    return fp;
}

FILE* openInput(const std::string& name)
{
    FILE* fp = fopen(name.c_str(), "r");
    if (!fp)
    {
        int err = errno;
        gmx_fatal("src/gromacs/utility/futil.cpp", 472, "Cannot open file '%s'\n  Reason: %s", name.c_str(),
                  strerror(err));
    }
    return fp;
}

