// Command-line option parsing and help formatting.
#include "options.h"

#include <cerrno>
#include <cfloat>
#include <climits>

namespace gmx
{

static const char* const kKnownExts[] = { ".mdp", ".trr", ".xtc", ".tng", ".h5md", ".edr", ".gro",
                                          ".g96", ".pdb", ".brk", ".ent", ".esp", ".pqr", ".tpr",
                                          ".tex", ".rtp", ".atp", ".hdb", ".dat", ".dlg", ".map",
                                          ".eps", ".mat", ".m2p", ".mtx", ".edi", ".cub", ".xpm",
                                          ".xvg", ".ndx", ".top", ".itp", ".log", ".out", ".cpt",
                                          ".csv", ".inp", nullptr };

bool isKnownExtension(const std::string& ext)
{
    for (int i = 0; kKnownExts[i]; i++)
    {
        if (ext == kKnownExts[i])
        {
            return true;
        }
    }
    return false;
}

const helpdata::CmdRec* findCommand(const std::string& name)
{
    for (int i = 0; helpdata::g_cmds[i].name; i++)
    {
        if (name == helpdata::g_cmds[i].name)
        {
            return &helpdata::g_cmds[i];
        }
    }
    return nullptr;
}

static void setupOption(Option& o, const helpdata::OptRec* r)
{
    o.rec          = r;
    o.name         = r->name;
    std::string t  = r->type;
    std::string fl = r->flags ? r->flags : "";
    if (t.empty())
    {
        o.type = OptType::Bool;
        o.bval = r->def && std::string(r->def) == "yes";
    }
    else if (t == "<int>")
    {
        o.type = OptType::Int;
    }
    else if (t == "<real>")
    {
        o.type = OptType::Real;
    }
    else if (t == "<time>")
    {
        o.type = OptType::Time;
    }
    else if (t == "<string>")
    {
        o.type = OptType::String;
    }
    else if (t == "<enum>")
    {
        o.type = OptType::Enum;
    }
    else if (t == "<vector>")
    {
        o.type = OptType::Vector;
    }
    else if (t == "<selection>")
    {
        o.type = OptType::Selection;
        o.multi = true;
    }
    else if (t == "<file>")
    {
        o.type = OptType::FileName;
    }
    else if (t.find("<dir>") != std::string::npos)
    {
        o.type  = OptType::Dir;
        o.multi = true;
    }
    else
    {
        o.type     = OptType::File;
        o.multi    = t.find("[...]") != std::string::npos;
        o.optional = fl.find("Opt.") != std::string::npos;
        o.library  = fl.find("Lib.") != std::string::npos;
        o.input    = r->section == 'i' || r->section == 'b';
        o.output   = r->section == 'o' || r->section == 'b';
        o.defFile  = r->def ? r->def : "";
        std::string inner = t;
        size_t      p     = inner.find("[...]");
        if (p != std::string::npos)
        {
            inner = inner.substr(0, p);
        }
        if (inner.find("...") != std::string::npos)
        {
            std::string d = r->desc;
            for (auto& ch : d)
            {
                if (ch == '\n')
                {
                    ch = ' ';
                }
            }
            size_t c = d.rfind(':');
            for (const auto& e : splitWS(d.substr(c + 1)))
            {
                o.exts.push_back("." + e);
            }
        }
        else
        {
            size_t a = inner.find('<');
            size_t b = inner.find('>');
            std::string list = inner.substr(a + 1, b - a - 1);
            size_t      s    = 0;
            while (true)
            {
                size_t q = list.find('/', s);
                o.exts.push_back(list.substr(s, q == std::string::npos ? std::string::npos : q - s));
                if (q == std::string::npos)
                {
                    break;
                }
                s = q + 1;
            }
        }
    }
    if (o.type == OptType::Enum)
    {
        std::string d = r->desc;
        for (auto& ch : d)
        {
            if (ch == '\n')
            {
                ch = ' ';
            }
        }
        size_t      c    = d.rfind(": ");
        std::string list = d.substr(c + 2);
        size_t      s    = 0;
        while (true)
        {
            size_t q = list.find(", ", s);
            o.enumVals.push_back(trim(list.substr(s, q == std::string::npos ? std::string::npos : q - s)));
            if (q == std::string::npos)
            {
                break;
            }
            s = q + 2;
        }
        std::string def = r->def ? r->def : "";
        for (size_t i = 0; i < o.enumVals.size(); i++)
        {
            if (o.enumVals[i] == def)
            {
                o.enumIdx = (int)i;
            }
        }
    }
    if ((o.type == OptType::Real || o.type == OptType::Int || o.type == OptType::Time) && r->def)
    {
        o.nums.push_back(strtod(r->def, nullptr));
    }
    if (o.type == OptType::Vector && r->def)
    {
        for (const auto& v : splitWS(r->def))
        {
            o.nums.push_back(strtod(v.c_str(), nullptr));
        }
    }
    if ((o.type == OptType::String) && r->def)
    {
        o.values.push_back(r->def);
    }
}

// Common options accepted by all modules.
static const helpdata::OptRec kCommonOpts[] = {
    { "h", 'x', "", "no", nullptr, false, "" },          { "hidden", 'x', "", "no", nullptr, true, "" },
    { "quiet", 'x', "", "no", nullptr, false, "" },      { "version", 'x', "", "no", nullptr, false, "" },
    { "copyright", 'x', "", "no", nullptr, false, "" },  { "nice", 'x', "<int>", "19", nullptr, false, "" },
    { "backup", 'x', "", "yes", nullptr, false, "" },    { "fpexcept", 'x', "", "no", nullptr, true, "" },
    { "debug", 'x', "<int>", "0", nullptr, true, "" },   { nullptr, 0, nullptr, nullptr, nullptr, false, nullptr }
};

Options Options::forCommand(const std::string& cmd)
{
    Options o;
    o.module                  = cmd;
    const helpdata::CmdRec* c = findCommand(cmd);
    if (c)
    {
        for (int i = 0; c->opts[i].name; i++)
        {
            Option opt;
            setupOption(opt, &c->opts[i]);
            o.opts.push_back(opt);
        }
    }
    for (int i = 0; kCommonOpts[i].name; i++)
    {
        if (o.find(kCommonOpts[i].name))
        {
            continue;
        }
        Option opt;
        setupOption(opt, &kCommonOpts[i]);
        o.opts.push_back(opt);
    }
    return o;
}

Option* Options::find(const std::string& name)
{
    for (auto& o : opts)
    {
        if (o.name == name)
        {
            return &o;
        }
    }
    return nullptr;
}

const Option* Options::find(const std::string& name) const
{
    for (const auto& o : opts)
    {
        if (o.name == name)
        {
            return &o;
        }
    }
    return nullptr;
}

Option& Options::get(const std::string& name)
{
    Option* o = find(name);
    if (!o)
    {
        throw std::runtime_error("internal: unknown option " + name);
    }
    return *o;
}

static bool looksLikeNumber(const std::string& s)
{
    if (s.empty())
    {
        return false;
    }
    char* end = nullptr;
    errno     = 0;
    strtod(s.c_str(), &end);
    return end && *end == '\0' && end != s.c_str();
}

static bool isOptionArg(const std::string& a)
{
    if (a.size() < 2 || a[0] != '-')
    {
        return false;
    }
    if (a == "--")
    {
        return false;
    }
    return !looksLikeNumber(a);
}

static std::string optionNameOf(const std::string& a)
{
    if (a.size() > 2 && a[1] == '-')
    {
        return a.substr(2);
    }
    return a.substr(1);
}

static bool parseIntStr(const std::string& s, long long& v, bool is64, std::string& err)
{
    const char* p   = s.c_str();
    char*       end = nullptr;
    errno           = 0;
    long long r     = strtoll(p, &end, 10);
    if (end == p || *end != '\0')
    {
        err = "Invalid value: '" + s + "'; expected an integer";
        return false;
    }
    if (errno == ERANGE || (!is64 && (r > INT_MAX || r < INT_MIN)))
    {
        err = "Invalid value: '" + s + "'; it causes an integer overflow";
        return false;
    }
    v = r;
    return true;
}

static bool parseRealStr(const std::string& s, double& v, bool isFloat, std::string& err)
{
    const char* p   = s.c_str();
    char*       end = nullptr;
    errno           = 0;
    double r        = strtod(p, &end);
    if (end == p || *end != '\0')
    {
        err = "Invalid value: '" + s + "'; expected a number";
        return false;
    }
    if (errno == ERANGE || std::isinf(r) || (isFloat && std::fabs(r) > FLT_MAX))
    {
        err = "Invalid value: '" + s + "'; it causes an overflow/underflow";
        return false;
    }
    if (isFloat)
    {
        r = (double)(float)r;
    }
    v = r;
    return true;
}

static bool parseBoolStr(const std::string& s, bool& v, std::string& err)
{
    std::string l = toLower(s);
    if (l == "1" || l == "yes" || l == "true")
    {
        v = true;
        return true;
    }
    if (l == "0" || l == "no" || l == "false")
    {
        v = false;
        return true;
    }
    err = "Invalid value: '" + s + "'; supported values are: 1, 0, yes, no, true, false";
    return false;
}

static std::string extList(const std::vector<std::string>& exts)
{
    return joinStr(exts, ", ");
}

// Resolve an input file name; returns empty on success, error message otherwise.
static std::string resolveInputFile(const Option& o, const std::string& value, std::string& result)
{
    std::string ext = fileExtension(value);
    bool        known = isKnownExtension(ext);
    if (known)
    {
        bool allowed = false;
        for (const auto& e : o.exts)
        {
            if (e == ext)
            {
                allowed = true;
            }
        }
        if (!allowed)
        {
            return "File name '" + value + "' cannot be used for this option.\nOnly the following extensions are possible:\n  "
                   + extList(o.exts);
        }
        if (o.library)
        {
            std::string f = libSearchFile(value, false);
            if (!f.empty())
            {
                result = f;
                return "";
            }
        }
        if (!fileExists(value))
        {
            int err = errno;
            (void)err;
            return "File '" + value
                   + "' does not exist or is not accessible.\nThe file could not be opened.\n  Reason: No such file or directory\n  (call to fopen() returned error code 2)";
        }
        result = value;
        return "";
    }
    for (const auto& e : o.exts)
    {
        if (fileExists(value + e))
        {
            result = value + e;
            return "";
        }
    }
    if (fileExists(value))
    {
        return "File '" + value
               + "' cannot be used by GROMACS because it does not have a recognizable extension.\nThe following extensions are possible for this option:\n  "
               + extList(o.exts);
    }
    return "File '" + value + "' does not exist or is not accessible.\nThe following extensions were tried to complete the file name:\n  "
           + extList(o.exts);
}

static std::string resolveOutputFile(const Option& o, const std::string& value, std::string& result)
{
    std::string ext   = fileExtension(value);
    bool        known = isKnownExtension(ext);
    if (known)
    {
        bool allowed = false;
        for (const auto& e : o.exts)
        {
            if (e == ext)
            {
                allowed = true;
            }
        }
        if (!allowed)
        {
            return "File name '" + value + "' cannot be used for this option.\nOnly the following extensions are possible:\n  "
                   + extList(o.exts);
        }
        result = value;
        return "";
    }
    std::string defExt = fileExtension(o.defFile);
    if (defExt.empty() && !o.exts.empty())
    {
        defExt = o.exts[0];
    }
    result = value + defExt;
    return "";
}

void Options::parse(const std::vector<std::string>& args)
{
    ErrNode     errors;
    Option*     cur = nullptr;
    ErrNode     curErr;
    std::set<std::string> seen;
    int                   nvals = 0;
    std::vector<std::string> curVals;

    auto finishOption = [&]() {
        if (!cur)
        {
            return;
        }
        Option&  o = *cur;
        ErrNode  e;
        e.msg = "In command-line option -" + o.name;
        auto addErr = [&](const std::string& m) {
            ErrNode c;
            c.msg = m;
            e.children.push_back(c);
        };
        bool hadValueErrors = !curErr.children.empty();
        for (auto& c : curErr.children)
        {
            e.children.push_back(c);
        }
        switch (o.type)
        {
            case OptType::Bool:
                if (curVals.empty() && !hadValueErrors)
                {
                    // flag without value; value set at start
                }
                break;
            case OptType::Int:
            case OptType::Int64:
            case OptType::Real:
            case OptType::Double:
            case OptType::Time:
            case OptType::String:
            case OptType::Enum:
            case OptType::FileName:
                if (curVals.empty() && !hadValueErrors)
                {
                    addErr("Too few (valid) values");
                }
                else if (curVals.empty() && hadValueErrors)
                {
                }
                break;
            case OptType::Vector:
                if (curVals.empty() && !hadValueErrors)
                {
                    addErr("Too few (valid) values");
                }
                else if (!hadValueErrors && curVals.size() == 2)
                {
                    addErr("Expected 1 or 3 values, got 2");
                }
                else if (!hadValueErrors && curVals.size() == 1)
                {
                    double v  = o.nums[0];
                    o.nums    = { v, v, v };
                }
                break;
            case OptType::Selection:
            case OptType::Dir: break;
            case OptType::File:
                if (curVals.empty() && !hadValueErrors)
                {
                    o.hasValue = false;
                }
                break;
        }
        if (!e.children.empty())
        {
            errors.children.push_back(e);
        }
        cur = nullptr;
        curErr.children.clear();
        curVals.clear();
        nvals = 0;
    };

    for (size_t i = 1; i < args.size(); i++)
    {
        const std::string& a = args[i];
        if (isOptionArg(a))
        {
            finishOption();
            std::string name = optionNameOf(a);
            Option*     o    = find(name);
            bool        neg  = false;
            if (!o && startsWith(name, "no"))
            {
                Option* o2 = find(name.substr(2));
                if (o2 && o2->type == OptType::Bool)
                {
                    o   = o2;
                    neg = true;
                }
            }
            if (!o)
            {
                ErrNode wrap;
                ErrNode c;
                c.msg = "Unknown command-line option " + a;
                wrap.children.push_back(c);
                errors.children.push_back(wrap);
                continue;
            }
            if (seen.count(o->name))
            {
                ErrNode e;
                e.msg = "In command-line option -" + o->name;
                ErrNode c;
                c.msg = "Option specified multiple times";
                e.children.push_back(c);
                errors.children.push_back(e);
                continue;
            }
            seen.insert(o->name);
            cur      = o;
            o->set   = true;
            if (o->type == OptType::Bool)
            {
                o->bval = !neg;
            }
            if (o->type != OptType::Bool && o->type != OptType::String)
            {
                if (o->type == OptType::Vector || o->type == OptType::Real || o->type == OptType::Int
                    || o->type == OptType::Time || o->type == OptType::Int64 || o->type == OptType::Double)
                {
                    o->nums.clear();
                }
            }
            if (o->type == OptType::String || o->type == OptType::FileName || o->type == OptType::Selection
                || o->type == OptType::Enum || o->type == OptType::Dir)
            {
                o->values.clear();
            }
            if (o->type == OptType::File)
            {
                o->files.clear();
                o->values.clear();
            }
            continue;
        }
        if (!cur)
        {
            if (!errors.children.empty())
            {
                // keep collecting; positional args are rejected below
            }
            throw GmxError(ErrKind::InvalidInput,
                           "Positional argument '" + a
                                   + "' cannot be accepted. Perhaps you forgot to put a hyphen before an option name.",
                           "src/gromacs/commandline/cmdlineparser.cpp", 248,
                           "void gmx::CommandLineParser::parse(int*, char**)");
        }
        Option& o = *cur;
        auto    valErr = [&](const std::string& m) {
            ErrNode c;
            c.msg = m;
            curErr.children.push_back(c);
        };
        std::string err;
        switch (o.type)
        {
            case OptType::Bool:
            {
                if (nvals >= 1)
                {
                    valErr("Too many values");
                    break;
                }
                bool v;
                if (parseBoolStr(a, v, err))
                {
                    o.bval = v;
                    curVals.push_back(a);
                }
                else
                {
                    // bool errors are reported per value
                    ErrNode e;
                    e.msg = "In command-line option -" + o.name;
                    ErrNode c;
                    c.msg = err;
                    e.children.push_back(c);
                    errors.children.push_back(e);
                }
                nvals++;
                break;
            }
            case OptType::Int:
            case OptType::Int64:
            {
                if (nvals >= 1)
                {
                    valErr("Too many values");
                    nvals++;
                    break;
                }
                long long v;
                if (parseIntStr(a, v, o.type == OptType::Int64, err))
                {
                    o.nums = { (double)v };
                    curVals.push_back(a);
                }
                else
                {
                    valErr(err);
                }
                nvals++;
                break;
            }
            case OptType::Real:
            case OptType::Double:
            case OptType::Time:
            {
                if (nvals >= 1)
                {
                    valErr("Too many values");
                    nvals++;
                    break;
                }
                double v;
                if (parseRealStr(a, v, o.type == OptType::Real, err))
                {
                    o.nums = { v };
                    curVals.push_back(a);
                }
                else
                {
                    valErr(err);
                }
                nvals++;
                break;
            }
            case OptType::Vector:
            {
                if (nvals >= 3)
                {
                    valErr("Too many values");
                    nvals++;
                    break;
                }
                double v;
                if (parseRealStr(a, v, true, err))
                {
                    o.nums.push_back(v);
                    curVals.push_back(a);
                }
                else
                {
                    valErr(err);
                }
                nvals++;
                break;
            }
            case OptType::String:
            case OptType::FileName:
                if (nvals >= 1)
                {
                    valErr("Too many values");
                    nvals++;
                    break;
                }
                o.values = { a };
                curVals.push_back(a);
                nvals++;
                break;
            case OptType::Enum:
            {
                if (nvals >= 1)
                {
                    valErr("Too many values");
                    nvals++;
                    break;
                }
                int found = -1;
                for (size_t k = 0; k < o.enumVals.size(); k++)
                {
                    if (o.enumVals[k] == a)
                    {
                        found = (int)k;
                        break;
                    }
                }
                if (found < 0 && !a.empty())
                {
                    for (size_t k = 0; k < o.enumVals.size(); k++)
                    {
                        if (startsWith(o.enumVals[k], a))
                        {
                            found = (int)k;
                            break;
                        }
                    }
                }
                if (found < 0)
                {
                    valErr("Invalid value: " + a + ". Allowed values: " + joinStr(o.enumVals, ", ") + ".");
                }
                else
                {
                    o.enumIdx = found;
                    o.values  = { o.enumVals[found] };
                    curVals.push_back(a);
                }
                nvals++;
                break;
            }
            case OptType::Selection:
            case OptType::Dir:
                o.values.push_back(a);
                curVals.push_back(a);
                nvals++;
                break;
            case OptType::File:
            {
                if (!o.multi && nvals >= 1)
                {
                    valErr("Too many values");
                    nvals++;
                    break;
                }
                std::string res;
                std::string msg;
                if (o.input && !o.output)
                {
                    msg = resolveInputFile(o, a, res);
                }
                else
                {
                    msg = resolveOutputFile(o, a, res);
                }
                if (!msg.empty())
                {
                    valErr(msg);
                }
                else
                {
                    o.files.push_back(res);
                    o.values.push_back(a);
                    o.hasValue = true;
                    curVals.push_back(a);
                }
                nvals++;
                break;
            }
        }
    }
    finishOption();
    if (!errors.children.empty())
    {
        GmxError e(ErrKind::InvalidInput, "Invalid command-line options", "src/gromacs/commandline/cmdlineparser.cpp",
                   271, "void gmx::CommandLineParser::parse(int*, char**)");
        e.root.children = errors.children;
        throw e;
    }
    // Finish: check required/default files
    ErrNode ferrors;
    for (auto& o : opts)
    {
        if (o.type != OptType::File)
        {
            continue;
        }
        bool needCheck = false;
        bool given     = o.set;
        if (o.input && !o.output)
        {
            if (given && o.files.empty())
            {
                needCheck = true;
            }
            else if (!given && !o.optional)
            {
                needCheck = true;
            }
        }
        if (o.output && o.files.empty())
        {
            o.files.push_back(o.defFile);
        }
        if (!needCheck)
        {
            if (o.input && !o.output && o.files.empty() && !o.defFile.empty())
            {
                // optional, not given: default name (may not exist)
                std::string res;
                if (o.library)
                {
                    std::string f = libSearchFile(o.defFile, false);
                    o.files.push_back(f.empty() ? o.defFile : f);
                }
                else
                {
                    o.files.push_back(o.defFile);
                }
            }
            continue;
        }
        if (o.defFile.empty())
        {
            continue;
        }
        std::string base = stripExtension(o.defFile);
        std::string res;
        bool        ok = false;
        if (o.library)
        {
            std::string f = libSearchFile(o.defFile, false);
            if (!f.empty())
            {
                res = f;
                ok  = true;
            }
        }
        if (!ok)
        {
            for (const auto& e : o.exts)
            {
                if (fileExists(base + e))
                {
                    res = base + e;
                    ok  = true;
                    break;
                }
            }
        }
        if (ok)
        {
            o.files.push_back(res);
            continue;
        }
        ErrNode e;
        e.msg = "In option " + o.name;
        ErrNode c;
        if (given)
        {
            c.msg = "No file name was provided, and the default file '" + base
                    + "' does not exist or is not accessible.\nThe following extensions were tried to complete the file name:\n  "
                    + extList(o.exts);
        }
        else
        {
            c.msg = "Required option was not provided, and the default file '" + base
                    + "' does not exist or is not accessible.\nThe following extensions were tried to complete the file name:\n  "
                    + extList(o.exts);
        }
        e.children.push_back(c);
        ferrors.children.push_back(e);
    }
    if (!ferrors.children.empty())
    {
        GmxError e(ErrKind::InvalidInput, "Invalid input values", "src/gromacs/options/options.cpp", 184,
                   "void gmx::internal::OptionSectionImpl::finish()");
        e.root.children = ferrors.children;
        throw e;
    }
}

bool Options::isSet(const std::string& name) const
{
    const Option* o = find(name);
    return o && o->set;
}

bool Options::getBool(const std::string& name)
{
    return get(name).bval;
}

int Options::getInt(const std::string& name)
{
    Option& o = get(name);
    return o.nums.empty() ? 0 : (int)o.nums[0];
}

int64_t Options::getInt64(const std::string& name)
{
    Option& o = get(name);
    return o.nums.empty() ? 0 : (int64_t)o.nums[0];
}

double Options::getReal(const std::string& name)
{
    Option& o = get(name);
    return o.nums.empty() ? 0 : o.nums[0];
}

std::string Options::getString(const std::string& name)
{
    Option& o = get(name);
    return o.values.empty() ? std::string() : o.values[0];
}

std::vector<std::string> Options::getStrings(const std::string& name)
{
    return get(name).values;
}

std::string Options::getEnum(const std::string& name)
{
    Option& o = get(name);
    return o.enumVals.empty() ? std::string() : o.enumVals[o.enumIdx];
}

int Options::getEnumIndex(const std::string& name)
{
    return get(name).enumIdx;
}

void Options::getVec(const std::string& name, double v[3])
{
    Option& o = get(name);
    for (int i = 0; i < 3; i++)
    {
        v[i] = i < (int)o.nums.size() ? o.nums[i] : 0;
    }
}

std::string Options::fileName(const std::string& name)
{
    Option& o = get(name);
    if (!o.files.empty())
    {
        return o.files[0];
    }
    return o.defFile;
}

std::vector<std::string> Options::fileNames(const std::string& name)
{
    Option& o = get(name);
    if (!o.files.empty())
    {
        return o.files;
    }
    return { o.defFile };
}

bool Options::fileSet(const std::string& name) const
{
    return isSet(name);
}

// ---------------------------------------------------------------------------
// Help formatting

static std::string optionDisplayName(const helpdata::OptRec& r)
{
    if (r.type[0] == '\0')
    {
        return std::string("-[no]") + r.name;
    }
    return std::string("-") + r.name;
}

static void padTo(std::string& s, size_t col)
{
    if (s.size() < col)
    {
        s.append(col - s.size(), ' ');
    }
    else
    {
        s += ' ';
    }
}

static std::string formatOptionLine(const helpdata::OptRec& r)
{
    std::string s = " " + optionDisplayName(r);
    if (r.type[0] != '\0')
    {
        padTo(s, 9);
        s += r.type;
    }
    if (r.def)
    {
        padTo(s, 28);
        s += std::string("(") + r.def + ")";
    }
    if (r.flags)
    {
        padTo(s, 45);
        s += std::string("(") + r.flags + ")";
    }
    return s;
}

std::string renderCommandHelp(const helpdata::CmdRec& c, bool showHidden)
{
    std::string out = "SYNOPSIS\n\n";
    std::string prefix = std::string("gmx") + (std::string(c.name) == "_gmx" ? "" : std::string(" ") + c.name) + " ";
    {
        std::string line   = prefix;
        size_t      indent = prefix.size();
        bool        first  = true;
        for (int i = 0; c.opts[i].name; i++)
        {
            const auto& r = c.opts[i];
            if (r.hidden && !showHidden)
            {
                continue;
            }
            std::string tok = "[" + optionDisplayName(r) + (r.type[0] ? std::string(" ") + r.type : "") + "]";
            if (first)
            {
                line += tok;
                first = false;
            }
            else if (line.size() + 1 + tok.size() <= 78)
            {
                line += " " + tok;
            }
            else
            {
                out += line + "\n";
                line = std::string(indent, ' ') + tok;
            }
        }
        out += line + "\n";
    }
    if (c.desc && c.desc[0])
    {
        out += "\nDESCRIPTION\n\n";
        out += c.desc;
        out += "\n";
    }
    bool anyOpt = false;
    for (int i = 0; c.opts[i].name; i++)
    {
        if (!c.opts[i].hidden || showHidden)
        {
            anyOpt = true;
        }
    }
    if (anyOpt)
    {
        out += "\nOPTIONS\n";
        const char  secs[]   = { 'i', 'b', 'o', 'x' };
        const char* titles[] = { "Options to specify input files:", "Options to specify input/output files:",
                                 "Options to specify output files:", "Other options:" };
        for (int s = 0; s < 4; s++)
        {
            bool any = false;
            for (int i = 0; c.opts[i].name; i++)
            {
                const auto& r = c.opts[i];
                if (r.section != secs[s] || (r.hidden && !showHidden))
                {
                    continue;
                }
                if (!any)
                {
                    out += std::string("\n") + titles[s] + "\n\n";
                    any = true;
                }
                out += formatOptionLine(r) + "\n";
                if (r.desc && r.desc[0])
                {
                    for (const auto& l : splitLines(r.desc))
                    {
                        out += "           " + l + "\n";
                    }
                }
            }
        }
    }
    if (c.tail && c.tail[0])
    {
        out += c.tail;
        out += "\n";
    }
    return out;
}

} // namespace gmx
EOF
