                else if (nValid >= maxVals)
                {
                    pushErr(head, "Too many values");
                }
                else
                {
                    o.enumIdx = found;
                    o.values  = { o.enumVals[found] };
                    nValid++;
                }
                break;
            }
            case OptType::File:
            {
                std::string res;
                std::string msg;
                if (o.input && !o.output)
                {
                    msg = resolveInputFile(o, a, res);
                }
                else
                {
                    msg = resolveOutputFile(o, a, res);
                }
                if (!msg.empty())
                {
                    pushErr(head, msg);
                }
                else if (nValid >= maxVals)
                {
                    pushErr(head, "Too many values");
                }
                else
                {
                    o.files.push_back(res);
                    o.values.push_back(a);
                    o.hasValue = true;
                    nValid++;
                }
                break;
            }
        }
    }
    finishOption();
    if (!errors.children.empty())
