#include "modules.h"
#include "options.h"

using namespace gmx;

static std::string quoteArg(const std::string& a)
{
    if (a.find(' ') != std::string::npos)
    {
        return "'" + a + "'";
    }
    return a;
}

static std::string resolveBinaryPath(const char* argv0)
{
    std::string p = argv0 ? argv0 : "gmx";
    if (p.find('/') == std::string::npos)
    {
        return p;
    }
    if (p[0] != '/')
    {
        p = prog().cwd + "/" + p;
    }
    for (int iter = 0; iter < 32; iter++)
    {
        struct stat st;
        if (lstat(p.c_str(), &st) != 0 || !S_ISLNK(st.st_mode))
        {
            break;
        }
        char    buf[PATH_MAX];
        ssize_t n = readlink(p.c_str(), buf, sizeof(buf) - 1);
        if (n <= 0)
        {
            break;
        }
        buf[n]             = '\0';
        std::string target = buf;
        if (target[0] != '/')
        {
            size_t s = p.rfind('/');
            target   = p.substr(0, s + 1) + target;
        }
        p = target;
    }
    return p;
}

struct CommonFlags
{
    bool h = false, hidden = false, quiet = false, version = false, copyright = false, backup = true;
};

static const char* kCommonNames[] = { "h", "hidden", "quiet", "version", "copyright", "nice", "backup", "fpexcept", "debug", nullptr };

// Parse common options from args (args[0] is skipped), ignoring unknown options.
static void parseCommon(const std::vector<std::string>& args, CommonFlags& f, bool strictUnknown)
{
    Options o = Options::forCommand("_none_");
    std::vector<std::string> filtered;
    filtered.push_back(args.empty() ? std::string() : args[0]);
    if (strictUnknown)
    {
        filtered = args;
    }
    else
    {
        bool keep = false;
        for (size_t i = 1; i < args.size(); i++)
        {
            const std::string& a = args[i];
            bool isOpt = a.size() > 1 && a[0] == '-' && a != "--";
            if (isOpt)
            {
                char* end = nullptr;
                strtod(a.c_str(), &end);
                if (end && *end == '\0')
                {
                    isOpt = false;
                }
            }
            if (isOpt)
            {
                std::string name = a.substr(a[1] == '-' ? 2 : 1);
                keep             = false;
                for (int k = 0; kCommonNames[k]; k++)
                {
                    std::string cn = kCommonNames[k];
                    if (name == cn
                        || (startsWith(name, "no") && name.substr(2) == cn && cn != "nice" && cn != "debug"))
                    {
                        keep = true;
                    }
                }
                if (keep)
                {
                    filtered.push_back(a);
                }
            }
            else if (keep)
            {
                filtered.push_back(a);
            }
        }
    }
    o.parse(filtered);
    f.h         = o.getBool("h");
    f.hidden    = o.getBool("hidden");
    f.quiet     = o.getBool("quiet");
    f.version   = o.getBool("version");
    f.copyright = o.getBool("copyright");
    f.backup    = o.getBool("backup");
}

static void printTopLevelHelp(bool hidden)
{
    const helpdata::CmdRec* c = findCommand("_gmx");
    fputs(renderCommandHelp(*c, hidden).c_str(), stdout);
}

static const char* findTopic(const std::string& path)
{
    for (int i = 0; helpdata::g_topics[i].path; i++)
    {
        if (path == helpdata::g_topics[i].path)
        {
            return helpdata::g_topics[i].text;
        }
    }
    return nullptr;
}

static bool topicHasChildren(const std::string& path)
{
    std::string pre = path + " ";
    for (int i = 0; helpdata::g_topics[i].path; i++)
    {
        if (startsWith(helpdata::g_topics[i].path, pre))
        {
            return true;
        }
    }
    return false;
}

// Returns exit code
static int runHelpModule(const std::vector<std::string>& args, const CommonFlags& f)
{
    // collect positional args (skipping common options and their values)
    std::vector<std::string> pos;
    for (size_t i = 1; i < args.size(); i++)
    {
        const std::string& a = args[i];
        if (a.size() > 1 && a[0] == '-')
        {
            char* end = nullptr;
            strtod(a.c_str(), &end);
            if (!(end && *end == '\0'))
            {
                // option; skip a following value for -nice / -debug
                std::string name = a.substr(a[1] == '-' ? 2 : 1);
                if ((name == "nice" || name == "debug") && i + 1 < args.size())
                {
                    i++;
                }
                continue;
            }
        }
        // values of bool options were validated already (only valid bools could follow)
        if (i > 1)
        {
            const std::string& prev = args[i - 1];
            if (prev.size() > 1 && prev[0] == '-')
            {
