cat > /workspace/src/xvg.cpp <<'EOF'
#include "xvg.h"

#include <ctime>

namespace gmx
{

XvgFormat xvgFormatFromOptions(Options& opts)
{
    if (!opts.find("xvg"))
    {
        return XvgFormat::Xmgrace;
    }
    std::string v = opts.getEnum("xvg");
    if (v == "xmgr")
    {
        return XvgFormat::Xmgr;
    }
    if (v == "none")
    {
        return XvgFormat::None;
    }
    return XvgFormat::Xmgrace;
}

void writeFileHeader(FILE* fp, const char* prefix)
{
    time_t now = time(nullptr);
    char   buf[64];
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, sizeof(buf), "%a %b %e %H:%M:%S %Y", &tmv);
    fprintf(fp, "%sThis file was created %s\n", prefix, buf);
    fprintf(fp, "%sCreated by:\n", prefix);
    const ProgramInfo& p     = prog();
    std::string        title = ":-) GROMACS - " + p.displayName + ", " + kVersionString + " (-:";
    int                pad   = (80 - (int)strlen(prefix) - (int)title.size()) / 2;
    if (pad < 0)
    {
        pad = 0;
    }
    fprintf(fp, "%s%s%s\n", prefix, std::string(pad, ' ').c_str(), title.c_str());
    fprintf(fp, "%s\n", prefix);
    fprintf(fp, "%sExecutable:   %s\n", prefix, p.fullPath.c_str());
    fprintf(fp, "%sData prefix:  %s\n", prefix, dataPrefix().c_str());
    fprintf(fp, "%sWorking dir:  %s\n", prefix, p.cwd.c_str());
    fprintf(fp, "%sCommand line:\n", prefix);
    fprintf(fp, "%s  %s\n", prefix, p.commandLine.c_str());
    std::string pre = prefix;
    std::string bare = trim(pre);
    fprintf(fp, "%s%s is part of G R O M A C S:\n", prefix, p.displayName.c_str());
    fprintf(fp, "%s\n", bare.c_str());
    fprintf(fp, "%s%s\n", prefix, randomPhrase().c_str());
    fprintf(fp, "%s\n", bare.c_str());
}

FILE* xvgrOpen(const std::string& fn, const std::string& title, const std::string& xlabel,
               const std::string& ylabel, XvgFormat fmt)
{
    FILE* fp = openOutput(fn);
    if (fmt != XvgFormat::None)
    {
        writeFileHeader(fp, "# ");
        fprintf(fp, "@    title \"%s\"\n", title.c_str());
        fprintf(fp, "@    xaxis  label \"%s\"\n", xlabel.c_str());
        fprintf(fp, "@    yaxis  label \"%s\"\n", ylabel.c_str());
        if (fmt == XvgFormat::Xmgr)
        {
            fprintf(fp, "@TYPE nxy\n");
        }
        else
        {
            fprintf(fp, "@TYPE xy\n");
        }
    }
    return fp;
}

void xvgrLegend(FILE* fp, const std::vector<std::string>& legends, XvgFormat fmt)
{
    if (fmt == XvgFormat::None)
    {
        return;
    }
    fprintf(fp, "@ view 0.15, 0.15, 0.75, 0.85\n");
    fprintf(fp, "@ legend on\n");
    fprintf(fp, "@ legend box on\n");
    fprintf(fp, "@ legend loctype view\n");
    fprintf(fp, "@ legend 0.78, 0.8\n");
    fprintf(fp, "@ legend length 2\n");
    for (size_t i = 0; i < legends.size(); i++)
    {
        if (fmt == XvgFormat::Xmgrace)
        {
            fprintf(fp, "@ s%zu legend \"%s\"\n", i, legends[i].c_str());
        }
        else
        {
            fprintf(fp, "@ legend string %zu \"%s\"\n", i, legends[i].c_str());
        }
    }
}

void xvgrClose(FILE* fp)
{
    if (fp)
    {
        fclose(fp);
    }
}

void viewFile(Options& opts, const std::string& fn)
{
    if (opts.find("w") && opts.getBool("w"))
    {
        const char* disp = getenv("DISPLAY");
        if (!disp || !*disp)
        {
            fprintf(stderr, "Can not view %s, no DISPLAY environment variable.\n", fn.c_str());
        }
        else
        {
            // Attempt to launch viewer (xmgrace) in background
            std::string cmd = "xmgrace -nxy " + fn + " &";
            fprintf(stderr, "Executing '%s'\n", cmd.c_str());
            int rc = system(cmd.c_str());
            (void)rc;
        }
    }
}

} // namespace gmx
EOF
echo ok"}

