{"command":"cat > /workspace/src/tools/sigeps.cpp <<'EOF'
// gmx sigeps: convert c6/cn to sigma/epsilon and plot potentials.
#include "../modules.h"
#include "../xvg.h"

namespace gmx
{

static const real kOne4PiEps0 = 138.935458f;

static real ljpot(real x, real qq, real c6, real cn, int npow)
{
    return cn * std::pow(x, (real)-npow) - c6 * std::pow(x, (real)-6) + qq * kOne4PiEps0 / x;
}

static real bhpot(real x, real A, real B, real C)
{
    return A * std::exp(-B * x) - C * std::pow(x, (real)-6);
}

static real dpot(real x, real qq, real c6, real cn, int npow)
{
    return -(npow * cn * std::pow(x, (real)(-npow - 1)) - 6 * c6 * std::pow(x, (real)-7)
             + qq * kOne4PiEps0 / (x * x));
}

int runSigeps(Options& opts)
{
    real c6     = (real)opts.getReal("c6");
    real cn     = (real)opts.getReal("cn");
    int  npow   = opts.getInt("pow");
    real sig    = (real)opts.getReal("sig");
    real eps    = (real)opts.getReal("eps");
    real Abh    = (real)opts.getReal("A");
    real Bbh    = (real)opts.getReal("B");
    real Cbh    = (real)opts.getReal("C");
    real qi     = (real)opts.getReal("qi");
    real qj     = (real)opts.getReal("qj");
    real sigfac = (real)opts.getReal("sigfac");

    bool bBham = opts.isSet("A") || opts.isSet("B") || opts.isSet("C");
    if (bBham)
    {
        c6  = Cbh;
        sig = std::pow((real)((6.0 / npow) * std::pow((real)(npow / Bbh), (real)(npow - 6))),
                       (real)(1.0 / (npow - 6)));
        eps = c6 / (4 * std::pow(sig, (real)6));
        cn  = 4 * eps * std::pow(sig, (real)npow);
    }
    else
    {
        if (opts.isSet("sig") || opts.isSet("eps"))
        {
            c6 = 4 * eps * std::pow(sig, (real)6);
            cn = 4 * eps * std::pow(sig, (real)npow);
        }
        else if (opts.isSet("c6") || opts.isSet("cn") || opts.isSet("pow"))
        {
            sig = std::pow(cn / c6, (real)(1.0 / (npow - 6)));
            eps = 0.25f * c6 * std::pow(sig, (real)-6);
        }
        else
        {
            sig = eps = 0;
        }
        printf("c6    = %12.5e, c%d    = %12.5e\n", c6, npow, cn);
        printf("sigma = %12.5f, epsilon = %12.5f\n", sig, eps);
        real rmin = std::pow((real)(std::pow(sig, (real)(npow - 6)) * (real)(npow / 6.0)), (real)(1.0 / (npow - 6)));
        real vmin = ljpot(rmin, 0, c6, cn, npow);
        printf("Van der Waals minimum at %g, V = %g\n\n", rmin, vmin);
        printf("Fit of Lennard Jones (%d-6) to Buckingham:\n", npow);
        Bbh = npow / rmin;
        Cbh = c6;
        Abh = 4 * eps * std::pow(sig / rmin, (real)npow) * std::exp((real)npow);
        printf("A = %g, B = %g, C = %g\n", Abh, Bbh, Cbh);
    }
    real      qq  = qi * qj;
    XvgFormat fmt = xvgFormatFromOptions(opts);
    std::string fn = opts.fileName("o");
    FILE*     fp  = xvgrOpen(fn, "Potential", "r (nm)", "E (kJ/mol)", fmt);
    xvgrLegend(fp, { "Lennard-Jones", "Buckingham" }, fmt);
    if (sig == 0)
    {
        sig = 0.25f;
    }
    real dp[2] = { 0, 0 };
    int  cur   = 0;
    real oldx  = 0;
    for (int i = 0; i < 100; i++)
    {
        real x          = sigfac * sig + sig * i * 0.02f;
        dp[1 - cur]     = dpot(x, qq, c6, cn, npow);
        fprintf(fp, "%10g  %10g  %10g\n", x, ljpot(x, qq, c6, cn, npow), bhpot(x, Abh, Bbh, Cbh));
        if (qq != 0)
        {
            if (i > 0 && dp[cur] * dp[1 - cur] < 0)
            {
                real minimum = oldx + dp[cur] * (x - oldx) / (dp[cur] - dp[1 - cur]);
                real mval    = ljpot(minimum, qq, c6, cn, npow);
                printf("Van der Waals + Coulomb minimum at r = %g (nm). Value = %g (kJ/mol)\n", minimum, mval);
            }
        }
        cur  = 1 - cur;
        oldx = x;
    }
    xvgrClose(fp);
    viewFile(opts, fn);
    return 0;
}

} // namespace gmx
