// Coordinate file I/O (gro, g96, pdb).
#include "structure.h"

#include <cerrno>

namespace gmx
{

FileType fileTypeOf(const std::string& fn)
{
    std::string e = fileExtension(fn);
    if (e == ".gro") return FileType::GRO;
    if (e == ".g96") return FileType::G96;
    if (e == ".pdb" || e == ".brk" || e == ".ent") return FileType::PDB;
    if (e == ".esp") return FileType::ESP;
    if (e == ".tpr") return FileType::TPR;
    if (e == ".xtc") return FileType::XTC;
    if (e == ".trr") return FileType::TRR;
    if (e == ".tng") return FileType::TNG;
    if (e == ".cpt") return FileType::CPT;
    if (e == ".h5md") return FileType::H5MD;
    return FileType::Other;
}

bool boxIsZero(const Matrix box)
{
    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            if (box[i][j] != 0)
            {
                return false;
            }
        }
    }
    return true;
}

void boxFromAngles(real a, real b, real c, real alpha, real beta, real gamma, Matrix box)
{
    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            box[i][j] = 0;
        }
    }
    box[0][0] = a;
    if (alpha != 90.0 || beta != 90.0 || gamma != 90.0)
    {
        const double deg2rad = M_PI / 180.0;
        double       cosa = (alpha != 90.0) ? cos(alpha * deg2rad) : 0;
        double       cosb = (beta != 90.0) ? cos(beta * deg2rad) : 0;
        double       cosg = 0, sing = 1;
        if (gamma != 90.0)
        {
            cosg = cos(gamma * deg2rad);
            sing = sin(gamma * deg2rad);
        }
        box[1][0] = b * cosg;
        box[1][1] = b * sing;
        box[2][0] = c * cosb;
        box[2][1] = c * (cosa - cosb * cosg) / sing;
        box[2][2] = std::sqrt(c * c - box[2][0] * box[2][0] - box[2][1] * box[2][1]);
    }
    else
    {
        box[1][1] = b;
        box[2][2] = c;
    }
}

// ---------------------------------------------------------------------------
// GRO

static bool readLine(FILE* fp, std::string& line)
{
    line.clear();
    int c;
    bool any = false;
    while ((c = fgetc(fp)) != EOF)
    {
        any = true;
        if (c == '\n')
        {
            break;
        }
        line += (char)c;
    }
    if (!line.empty() && line.back() == '\r')
    {
        line.pop_back();
    }
    return any;
}

static void readGro(const std::string& fn, Structure& s)
{
    FILE* fp = fopen(fn.c_str(), "r");
    if (!fp)
    {
        gmx_fatal("src/gromacs/utility/futil.cpp", 472, "Cannot open file '%s'", fn.c_str());
    }
    std::string line;
    readLine(fp, line);
    s.title = trim(line);
    std::string nl;
    if (!readLine(fp, nl))
    {
        fclose(fp);
        gmx_fatal("src/gromacs/fileio/groio.cpp", 66, "gro file does not have the number of atoms on the second line");
    }
    int natoms = 0;
    if (sscanf(nl.c_str(), "%d", &natoms) != 1)
    {
        fclose(fp);
        gmx_fatal("src/gromacs/fileio/groio.cpp", 66, "gro file does not have the number of atoms on the second line");
    }
    s.atoms.clear();
    s.res.clear();
    s.x.assign(natoms, RVec{ 0, 0, 0 });
    s.v.assign(natoms, RVec{ 0, 0, 0 });
    bool bVel  = false;
    int  ddist = 8;
    int  prec  = 3;
    int  prevResnr = -1;
    std::string prevResname;
    for (int i = 0; i < natoms; i++)
    {
        if (!readLine(fp, line))
        {
            fclose(fp);
            gmx_fatal("src/gromacs/fileio/groio.cpp", 144, "Unexpected end of file in file %s at line %d", fn.c_str(),
                      i + 2);
        }
        if ((int)line.size() < 39)
        {
            fclose(fp);
            gmx_fatal("src/gromacs/fileio/groio.cpp", 150, "Invalid line in %s for atom %d:\n%s", fn.c_str(), i + 1,
                      line.c_str());
        }
        if (i == 0)
        {
            // determine precision from decimal points
            size_t p1 = line.find('.', 20);
            size_t p2 = p1 == std::string::npos ? std::string::npos : line.find('.', p1 + 1);
            if (p1 != std::string::npos && p2 != std::string::npos)
            {
                ddist = (int)(p2 - p1);
                prec  = ddist - 5;
            }
            (void)prec;
        }
        std::string resnrS = line.substr(0, 5);
        std::string resname = trim(line.substr(5, 5));
        std::string aname   = trim(line.substr(10, 5));
        int         resnr   = atoi(resnrS.c_str());
        if (i == 0 || resnr != prevResnr || resname != prevResname)
        {
            ResInfo r;
            r.name = resname;
            r.nr   = resnr;
            s.res.push_back(r);
            prevResnr   = resnr;
            prevResname = resname;
        }
        AtomInfo a;
        a.name   = aname;
        a.resind = (int)s.res.size() - 1;
        a.atomnr = atoi(line.substr(15, 5).c_str());
        s.atoms.push_back(a);
        for (int d = 0; d < 3; d++)
        {
            size_t st = 20 + d * ddist;
            std::string f = st < line.size() ? line.substr(st, ddist) : "";
            s.x[i][d] = (real)strtod(f.c_str(), nullptr);
        }
        // velocities
        bool vok = true;
        for (int d = 0; d < 3; d++)
        {
            size_t st = 20 + 3 * ddist + d * (ddist + 1);
            if (st >= line.size())
            {
                vok = false;
                break;
            }
            std::string f   = line.substr(st, ddist + 1);
            char*       end = nullptr;
            double      val = strtod(f.c_str(), &end);
            if (end == f.c_str())
            {
                vok = false;
                break;
            }
            s.v[i][d] = (real)val;
        }
        if (vok)
        {
            if (i == 0)
            {
                bVel = true;
            }
        }
        else if (i == 0)
        {
            bVel = false;
        }
    }
    s.haveV = bVel;
    if (!bVel)
    {
        s.v.assign(natoms, RVec{ 0, 0, 0 });
    }
    // box
    if (!readLine(fp, line))
    {
        fclose(fp);
        gmx_fatal("src/gromacs/fileio/groio.cpp", 233, "Found an invalid box line or no box in file %s", fn.c_str());
    }
    double b[9] = { 0, 0, 0, 0, 0, 0, 0, 0, 0 };
    int    n    = sscanf(line.c_str(), "%lf%lf%lf%lf%lf%lf%lf%lf%lf", &b[0], &b[1], &b[2], &b[3], &b[4], &b[5], &b[6],
                   &b[7], &b[8]);
    if (n < 3)
    {
        fclose(fp);
        gmx_fatal("src/gromacs/fileio/groio.cpp", 233, "Found an invalid box line or no box in file %s", fn.c_str());
    }
    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            s.box[i][j] = 0;
        }
    }
    s.box[0][0] = b[0];
    s.box[1][1] = b[1];
    s.box[2][2] = b[2];
    if (n == 9)
    {
        s.box[0][1] = b[3];
        s.box[0][2] = b[4];
        s.box[1][0] = b[5];
        s.box[1][2] = b[6];
        s.box[2][0] = b[7];
        s.box[2][1] = b[8];
    }
    fclose(fp);
}

void writeGro(FILE* fp, const Structure& s, const std::vector<int>* index, int prec)
{
    std::string title = s.title.empty() ? randomPhrase() : s.title;
    fprintf(fp, "%s\n", title.c_str());
    int n = index ? (int)index->size() : s.natoms();
    fprintf(fp, "%5d\n", n);
    int  l   = prec + 5;
    int  vl  = prec + 6;
    char fmt[64], vfmt[64];
    snprintf(fmt, sizeof(fmt), "%%%d.%df%%%d.%df%%%d.%df", l, prec, l, prec, l, prec);
    snprintf(vfmt, sizeof(vfmt), "%%%d.%df%%%d.%df%%%d.%df", vl, prec + 1, vl, prec + 1, vl, prec + 1);
    for (int k = 0; k < n; k++)
    {
        int             i  = index ? (*index)[k] : k;
        const AtomInfo& a  = s.atoms[i];
        const ResInfo&  r  = s.res[a.resind];
        std::string     rn = r.name.substr(0, 5);
        std::string     an = a.name.substr(0, 5);
        fprintf(fp, "%5d%-5s%5s%5d", r.nr % 100000, rn.c_str(), an.c_str(), (k + 1) % 100000);
        fprintf(fp, fmt, s.x[i][0], s.x[i][1], s.x[i][2]);
        if (s.haveV)
        {
            fprintf(fp, vfmt, s.v[i][0], s.v[i][1], s.v[i][2]);
        }
        fprintf(fp, "\n");
    }
    const Matrix& box = s.box;
    if (box[0][1] != 0 || box[0][2] != 0 || box[1][0] != 0 || box[1][2] != 0 || box[2][0] != 0 || box[2][1] != 0)
    {
        fprintf(fp, "%10.5f%10.5f%10.5f%10.5f%10.5f%10.5f%10.5f%10.5f%10.5f\n", box[0][0], box[1][1], box[2][2],
                box[0][1], box[0][2], box[1][0], box[1][2], box[2][0], box[2][1]);
    }
    else
    {
        fprintf(fp, "%10.5f%10.5f%10.5f\n", box[0][0], box[1][1], box[2][2]);
    }
}

// ---------------------------------------------------------------------------
// G96

static void readG96(const std::string& fn, Structure& s)
{
    FILE* fp = fopen(fn.c_str(), "r");
    if (!fp)
    {
        gmx_fatal("src/gromacs/utility/futil.cpp", 472, "Cannot open file '%s'", fn.c_str());
    }
    std::string line;
    s.atoms.clear();
    s.res.clear();
    s.x.clear();
    s.v.clear();
    s.haveV = false;
    std::string block;
    int         prevResnr = -1;
    std::string prevResname;
    int         vi = 0;
    while (readLine(fp, line))
    {
        if (line.empty() || line[0] == '#')
        {
            continue;
        }
        if (block.empty())
        {
            block = trim(line);
            if (block == "TITLE")
            {
                std::string t;
                while (readLine(fp, line) && trim(line) != "END")
                {
                    t += (t.empty() ? "" : " ") + line;
                }
                s.title = t;
                block.clear();
            }
            continue;
        }
        if (trim(line) == "END")
        {
            block.clear();
            continue;
        }
        if (block == "POSITION")
        {
            int    resnr, atnr;
            char   rn[64], an[64];
            double x, y, z;
            if (sscanf(line.c_str(), "%d %63s %63s %d %lf %lf %lf", &resnr, rn, an, &atnr, &x, &y, &z) == 7)
            {
                if (s.res.empty() || resnr != prevResnr || prevResname != rn)
                {
                    ResInfo r;
                    r.name = rn;
                    r.nr   = resnr;
                    s.res.push_back(r);
                    prevResnr   = resnr;
                    prevResname = rn;
                }
                AtomInfo a;
                a.name   = an;
                a.resind = (int)s.res.size() - 1;
                s.atoms.push_back(a);
                s.x.push_back(RVec{ (real)x, (real)y, (real)z });
            }
        }
        else if (block == "POSITIONRED")
        {
            double x, y, z;
            if (sscanf(line.c_str(), "%lf %lf %lf", &x, &y, &z) == 3)
            {
                s.x.push_back(RVec{ (real)x, (real)y, (real)z });
            }
        }
        else if (block == "VELOCITY")
        {
            int    resnr, atnr;
            char   rn[64], an[64];
            double x, y, z;
            if (sscanf(line.c_str(), "%d %63s %63s %d %lf %lf %lf", &resnr, rn, an, &atnr, &x, &y, &z) == 7)
            {
                if ((int)s.v.size() <= vi)
                {
                    s.v.resize(vi + 1, RVec{ 0, 0, 0 });
                }
                s.v[vi++] = RVec{ (real)x, (real)y, (real)z };
                s.haveV   = true;
            }
        }
        else if (block == "VELOCITYRED")
        {
            double x, y, z;
            if (sscanf(line.c_str(), "%lf %lf %lf", &x, &y, &z) == 3)
            {
                if ((int)s.v.size() <= vi)
                {
                    s.v.resize(vi + 1, RVec{ 0, 0, 0 });
                }
                s.v[vi++] = RVec{ (real)x, (real)y, (real)z };
                s.haveV   = true;
            }
        }
        else if (block == "BOX")
        {
            double b[9] = { 0 };
            int    n = sscanf(line.c_str(), "%lf%lf%lf%lf%lf%lf%lf%lf%lf", &b[0], &b[1], &b[2], &b[3], &b[4], &b[5],
                           &b[6], &b[7], &b[8]);
            for (int i = 0; i < 3; i++)
            {
                for (int j = 0; j < 3; j++)
                {
                    s.box[i][j] = 0;
                }
            }
            s.box[0][0] = b[0];
            s.box[1][1] = b[1];
            s.box[2][2] = b[2];
            if (n == 9)
            {
                s.box[0][1] = b[3];
                s.box[0][2] = b[4];
                s.box[1][0] = b[5];
                s.box[1][2] = b[6];
                s.box[2][0] = b[7];
                s.box[2][1] = b[8];
            }
        }
    }
    fclose(fp);
    s.v.resize(s.x.size(), RVec{ 0, 0, 0 });
}

void writeG96(FILE* fp, const Structure& s, const std::vector<int>* index)
{
    fprintf(fp, "TITLE\n%s\nEND\n", s.title.c_str());
    int n = index ? (int)index->size() : s.natoms();
    fprintf(fp, "POSITION\n");
    for (int k = 0; k < n; k++)
    {
        int             i = index ? (*index)[k] : k;
        const AtomInfo& a = s.atoms[i];
        const ResInfo&  r = s.res[a.resind];
        fprintf(fp, "%5d %-5s %-5s%7d%15.9f%15.9f%15.9f\n", r.nr % 100000, r.name.substr(0, 5).c_str(),
                a.name.substr(0, 5).c_str(), (k + 1) % 10000000, s.x[i][0], s.x[i][1], s.x[i][2]);
    }
    fprintf(fp, "END\n");
    if (s.haveV)
    {
        fprintf(fp, "VELOCITY\n");
        for (int k = 0; k < n; k++)
        {
            int             i = index ? (*index)[k] : k;
            const AtomInfo& a = s.atoms[i];
            const ResInfo&  r = s.res[a.resind];
            fprintf(fp, "%5d %-5s %-5s%7d%15.9f%15.9f%15.9f\n", r.nr % 100000, r.name.substr(0, 5).c_str(),
                    a.name.substr(0, 5).c_str(), (k + 1) % 10000000, s.v[i][0], s.v[i][1], s.v[i][2]);
        }
        fprintf(fp, "END\n");
    }
    const Matrix& box = s.box;
    fprintf(fp, "BOX\n");
    if (box[0][1] != 0 || box[0][2] != 0 || box[1][0] != 0 || box[1][2] != 0 || box[2][0] != 0 || box[2][1] != 0)
    {
        fprintf(fp, "%15.9f%15.9f%15.9f%15.9f%15.9f%15.9f%15.9f%15.9f%15.9f\n", box[0][0], box[1][1], box[2][2],
                box[0][1], box[0][2], box[1][0], box[1][2], box[2][0], box[2][1]);
    }
    else
    {
        fprintf(fp, "%15.9f%15.9f%15.9f\n", box[0][0], box[1][1], box[2][2]);
    }
    fprintf(fp, "END\n");
}

// ---------------------------------------------------------------------------
// PDB

static std::string fieldAt(const char* buf, int start, int len)
{
    // strncpy semantics: stop at NUL
    std::string r;
    for (int i = 0; i < len; i++)
    {
        char c = buf[start + i];
        if (c == '\0')
        {
            break;
        }
        r += c;
    }
    return r;
}

static void readPdb(const std::string& fn, Structure& s)
{
    FILE* fp = fopen(fn.c_str(), "r");
    if (!fp)
    {
        gmx_fatal("src/gromacs/utility/futil.cpp", 472, "Cannot open file '%s'", fn.c_str());
    }
    s.atoms.clear();
    s.res.clear();
    s.x.clear();
    s.v.clear();
    s.haveV   = false;
    s.havePdb = true;
    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            s.box[i][j] = 0;
        }
    }
    static char buf[4096];
    memset(buf, 0, sizeof(buf));
    std::string line;
    bool        haveTitle = false;
    std::string prevKey;
    while (readLine(fp, line))
    {
        size_t n = std::min(line.size(), sizeof(buf) - 1);
        memcpy(buf, line.c_str(), n);
        buf[n] = '\0';
        std::string rec = line.substr(0, 6);
        std::string r6  = trim(rec);
        if (r6 == "ATOM" || r6 == "HETATM")
        {
            AtomInfo    a;
            std::string aname = trim(fieldAt(buf, 12, 4));
            char        alt   = buf[16] ? buf[16] : ' ';
            std::string rname = trim(n > 17 ? fieldAt(buf, 17, 4) : "");
            char        chain = n > 21 ? buf[21] : ' ';
            std::string rnr   = n > 22 ? fieldAt(buf, 22, 4) : "";
            char        ic    = n > 26 ? buf[26] : ' ';
            if (ic == '\0')
            {
                ic = ' ';
            }
            if (chain == '\0')
            {
                chain = ' ';
            }
            double x = strtod(fieldAt(buf, 30, 8).c_str(), nullptr);
            double y = strtod(fieldAt(buf, 38, 8).c_str(), nullptr);
            double z = strtod(fieldAt(buf, 46, 8).c_str(), nullptr);
            double occ  = strtod(fieldAt(buf, 54, 6).c_str(), nullptr);
            double bfac = strtod(fieldAt(buf, 60, 6).c_str(), nullptr);
            char   el   = buf[77];
            int    resnr = atoi(rnr.c_str());
            std::string key = rnr + "|" + rname + "|" + chain + "|" + ic;
            if (s.res.empty() || key != prevKey)
            {
                ResInfo r;
                r.name  = rname;
                r.nr    = resnr;
                r.chain = chain;
                r.ic    = ic;
                s.res.push_back(r);
                prevKey = key;
            }
            a.name   = aname;
            a.altloc = alt;
            a.resind = (int)s.res.size() - 1;
            a.occup  = (real)occ;
            a.bfac   = (real)bfac;
            a.het    = (r6 == "HETATM");
            a.hasPdb = true;
            a.elem   = (el && el != ' ') ? std::string(1, el) : std::string();
            a.atomnr = atoi(fieldAt(buf, 6, 5).c_str());
            s.atoms.push_back(a);
            s.x.push_back(RVec{ (real)(x * 0.1), (real)(y * 0.1), (real)(z * 0.1) });
        }
        else if (r6 == "CRYST1")
        {
            double a = strtod(fieldAt(buf, 6, 9).c_str(), nullptr);
            double b = strtod(fieldAt(buf, 15, 9).c_str(), nullptr);
            double c = strtod(fieldAt(buf, 24, 9).c_str(), nullptr);
            double al = 90, be = 90, ga = 90;
            std::string sa = fieldAt(buf, 33, 7), sb = fieldAt(buf, 40, 7), sg = fieldAt(buf, 47, 7);
            if (!trim(sa).empty()) al = strtod(sa.c_str(), nullptr);
            if (!trim(sb).empty()) be = strtod(sb.c_str(), nullptr);
            if (!trim(sg).empty()) ga = strtod(sg.c_str(), nullptr);
            boxFromAngles((real)(a * 0.1), (real)(b * 0.1), (real)(c * 0.1), (real)al, (real)be, (real)ga, s.box);
        }
        else if (r6 == "TITLE" || r6 == "HEADER")
        {
            if (!haveTitle || r6 == "TITLE")
            {
                s.title   = trim(line.size() > 6 ? line.substr(6) : "");
                haveTitle = true;
            }
        }
        else if (r6 == "ENDMDL" || r6 == "END")
        {
            if (!s.atoms.empty())
            {
                break;
            }
        }
    }
    fclose(fp);
    s.v.assign(s.x.size(), RVec{ 0, 0, 0 });
}

static void pdbAtomLine(FILE* fp, bool het, int nr, const std::string& name, char altloc, const std::string& resname,
                        char chain, int resnr, char ic, double x, double y, double z, double occ, double bfac,
                        const std::string& elem)
{
    std::string an;
    if (elem.size() >= 2 && strncasecmp(name.c_str(), elem.c_str(), 2) == 0)
    {
        an = name.substr(0, 4);
    }
    else if (name.size() < 4)
    {
        an = " " + name;
    }
    else
    {
        an = name.substr(0, 4);
    }
    std::string rn = resname.substr(0, 4);
    char        rnbuf[16];
    if (rn.size() < 4)
    {
        snprintf(rnbuf, sizeof(rnbuf), "%3s ", rn.c_str());
    }
    else
    {
        snprintf(rnbuf, sizeof(rnbuf), "%s", rn.c_str());
    }
    fprintf(fp, "%-6s%5d %-4.4s%c%4.4s%c%4d%c   %8.3f%8.3f%8.3f%6.2f%6.2f          %2s\n", het ? "HETATM" : "ATOM",
            nr % 100000, an.c_str(), altloc, rnbuf, chain, resnr % 10000, ic, x, y, z, occ, bfac, elem.c_str());
}

void writePdb(FILE* fp, const Structure& s, const std::vector<int>* index, int model, bool writeTer, bool remarkBox)
{
    std::string title = s.title.empty() ? randomPhrase() : s.title;
    fprintf(fp, "TITLE     %s\n", title.c_str());
    if (!boxIsZero(s.box))
    {
        if (remarkBox)
        {
            fprintf(fp, "REMARK    THIS IS A SIMULATION BOX\n");
        }
        // compute lengths and angles
        double a[3], ang[3];
        for (int i = 0; i < 3; i++)
        {
            a[i] = std::sqrt((double)s.box[i][0] * s.box[i][0] + (double)s.box[i][1] * s.box[i][1]
                             + (double)s.box[i][2] * s.box[i][2]);
        }
        auto angle = [&](int i, int j) {
            double dot = (double)s.box[i][0] * s.box[j][0] + (double)s.box[i][1] * s.box[j][1]
                         + (double)s.box[i][2] * s.box[j][2];
            if (a[i] == 0 || a[j] == 0)
            {
                return 90.0;
            }
            return acos(dot / (a[i] * a[j])) * 180.0 / M_PI;
        };
        ang[0] = (s.box[1][2] == 0 && s.box[2][1] == 0 && s.box[1][0] == 0 && s.box[2][0] == 0 && s.box[0][1] == 0
                  && s.box[0][2] == 0)
                         ? 90.0
                         : angle(1, 2);
        ang[1] = (s.box[2][0] == 0 && s.box[0][2] == 0 && s.box[1][0] == 0 && s.box[2][1] == 0 && s.box[0][1] == 0
                  && s.box[1][2] == 0)
                         ? 90.0
                         : angle(0, 2);
        ang[2] = (s.box[1][0] == 0 && s.box[0][1] == 0 && s.box[2][0] == 0 && s.box[2][1] == 0 && s.box[0][2] == 0
                  && s.box[1][2] == 0)
                         ? 90.0
                         : angle(0, 1);
        fprintf(fp, "CRYST1%9.3f%9.3f%9.3f%7.2f%7.2f%7.2f %-11s%4d\n", 10 * a[0], 10 * a[1], 10 * a[2], ang[0],
                ang[1], ang[2], "P 1", 1);
    }
    if (model >= 0)
    {
        fprintf(fp, "MODEL %8d\n", model);
    }
    int n = index ? (int)index->size() : s.natoms();
    for (int k = 0; k < n; k++)
    {
        int             i = index ? (*index)[k] : k;
        const AtomInfo& a = s.atoms[i];
        const ResInfo&  r = s.res[a.resind];
        double          occ  = a.hasPdb ? a.occup : 1.0;
        double          bfac = a.hasPdb ? a.bfac : 0.0;
        pdbAtomLine(fp, a.het, i + 1, a.name, a.altloc, r.name, r.chain, r.nr, r.ic, 10 * s.x[i][0], 10 * s.x[i][1],
                    10 * s.x[i][2], occ, bfac, a.elem);
    }
    if (writeTer)
    {
        fprintf(fp, "TER\n");
    }
    fprintf(fp, "ENDMDL\n");
}

// ---------------------------------------------------------------------------

void readStructure(const std::string& fn, Structure& s)
{
    switch (fileTypeOf(fn))
    {
        case FileType::GRO: readGro(fn, s); break;
        case FileType::G96: readG96(fn, s); break;
        case FileType::PDB: readPdb(fn, s); break;
        case FileType::ESP: readPdb(fn, s); break;
        default:
            gmx_fatal("src/gromacs/fileio/confio.cpp", 440, "Not supported in read_whole_conf: %s", fn.c_str());
    }
}

void writeStructure(const std::string& fn, const Structure& s, const std::vector<int>* index)
{
    FILE* fp = openOutput(fn);
    switch (fileTypeOf(fn))
    {
        case FileType::GRO: writeGro(fp, s, index); break;
        case FileType::G96: writeG96(fp, s, index); break;
        case FileType::PDB: writePdb(fp, s, index); break;
        default: writeGro(fp, s, index); break;
    }
    fclose(fp);
}

} // namespace gmx
