cat > /workspace/src/xvgread.cpp <<'EOF'
#include "xvgread.h"

namespace gmx
{

static bool getLine(FILE* fp, std::string& line)
{
    line.clear();
    int  c;
    bool any = false;
    while ((c = fgetc(fp)) != EOF)
    {
        any = true;
        if (c == '\n')
        {
            break;
        }
        line += (char)c;
    }
    return any;
}

static int parseNumbers(const std::string& line, std::vector<double>& out, int maxn)
{
    out.clear();
    const char* p = line.c_str();
    while (*p && (maxn < 0 || (int)out.size() < maxn))
    {
        while (*p && isspace((unsigned char)*p))
        {
            p++;
        }
        if (!*p)
        {
            break;
        }
        char*  end = nullptr;
        double v   = strtod(p, &end);
        if (end == p)
        {
            break;
        }
        out.push_back(v);
        p = end;
    }
    return (int)out.size();
}

void readXvgTime(const std::string& fn, bool haveTime, bool bTB, double tb, bool bTE, double te, int nsetsIn,
                 XvgData& d)
{
    FILE* fp = fopen(fn.c_str(), "r");
    if (!fp)
    {
        gmx_fatal("src/gromacs/utility/futil.cpp", 472, "Cannot open file '%s'", fn.c_str());
    }
    std::string         line;
    int                 narg  = 0;
    bool                first = true;
    int                 nsetBlock = 0; // which & block
    std::vector<double> nums;
    std::vector<std::vector<double>> times(1);
    std::vector<std::vector<std::vector<double>>> vals(1);
    int nsetPerBlock = 0;
    bool stop = false;
    while (!stop && getLine(fp, line))
    {
        size_t k = 0;
        while (k < line.size() && isspace((unsigned char)line[k]))
        {
            k++;
        }
        if (k < line.size() && line[k] == '&')
        {
            if (nsetsIn > 1 && nsetBlock + 1 < nsetsIn)
            {
                nsetBlock++;
                times.emplace_back();
                vals.emplace_back();
                continue;
            }
            break;
        }
        if (k >= line.size() || line[k] == '#' || line[k] == '@')
        {
            if (k < line.size() && line[k] == '@')
            {
                // legends
                std::string l = line.substr(k + 1);
                size_t      q = l.find("legend \"");
                if (q != std::string::npos && l.find(" s") != std::string::npos)
                {
                    size_t q2 = l.rfind('"');
                    if (q2 > q + 8)
                    {
                        d.legends.push_back(l.substr(q + 8, q2 - q - 8));
                    }
                }
            }
            continue;
        }
        if (first)
        {
            narg = parseNumbers(line, nums, -1);
            if (narg == 0)
            {
                continue;
            }
            if (haveTime && narg == 1)
            {
                fprintf(stderr, "Found only 1 number on line, assuming no time is present.\n");
                haveTime = false;
            }
            nsetPerBlock = narg - (haveTime ? 1 : 0);
            first        = false;
        }
        else
        {
            int n = parseNumbers(line, nums, narg);
            if (n == 0)
            {
                continue;
            }
            if (n < narg)
            {
                fprintf(stderr, "Invalid line in %s:\n%s", fn.c_str(), (line + "\n").c_str());
                fprintf(stderr, "Using zeros for the last %d sets\n", narg - n);
                while ((int)nums.size() < narg)
                {
                    nums.push_back(0);
                }
            }
        }
        double tt = haveTime ? nums[0] : (double)times[nsetBlock].size();
        if (bTB && tt < tb)
        {
            continue;
        }
        if (bTE && tt > te)
        {
            if (nsetsIn > 1)
            {
                continue;
            }
            stop = true;
            break;
        }
        times[nsetBlock].push_back(tt);
        std::vector<double> row;
        for (int s = 0; s < nsetPerBlock; s++)
        {
            row.push_back(nums[(haveTime ? 1 : 0) + s]);
        }
        vals[nsetBlock].push_back(row);
    }
    fclose(fp);
    int nblocks = (int)times.size();
    d.nset      = nsetPerBlock * nblocks;
    d.n         = 0;
    if (!times.empty())
    {
        d.n = (int)times[0].size();
        for (const auto& tb2 : times)
        {
            d.n = std::min(d.n, (int)tb2.size());
        }
    }
    if (first)
    {
        d.nset = 0;
        d.n    = 0;
    }
    d.t.assign(d.n, 0);
    for (int i = 0; i < d.n; i++)
    {
        d.t[i] = times[0][i];
    }
    d.val.assign(d.nset, std::vector<double>(d.n, 0));
    for (int b = 0; b < nblocks; b++)
    {
        for (int s = 0; s < nsetPerBlock; s++)
        {
            for (int i = 0; i < d.n; i++)
            {
                d.val[b * nsetPerBlock + s][i] = vals[b][i][s];
            }
        }
    }
    d.dt = (d.n > 1) ? (d.t[1] - d.t[0]) : 1;
}

std::vector<std::vector<double>> readXvgColumns(const std::string& fn, std::vector<std::string>* legends,
                                                std::string* title)
{
    FILE* fp = fopen(fn.c_str(), "r");
    if (!fp)
    {
        gmx_fatal("src/gromacs/utility/futil.cpp", 472, "Cannot open file '%s'", fn.c_str());
    }
    std::vector<std::vector<double>> rows;
    std::string                      line;
    std::vector<double>              nums;
    while (getLine(fp, line))
    {
        size_t k = 0;
        while (k < line.size() && isspace((unsigned char)line[k]))
        {
            k++;
        }
        if (k >= line.size())
        {
            continue;
        }
        if (line[k] == '&')
        {
            break;
        }
        if (line[k] == '#')
        {
            continue;
        }
        if (line[k] == '@')
        {
            std::string l = line.substr(k + 1);
            if (legends)
            {
                size_t q = l.find("legend \"");
                if (q != std::string::npos)
                {
                    size_t q2 = l.rfind('"');
                    if (q2 > q + 8)
                    {
                        legends->push_back(l.substr(q + 8, q2 - q - 8));
                    }
                }
            }
            if (title)
            {
                size_t q = l.find("title \"");
                if (q != std::string::npos && l.find("axis") == std::string::npos)
                {
                    size_t q2 = l.rfind('"');
                    *title    = l.substr(q + 7, q2 - q - 7);
                }
            }
            continue;
        }
        if (parseNumbers(line, nums, -1) > 0)
        {
            rows.push_back(nums);
        }
    }
    fclose(fp);
    return rows;
}

} // namespace gmx
