// gmx analyze: analyze data sets.
#include "../modules.h"
#include "../xvg.h"
#include "../xvgread.h"

namespace gmx
{

static void printStats(int n, int nset, const std::vector<std::vector<real>>& val)
{
    printf("                                      std. dev.    relative deviation of\n");
    printf("                       standard       ---------   cumulants from those of\n");
    printf("set      average       deviation      sqrt(n-1)   a Gaussian distribition\n");
    printf("                                                      cum. 3   cum. 4\n");
    for (int s = 0; s < nset; s++)
    {
        real cum1 = 0, cum2 = 0, cum3 = 0, cum4 = 0;
        for (int i = 0; i < n; i++)
        {
            cum1 += val[s][i];
        }
        cum1 /= n;
        for (int i = 0; i < n; i++)
        {
            real db = val[s][i] - cum1;
            cum2 += db * db;
            cum3 += db * db * db;
            cum4 += db * db * db * db;
        }
        cum2 /= n;
        cum3 /= n;
        cum4 /= n;
        real av  = cum1;
        real sig = std::sqrt(cum2);
        real error;
        if (n > 1)
        {
            error = std::sqrt(cum2 / (n - 1));
        }
        else
        {
            error = 0;
        }
        printf("SS%d  %13.6e   %12.6e   %12.6e      %6.3f   %6.3f\n", s + 1, av, sig, error,
               sig ? cum3 / (sig * sig * sig * std::sqrt(8 / M_PI)) : 0,
               sig ? cum4 / (sig * sig * sig * sig * 3) - 1 : 0);
    }
    printf("\n");
}

static real evaluateIntegral(int n, const std::vector<real>& x, const std::vector<real>& y, const real* dy,
                             real averStart, real* stddev)
{
    double sum = 0, sumVar = 0, w;
    double sumTail = 0, sum2Tail = 0;
    int    nsumTail = 0;
    for (int i = 0; i < n - 1; i++)
    {
        w = 0.5 * (x[i + 1] - x[i]);
        sum += w * (y[i] + y[i + 1]);
        if (dy)
        {
            sumVar += w * w * (dy[i] * dy[i] + dy[i + 1] * dy[i + 1]);
        }
        if (averStart > 0 && x[i] >= averStart)
        {
            sumTail += sum;
            sum2Tail += std::sqrt(sumVar);
            nsumTail += 1;
        }
    }
    if (nsumTail > 0)
    {
        sum     = sumTail / nsumTail;
        *stddev = sum2Tail / nsumTail;
    }
    else
    {
        *stddev = std::sqrt(sumVar);
    }
    return sum;
}

static void histogram(const std::string& fn, real binwidth, int n, int nset, const std::vector<std::vector<real>>& val,
                      XvgFormat fmt)
{
    real minval = val[0][0], maxval = val[0][0];
    for (int s = 0; s < nset; s++)
    {
        for (int i = 0; i < n; i++)
        {
            minval = std::min(minval, val[s][i]);
            maxval = std::max(maxval, val[s][i]);
        }
    }
    minval = binwidth * std::floor(minval / binwidth);
    maxval = binwidth * std::ceil(maxval / binwidth);
    if (minval != 0)
    {
        minval -= binwidth;
    }
    maxval += binwidth;
    int nbin = (int)std::rint((maxval - minval) / binwidth) + 1;
    printf("Making distributions with %d bins\n", nbin);
    std::vector<double> histo(nbin);
    FILE* fp = xvgrOpen(fn, "Distribution", "", "", fmt);
    for (int s = 0; s < nset; s++)
    {
        for (int i = 0; i < nbin; i++)
        {
            histo[i] = 0;
        }
        for (int i = 0; i < n; i++)
        {
            int b = (int)std::rint((val[s][i] - minval) / binwidth);
            if (b >= 0 && b < nbin)
            {
                histo[b]++;
            }
        }
        for (int i = 0; i < nbin; i++)
        {
            fprintf(fp, " %g  %g\n", minval + i * binwidth, histo[i] / (n * binwidth));
        }
        if (s < nset - 1)
        {
            fprintf(fp, "%s\n", fmt != XvgFormat::None ? "&" : "");
        }
    }
    xvgrClose(fp);
}

static void average(const std::string& fn, int avbarOpt, int n, int nset, const std::vector<std::vector<real>>& val,
                    const std::vector<real>& t)
{
    FILE* fp = openOutput(fn);
    if (avbarOpt == 1 || avbarOpt == 2)
    {
        fprintf(fp, "@TYPE xydy\n");
    }
    else if (avbarOpt == 3)
    {
        fprintf(fp, "@TYPE xydydy\n");
    }
    std::vector<real> tmp(nset);
    for (int i = 0; i < n; i++)
    {
        double av = 0;
        for (int s = 0; s < nset; s++)
        {
            av += val[s][i];
        }
        av /= nset;
        fprintf(fp, " %g %g", t[i], av);
        double var = 0;
        if (avbarOpt)
        {
            if (avbarOpt == 3)
            {
                for (int s = 0; s < nset; s++)
                {
                    tmp[s] = val[s][i];
                }
                std::sort(tmp.begin(), tmp.end());
                fprintf(fp, " %g %g", av - tmp[(int)(0.05 * nset)], tmp[(int)(0.95 * nset)] - av);
            }
            else
            {
                for (int s = 0; s < nset; s++)
                {
                    var += (val[s][i] - av) * (val[s][i] - av);
                }
                if (avbarOpt == 1)
                {
                    var /= nset;
                }
                else if (nset > 1)
                {
                    var /= (nset - 1) * nset;
                }
                fprintf(fp, " %g", std::sqrt(var));
            }
        }
        fprintf(fp, "\n");
    }
    fclose(fp);
}

static void regressionAnalysis(int n, bool bXYdy, const std::vector<real>& x, int nset,
                               const std::vector<std::vector<real>>& val)
{
    if (bXYdy || nset == 1)
    {
        printf("Fitting data to a function f(x) = ax + b\n");
        printf("Minimizing residual chi2 = Sum_i w_i [f(x_i) - y_i]2\n");
        printf("Error estimates will be given if w_i (sigma) values are given\n");
        printf("(use option -xydy).\n\n");
        double sx = 0, sy = 0, sxx = 0, sxy = 0, syy = 0, sw = 0;
        for (int i = 0; i < n; i++)
        {
            double w  = 1;
            if (bXYdy && nset > 1)
            {
                double dy = val[1][i];
                w         = dy != 0 ? 1.0 / (dy * dy) : 1.0;
            }
            double xi = x[i], yi = val[0][i];
            sw += w;
            sx += w * xi;
            sy += w * yi;
            sxx += w * xi * xi;
            sxy += w * xi * yi;
            syy += w * yi * yi;
        }
        double xbar = sx / sw, ybar = sy / sw;
        double sxx2 = sxx - sw * xbar * xbar;
        double sxy2 = sxy - sw * xbar * ybar;
        double syy2 = syy - sw * ybar * ybar;
        double a    = sxy2 / sxx2;
        double b    = ybar - a * xbar;
        double res  = 0;
        for (int i = 0; i < n; i++)
        {
            double d = val[0][i] - (a * x[i] + b);
            res += d * d;
        }
        double r     = sxy2 / std::sqrt(sxx2 * syy2);
        double chi2  = res * (n - 2);
        printf("Chi2                    = %g\n", chi2);
        printf("S (Sqrt(Chi2/(n-2))     = %g\n", std::sqrt(res / (n - 2)));
        printf("Correlation coefficient = %.1f%%\n\n", 100 * r);
        if (bXYdy)
        {
            double da = std::sqrt(1.0 / sxx2);
            double db = std::sqrt(1.0 / sw + xbar * xbar / sxx2);
            printf("a    = %g +/- %g\n", a, da);
            printf("b    = %g +/- %g\n", b, db);
        }
        else
        {
            printf("a    = %g\n", a);
            printf("b    = %g\n", b);
        }
    }
    else
    {
        int nx = nset - 1;
        printf("Fitting %d data points in %d sets\n", n, nx);
        // normal equations
        std::vector<std::vector<double>> M(nx, std::vector<double>(nx + 1, 0));
        for (int j = 0; j < nx; j++)
        {
            for (int k = 0; k < nx; k++)
            {
                for (int i = 0; i < n; i++)
                {
                    M[j][k] += (double)val[j + 1][i] * val[k + 1][i];
                }
            }
            for (int i = 0; i < n; i++)
            {
                M[j][nx] += (double)val[j + 1][i] * val[0][i];
            }
        }
        for (int c = 0; c < nx; c++)
        {
            int piv = c;
            for (int r = c + 1; r < nx; r++)
            {
                if (std::fabs(M[r][c]) > std::fabs(M[piv][c]))
                {
                    piv = r;
                }
            }
            std::swap(M[c], M[piv]);
            for (int r = 0; r < nx; r++)
            {
                if (r != c && M[c][c] != 0)
                {
                    double f = M[r][c] / M[c][c];
                    for (int k = c; k <= nx; k++)
                    {
                        M[r][k] -= f * M[c][k];
                    }
                }
            }
        }
        std::vector<double> A(nx);
        for (int j = 0; j < nx; j++)
        {
            A[j] = M[j][j] != 0 ? M[j][nx] / M[j][j] : 0;
        }
        double chi2 = 0;
        for (int i = 0; i < n; i++)
        {
            double f = 0;
            for (int j = 0; j < nx; j++)
            {
                f += A[j] * val[j + 1][i];
            }
            chi2 += (val[0][i] - f) * (val[0][i] - f);
        }
        printf("chi2 = %g\n", chi2);
        printf("A = ");
        for (int j = 0; j < nx; j++)
        {
            printf("  %g", A[j]);
        }
        printf("\n");
    }
}

int runAnalyze(Options& opts)
{
    bool   bHaveT = opts.getBool("time");
    double tb     = opts.getReal("b");
    double te     = opts.getReal("e");
    int    nsetsIn = opts.getInt("n");
    bool   bDer    = opts.getBool("d");
    real   binwidth = (real)opts.getReal("bw");
    bool   bIntegrate = opts.getBool("integrate");
    real   averStart  = (real)opts.getReal("aver_start");
    bool   bXYdy      = opts.getBool("xydy");
    bool   bRegression = opts.getBool("regression");
    std::string errbar = opts.getEnum("errbar");
    int avbarOpt = errbar == "stddev" ? 1 : errbar == "error" ? 2 : errbar == "90" ? 3 : 0;
    XvgFormat fmt = xvgFormatFromOptions(opts);

    if (nsetsIn < 1)
    {
        gmx_fatal("src/gromacs/gmxana/gmx_analyze.cpp", 1180, "Must have nsets >= 1");
    }

    XvgData d;
    readXvgTime(opts.fileName("f"), bHaveT, opts.isSet("b"), tb, opts.isSet("e"), te, nsetsIn, d);
    int n    = d.n;
    int nset = d.nset;
    std::vector<std::vector<real>> val(nset, std::vector<real>(n));
    for (int s = 0; s < nset; s++)
    {
        for (int i = 0; i < n; i++)
        {
            val[s][i] = (real)d.val[s][i];
        }
    }
    std::vector<real> t(n);
    for (int i = 0; i < n; i++)
    {
        t[i] = (real)d.t[i];
    }
    real dt = (real)d.dt;
    printf("Read %d sets of %d points, dt = %g\n\n", nset, n, dt);

    if (bDer)
    {
        int d2 = 1;
        printf("Calculating the derivative as (f[i+%d]-f[i])/(%d*dt)\n\n", d2, d2);
        n -= d2;
        for (int s = 0; s < nset; s++)
        {
            for (int i = 0; i < n; i++)
            {
                val[s][i] = (val[s][i + d2] - val[s][i]) / (d2 * dt);
            }
        }
    }
    if (bIntegrate)
    {
        printf("Calculating the integral using the trapezium rule\n");
        if (bXYdy)
        {
            real stddev;
            real sum = evaluateIntegral(n, t, val[0], nset > 1 ? val[1].data() : nullptr, averStart, &stddev);
            printf("Integral %10.6f +/- %10.5f\n", sum, stddev);
        }
        else
        {
            for (int s = 0; s < nset; s++)
            {
                real stddev;
                real sum = evaluateIntegral(n, t, val[s], nullptr, averStart, &stddev);
                printf("Integral %d  %10.5f  +/-  %10.5f\n", s + 1, sum, stddev);
            }
        }
    }
    printStats(n, nset, val);

    if (opts.isSet("dist") && nset > 0 && n > 0)
    {
        histogram(opts.fileName("dist"), binwidth, n, nset, val, fmt);
    }
    if (opts.isSet("av"))
    {
        average(opts.fileName("av"), avbarOpt, n, nset, val, t);
    }
    if (bRegression)
    {
        regressionAnalysis(n, bXYdy, t, nset, val);
    }
    return 0;
}

} // namespace gmx
