cat > /workspace/src/toolcommon.cpp <<'EOF'
#include "toolcommon.h"

namespace gmx
{

static std::map<std::string, std::string> g_resTypes;
static bool                               g_resTypesLoaded = false;

void requireResidueTypes()
{
    if (g_resTypesLoaded)
    {
        return;
    }
    std::string fn = libSearchFile("residuetypes.dat", true);
    FILE*       fp = fopen(fn.c_str(), "r");
    if (fp)
    {
        char line[1024];
        while (fgets(line, sizeof(line), fp))
        {
            char a[256], b[256];
            if (sscanf(line, "%255s %255s", a, b) == 2)
            {
                if (!g_resTypes.count(a))
                {
                    g_resTypes[a] = b;
                }
            }
        }
        fclose(fp);
    }
    g_resTypesLoaded = true;
}

std::string residueTypeOf(const std::string& resname)
{
    for (const auto& kv : g_resTypes)
    {
        if (strcasecmp(kv.first.c_str(), resname.c_str()) == 0)
        {
            return kv.second;
        }
    }
    return "Other";
}

void readTprFail(const std::string& fn)
