// Selection language subset implementation.
#include "selection.h"

#include <algorithm>

namespace gmx
{

struct NumNode;
struct PosNode;

struct SelNode
{
    enum Kind
    {
        All,
        None,
        IntKw,   // integer keyword with ranges (atomnr)
        RealKw,  // real keyword with ranges (x, y, z)
        Cmp,
        And,
        Or,
        Not,
        Within,
        Group,
        Var,
        Pos,     // position expression used as selection
        SolidAngle,
        TopKw    // keyword requiring topology
    } kind = All;
    std::string                          kw;
    std::vector<std::pair<double, double>> ranges;
    std::shared_ptr<NumNode>             l, r;
    std::string                          op;
    std::shared_ptr<SelNode>             a, b;
    double                               cutoff = 0;
    std::shared_ptr<PosNode>             pos, pos2;
    std::string                          group;
    int                                  groupNr = -1;
};

struct NumNode
{
    enum Kind
    {
        Const,
        Kw,
        Bin,
        Neg,
        Dist,
        MinDist
    } kind = Const;
    double                   c = 0;
    std::string              kw;
    char                     op = 0;
    std::shared_ptr<NumNode> a, b;
    std::shared_ptr<PosNode> pos;
    double                   cutoff = 0;
};

struct PosNode
{
    enum Kind
    {
        Const,
        Cog,
        Com,
        Atoms // atom selection as positions
    } kind = Const;
    RVec                     c = { 0, 0, 0 };
    std::shared_ptr<SelNode> sel;
    bool                     pbc = false;
};

// ---------------------------------------------------------------------------
// Tokenizer

struct Token
{
    enum Type
    {
        Int,
        Real,
        Str,
        Ident,
        Op,
        Sep, // ';' or newline
        End
    } type = End;
    std::string text;
    double      num        = 0;
    bool        spaceBefore = false;
    size_t      pos        = 0;
};

static std::vector<Token> tokenize(const std::string& s)
{
    std::vector<Token> toks;
    size_t             i  = 0;
    bool               sp = false;
    while (i < s.size())
    {
        char c = s[i];
        if (c == '\n')
        {
            Token t;
            t.type        = Token::Sep;
            t.text        = "\n";
            t.spaceBefore = sp;
            t.pos         = i;
            toks.push_back(t);
            sp = false;
            i++;
            continue;
        }
        if (isspace((unsigned char)c))
        {
            sp = true;
            i++;
            continue;
        }
        Token t;
        t.spaceBefore = sp;
        t.pos         = i;
        sp            = false;
        if (isdigit((unsigned char)c) || (c == '.' && i + 1 < s.size() && isdigit((unsigned char)s[i + 1])))
        {
            size_t j    = i;
            bool   real = false;
            while (j < s.size() && isdigit((unsigned char)s[j]))
            {
                j++;
            }
            if (j < s.size() && s[j] == '.')
            {
                real = true;
                j++;
                while (j < s.size() && isdigit((unsigned char)s[j]))
                {
                    j++;
                }
            }
            if (j < s.size() && (s[j] == 'e' || s[j] == 'E'))
            {
                size_t k = j + 1;
                if (k < s.size() && (s[k] == '+' || s[k] == '-'))
                {
                    k++;
                }
                if (k < s.size() && isdigit((unsigned char)s[k]))
                {
                    real = true;
                    j    = k;
                    while (j < s.size() && isdigit((unsigned char)s[j]))
                    {
                        j++;
                    }
                }
            }
            t.text = s.substr(i, j - i);
            t.type = real ? Token::Real : Token::Int;
            t.num  = strtod(t.text.c_str(), nullptr);
            i      = j;
        }
        else if (isalpha((unsigned char)c) || c == '_')
        {
            size_t j = i;
            while (j < s.size() && (isalnum((unsigned char)s[j]) || s[j] == '_' || s[j] == '\''))
            {
                j++;
            }
            t.text = s.substr(i, j - i);
            t.type = Token::Ident;
            i      = j;
        }
        else if (c == '"')
        {
            size_t j = i + 1;
            while (j < s.size() && s[j] != '"')
            {
                j++;
            }
            t.text = s.substr(i + 1, j - i - 1);
            t.type = Token::Str;
            i      = j < s.size() ? j + 1 : j;
        }
        else if (c == ';')
        {
            t.type = Token::Sep;
            t.text = ";";
            i++;
        }
        else
        {
            std::string two = s.substr(i, 2);
            if (two == "<=" || two == ">=" || two == "==" || two == "!=")
            {
                t.text = two;
                i += 2;
            }
            else
            {
                t.text = std::string(1, c);
                i++;
            }
            t.type = Token::Op;
        }
        toks.push_back(t);
    }
    Token e;
    e.type        = Token::End;
    e.spaceBefore = sp;
    e.pos         = s.size();
    toks.push_back(e);
    return toks;
}

// ---------------------------------------------------------------------------
// Parser

static const char* kTopKeywords[] = { "name",     "atomname", "pdbatomname", "pdbname", "type",  "atomtype",
                                      "resname",  "resnr",    "resid",       "resindex", "residue", "mol",
                                      "molecule", "molindex", "mass",        "charge",   "chain",   "insertcode",
                                      "altloc",   "occupancy", "beta",       "betafactor", "res_com", "res_cog",
                                      "mol_com",  "mol_cog",  "whole_res_com", "whole_res_cog", "whole_mol_com",
                                      "whole_mol_cog", "part_res_com", "part_res_cog", "part_mol_com",
                                      "part_mol_cog", "dyn_res_com", "dyn_res_cog", "dyn_mol_com", "dyn_mol_cog",
                                      "same", nullptr };

static bool isTopKeyword(const std::string& s)
{
    for (int i = 0; kTopKeywords[i]; i++)
    {
        if (s == kTopKeywords[i])
        {
            return true;
        }
    }
    return false;
}

class Parser
{
public:
    Parser(const std::vector<Token>& t, SelectionCollection& sc) : toks(t), sc_(sc) {}
    const std::vector<Token>& toks;
    size_t                    p = 0;
    SelectionCollection&      sc_;
    bool                      dynamic  = false;
    bool                      needsTop = false;

    const Token& cur() const { return toks[p]; }
    bool isIdent(const char* s) const { return cur().type == Token::Ident && cur().text == s; }
    bool isOp(const char* s) const { return cur().type == Token::Op && cur().text == s; }

    [[noreturn]] void error() const
    {
        SelSyntaxError e;
        e.near    = cur().type == Token::End ? "" : cur().text;
        e.message = "syntax error";
        throw e;
    }

    bool atSelEnd() const
    {
        return cur().type == Token::End || cur().type == Token::Sep || isOp(")") || isOp(",") || isOp("]")
               || isIdent("and") || isIdent("or") || isIdent("of") || isIdent("pbc") || isIdent("span")
               || isIdent("cutoff");
    }

    std::shared_ptr<SelNode> parseSel() { return parseOr(); }

    std::shared_ptr<SelNode> parseOr()
    {
        auto a = parseAnd();
        while (isIdent("or"))
        {
            p++;
            auto b = parseAnd();
            auto n = std::make_shared<SelNode>();
            n->kind = SelNode::Or;
            n->a    = a;
            n->b    = b;
            a       = n;
        }
        return a;
    }

    std::shared_ptr<SelNode> parseAnd()
    {
        auto a = parseNot();
        while (isIdent("and"))
        {
            p++;
            auto b = parseNot();
            auto n = std::make_shared<SelNode>();
            n->kind = SelNode::And;
            n->a    = a;
            n->b    = b;
            a       = n;
        }
        return a;
    }

    std::shared_ptr<SelNode> parseNot()
    {
        if (isIdent("not"))
        {
            p++;
            auto a  = parseNot();
            auto n  = std::make_shared<SelNode>();
            n->kind = SelNode::Not;
            n->a    = a;
            return n;
        }
        return parsePrimary();
    }

    bool numStartsHere() const
    {
        const Token& t = cur();
        if (t.type == Token::Int || t.type == Token::Real)
        {
            return true;
        }
        if (t.type == Token::Op && (t.text == "-" || t.text == "("))
        {
            return true;
        }
        if (t.type == Token::Ident
            && (t.text == "x" || t.text == "y" || t.text == "z" || t.text == "distance" || t.text == "dist"
                || t.text == "mindistance" || t.text == "mindist" || t.text == "atomnr"))
        {
            return true;
        }
        return false;
    }

    bool isCmpOp() const
    {
        return cur().type == Token::Op
               && (cur().text == "<" || cur().text == ">" || cur().text == "<=" || cur().text == ">="
                   || cur().text == "==" || cur().text == "!=");
    }

    std::shared_ptr<SelNode> parsePrimary()
    {
        const Token& t = cur();
        if (isOp("("))
        {
            // could be a parenthesized selection or numeric expression
            size_t save = p;
            p++;
            try
            {
                auto s = parseSel();
                if (!isOp(")"))
                {
                    error();
                }
                p++;
                if (!isCmpOp() && !isOp("+") && !isOp("-") && !isOp("*") && !isOp("/") && !isOp("^"))
                {
                    return s;
                }
            }
            catch (const SelSyntaxError&)
            {
            }
            p = save;
            return parseComparison();
        }
        if (t.type == Token::Ident)
        {
            const std::string& w = t.text;
            if (w == "all")
            {
                p++;
                auto n  = std::make_shared<SelNode>();
                n->kind = SelNode::All;
                return n;
            }
            if (w == "none")
            {
                p++;
                auto n  = std::make_shared<SelNode>();
                n->kind = SelNode::None;
                return n;
            }
            if (w == "atomnr")
            {
                // either an integer list, or a numeric expression in comparison
                size_t save = p;
                p++;
                if (cur().type == Token::Int)
                {
                    auto n  = std::make_shared<SelNode>();
                    n->kind = SelNode::IntKw;
                    n->kw   = "atomnr";
                    parseRanges(n->ranges, true);
                    return n;
                }
                p = save;
                return parseComparison();
            }
            if (w == "x" || w == "y" || w == "z")
            {
                size_t save = p;
                p++;
                if (cur().type == Token::Int || cur().type == Token::Real)
                {
                    auto n  = std::make_shared<SelNode>();
                    n->kind = SelNode::RealKw;
                    n->kw   = w;
                    parseRanges(n->ranges, false);
                    dynamic = true;
                    return n;
                }
                p = save;
                return parseComparison();
            }
            if (w == "within")
            {
                p++;
                double r = parseNumberConst();
                if (!isIdent("of"))
                {
                    error();
                }
                p++;
                auto n    = std::make_shared<SelNode>();
                n->kind   = SelNode::Within;
                n->cutoff = r;
                n->pos    = parsePosExpr();
                dynamic   = true;
                return n;
            }
            if (w == "insolidangle")
            {
                p++;
                if (!isIdent("center"))
                {
                    error();
                }
                p++;
                auto n  = std::make_shared<SelNode>();
                n->kind = SelNode::SolidAngle;
                n->pos  = parsePosExpr();
                if (!isIdent("span"))
                {
                    error();
                }
                p++;
                n->pos2   = parsePosExpr();
                n->cutoff = 5;
                if (isIdent("cutoff"))
                {
                    p++;
                    n->cutoff = parseNumberConst();
                }
                dynamic = true;
                return n;
            }
            if (w == "distance" || w == "dist" || w == "mindistance" || w == "mindist")
            {
                return parseComparison();
            }
            if (w == "cog" || w == "com" || isOp("["))
            {
                auto n  = std::make_shared<SelNode>();
                n->kind = SelNode::Pos;
                n->pos  = parsePosExpr();
                return n;
            }
            if (w == "group")
            {
                p++;
                auto n  = std::make_shared<SelNode>();
                n->kind = SelNode::Group;
                if (cur().type == Token::Int)
                {
                    n->groupNr = (int)cur().num;
                    p++;
                }
                else if (cur().type == Token::Str || cur().type == Token::Ident)
                {
                    n->group = cur().text;
                    p++;
                }
                else
                {
                    error();
                }
                sc_.hasGroupRefs = true;
                return n;
            }
            if (isTopKeyword(w))
            {
                needsTop = true;
                p++;
                // consume arguments until selection end
                while (!atSelEnd() && !isIdent("as"))
                {
                    p++;
                }
                if (isIdent("as"))
                {
                    p++;
                    parseSel();
                }
                auto n  = std::make_shared<SelNode>();
                n->kind = SelNode::TopKw;
                n->kw   = w;
                return n;
            }
            auto vit = sc_.variables.find(w);
            if (vit != sc_.variables.end())
            {
                p++;
                auto n  = std::make_shared<SelNode>();
                n->kind = SelNode::Var;
                n->a    = vit->second;
                return n;
            }
            // reserved words that can't start a selection
            if (w == "and" || w == "or" || w == "of" || w == "to" || w == "xor" || w == "as" || w == "pbc")
            {
                error();
            }
            // index group reference by name
            p++;
            auto n           = std::make_shared<SelNode>();
            n->kind          = SelNode::Group;
            n->group         = w;
            sc_.hasGroupRefs = true;
            return n;
        }
        if (t.type == Token::Str)
        {
            p++;
            auto n           = std::make_shared<SelNode>();
            n->kind          = SelNode::Group;
            n->group         = t.text;
            sc_.hasGroupRefs = true;
            return n;
        }
        if (t.type == Token::Int || t.type == Token::Real || isOp("-"))
        {
            if (t.type == Token::Int)
            {
                // could be a group number
                size_t save = p;
                p++;
                if (atSelEnd())
                {
                    auto n           = std::make_shared<SelNode>();
                    n->kind          = SelNode::Group;
                    n->groupNr       = (int)t.num;
                    sc_.hasGroupRefs = true;
                    return n;
                }
                p = save;
            }
            return parseComparison();
        }
        if (isOp("["))
        {
            auto n  = std::make_shared<SelNode>();
            n->kind = SelNode::Pos;
            n->pos  = parsePosExpr();
            return n;
        }
        error();
    }

    void parseRanges(std::vector<std::pair<double, double>>& ranges, bool intOnly)
    {
        while (cur().type == Token::Int || (!intOnly && cur().type == Token::Real))
        {
            double a = cur().num;
            p++;
            double b = a;
            if (isIdent("to"))
            {
                p++;
                if (cur().type == Token::Int || (!intOnly && cur().type == Token::Real))
                {
                    b = cur().num;
                    p++;
                }
                else
                {
                    error();
                }
            }
            if (a > b)
            {
                std::swap(a, b);
            }
            ranges.emplace_back(a, b);
        }
    }

    double parseNumberConst()
    {
        bool neg = false;
        if (isOp("-"))
        {
            neg = true;
            p++;
        }
        if (cur().type != Token::Int && cur().type != Token::Real)
        {
            error();
        }
        double v = cur().num;
        p++;
        return neg ? -v : v;
    }

    std::shared_ptr<SelNode> parseComparison()
    {
        auto l = parseNumExpr();
        if (!isCmpOp())
        {
            error();
        }
        std::string op = cur().text;
        p++;
        auto r  = parseNumExpr();
        auto n  = std::make_shared<SelNode>();
        n->kind = SelNode::Cmp;
        n->l    = l;
        n->r    = r;
        n->op   = op;
        return n;
    }

    std::shared_ptr<NumNode> parseNumExpr() { return parseAdd(); }

    std::shared_ptr<NumNode> parseAdd()
    {
        auto a = parseMul();
        while (isOp("+") || isOp("-"))
        {
            char op = cur().text[0];
            p++;
            auto b  = parseMul();
            auto n  = std::make_shared<NumNode>();
            n->kind = NumNode::Bin;
            n->op   = op;
            n->a    = a;
            n->b    = b;
            a       = n;
        }
        return a;
    }

    std::shared_ptr<NumNode> parseMul()
    {
        auto a = parseUnary();
        while (isOp("*") || isOp("/"))
        {
            char op = cur().text[0];
            p++;
            auto b  = parseUnary();
            auto n  = std::make_shared<NumNode>();
            n->kind = NumNode::Bin;
            n->op   = op;
            n->a    = a;
            n->b    = b;
            a       = n;
        }
        return a;
    }

    std::shared_ptr<NumNode> parseUnary()
    {
        if (isOp("-"))
        {
            p++;
            auto a  = parseUnary();
            auto n  = std::make_shared<NumNode>();
            n->kind = NumNode::Neg;
            n->a    = a;
            return n;
        }
        return parsePow();
    }

    std::shared_ptr<NumNode> parsePow()
    {
        auto a = parseNumPrimary();
        if (isOp("^"))
        {
            p++;
            auto b  = parseUnary();
            auto n  = std::make_shared<NumNode>();
            n->kind = NumNode::Bin;
            n->op   = '^';
            n->a    = a;
            n->b    = b;
            return n;
        }
        return a;
    }

    std::shared_ptr<NumNode> parseNumPrimary()
    {
        const Token& t = cur();
        if (t.type == Token::Int || t.type == Token::Real)
        {
            p++;
            auto n  = std::make_shared<NumNode>();
            n->kind = NumNode::Const;
            n->c    = t.num;
            return n;
        }
        if (isOp("("))
        {
            p++;
            auto n = parseNumExpr();
            if (!isOp(")"))
            {
                error();
            }
            p++;
            return n;
        }
        if (t.type == Token::Ident)
        {
            if (t.text == "x" || t.text == "y" || t.text == "z" || t.text == "atomnr")
            {
                p++;
                auto n  = std::make_shared<NumNode>();
                n->kind = NumNode::Kw;
                n->kw   = t.text;
                if (t.text != "atomnr")
                {
                    dynamic = true;
                }
                return n;
            }
            if (t.text == "distance" || t.text == "dist" || t.text == "mindistance" || t.text == "mindist")
            {
                bool minD = t.text[0] == 'm';
                p++;
                if (!isIdent("from"))
                {
                    error();
                }
                p++;
                auto n    = std::make_shared<NumNode>();
                n->kind   = minD ? NumNode::MinDist : NumNode::Dist;
                n->pos    = parsePosExpr();
                n->cutoff = 0;
                if (isIdent("cutoff"))
                {
                    p++;
                    n->cutoff = parseNumberConst();
                }
                dynamic = true;
                return n;
            }
            if (isTopKeyword(t.text))
            {
                needsTop = true;
                p++;
                auto n  = std::make_shared<NumNode>();
                n->kind = NumNode::Const;
                return n;
            }
        }
        error();
    }

    std::shared_ptr<PosNode> parsePosExpr()
    {
        if (isOp("["))
        {
            p++;
            auto n  = std::make_shared<PosNode>();
            n->kind = PosNode::Const;
            for (int d = 0; d < 3; d++)
            {
                n->c[d] = (real)parseNumberConst();
                if (d < 2)
                {
                    if (!isOp(","))
                    {
                        error();
                    }
                    p++;
                }
            }
            if (!isOp("]"))
            {
                error();
            }
            p++;
            return n;
        }
        if (isIdent("cog") || isIdent("com"))
        {
            bool com = cur().text == "com";
            p++;
            if (!isIdent("of"))
            {
                error();
            }
            p++;
            auto n  = std::make_shared<PosNode>();
            n->kind = com ? PosNode::Com : PosNode::Cog;
            n->sel  = parseNot();
            if (isIdent("pbc"))
            {
                p++;
                n->pbc = true;
            }
            if (com)
            {
                needsTop = true;
            }
            return n;
        }
        auto n  = std::make_shared<PosNode>();
        n->kind = PosNode::Atoms;
        n->sel  = parseNot();
        return n;
    }
};

// ---------------------------------------------------------------------------
// Evaluation

struct EvalState
{
    const SelEvalContext&       ctx;
    const SelectionCollection&  sc;
};

static void pbcDx(const SelEvalContext& ctx, const RVec& a, const RVec& b, double dx[3])
{
    for (int d = 0; d < 3; d++)
    {
        dx[d] = (double)a[d] - b[d];
    }
    if (!ctx.pbc || boxIsZero(ctx.box))
    {
        return;
    }
    for (int d = 2; d >= 0; d--)
    {
        double bl = ctx.box[d][d];
        if (bl <= 0)
        {
            continue;
        }
        while (dx[d] > 0.5 * bl)
        {
            for (int e = 0; e <= d; e++)
            {
                dx[e] -= ctx.box[d][e];
            }
        }
        while (dx[d] <= -0.5 * bl)
        {
            for (int e = 0; e <= d; e++)
            {
                dx[e] += ctx.box[d][e];
            }
        }
    }
}

static double dist2(const SelEvalContext& ctx, const RVec& a, const RVec& b)
{
    double dx[3];
    pbcDx(ctx, a, b, dx);
    return dx[0] * dx[0] + dx[1] * dx[1] + dx[2] * dx[2];
}

static std::vector<char> evalSel(const SelNode& n, const EvalState& st);

static std::vector<RVec> evalPos(const PosNode& n, const EvalState& st)
{
    std::vector<RVec> out;
    const auto&       x = *st.ctx.x;
    switch (n.kind)
    {
        case PosNode::Const: out.push_back(n.c); break;
        case PosNode::Cog:
        case PosNode::Com:
        {
            auto   m = evalSel(*n.sel, st);
            double c[3] = { 0, 0, 0 };
            int    cnt  = 0;
            for (int i = 0; i < st.ctx.natoms; i++)
            {
                if (m[i])
                {
                    for (int d = 0; d < 3; d++)
                    {
                        c[d] += x[i][d];
                    }
                    cnt++;
                }
            }
            if (cnt > 0)
            {
                out.push_back(RVec{ (real)(c[0] / cnt), (real)(c[1] / cnt), (real)(c[2] / cnt) });
            }
            break;
        }
        case PosNode::Atoms:
        {
            auto m = evalSel(*n.sel, st);
            for (int i = 0; i < st.ctx.natoms; i++)
            {
                if (m[i])
                {
                    out.push_back(x[i]);
                }
            }
            break;
        }
    }
    return out;
}

static double evalNum(const NumNode& n, const EvalState& st, int i, const std::vector<RVec>* cache)
{
    const auto& x = *st.ctx.x;
    switch (n.kind)
    {
        case NumNode::Const: return n.c;
        case NumNode::Kw:
            if (n.kw == "x") return x[i][0];
            if (n.kw == "y") return x[i][1];
            if (n.kw == "z") return x[i][2];
            if (n.kw == "atomnr") return i + 1;
            return 0;
        case NumNode::Neg: return -evalNum(*n.a, st, i, cache);
        case NumNode::Bin:
        {
            double a = evalNum(*n.a, st, i, cache), b = evalNum(*n.b, st, i, cache);
            switch (n.op)
            {
                case '+': return a + b;
                case '-': return a - b;
                case '*': return a * b;
                case '/': return a / b;
                case '^': return std::pow(a, b);
            }
            return 0;
        }
        case NumNode::Dist:
        case NumNode::MinDist:
        {
            std::vector<RVec> ps = evalPos(*n.pos, st);
            double            best = -1;
            for (const auto& pp : ps)
            {
                double d = std::sqrt(dist2(st.ctx, x[i], pp));
                if (best < 0 || d < best)
                {
                    best = d;
                }
            }
            if (n.cutoff > 0 && best > n.cutoff)
            {
                best = n.cutoff;
            }
            return best < 0 ? 0 : best;
        }
    }
    return 0;
}

static const IndexGroup* findGroup(const SelectionCollection& sc, const SelNode& n)
{
    if (n.groupNr >= 0)
    {
        if (n.groupNr < (int)sc.groups.size())
        {
            return &sc.groups[n.groupNr];
        }
        return nullptr;
    }
    for (const auto& g : sc.groups)
    {
        if (g.name == n.group)
        {
            return &g;
        }
    }
    for (const auto& g : sc.groups)
    {
        if (strcasecmp(g.name.c_str(), n.group.c_str()) == 0)
        {
            return &g;
        }
    }
    const IndexGroup* found = nullptr;
    int               nf    = 0;
    for (const auto& g : sc.groups)
    {
        if (strncasecmp(g.name.c_str(), n.group.c_str(), n.group.size()) == 0)
        {
            found = &g;
            nf++;
        }
    }
    return nf == 1 ? found : nullptr;
}

static std::vector<char> evalSel(const SelNode& n, const EvalState& st)
{
    int               N = st.ctx.natoms;
    std::vector<char> m(N, 0);
    switch (n.kind)
    {
        case SelNode::All: std::fill(m.begin(), m.end(), 1); break;
        case SelNode::None: break;
        case SelNode::IntKw:
            for (int i = 0; i < N; i++)
            {
                for (const auto& r : n.ranges)
                {
                    if (i + 1 >= r.first && i + 1 <= r.second)
                    {
                        m[i] = 1;
                    }
                }
            }
            break;
        case SelNode::RealKw:
        {
            int d = n.kw == "x" ? 0 : n.kw == "y" ? 1 : 2;
            for (int i = 0; i < N; i++)
            {
                double v = (*st.ctx.x)[i][d];
                for (const auto& r : n.ranges)
                {
                    if (v >= r.first && v <= r.second)
                    {
                        m[i] = 1;
                    }
                }
            }
            break;
        }
        case SelNode::Cmp:
            for (int i = 0; i < N; i++)
            {
                double a = evalNum(*n.l, st, i, nullptr), b = evalNum(*n.r, st, i, nullptr);
                bool   r = false;
                if (n.op == "<") r = a < b;
                else if (n.op == ">") r = a > b;
                else if (n.op == "<=") r = a <= b;
                else if (n.op == ">=") r = a >= b;
                else if (n.op == "==") r = a == b;
                else if (n.op == "!=") r = a != b;
                m[i] = r;
            }
            break;
        case SelNode::And:
        {
            auto a = evalSel(*n.a, st), b = evalSel(*n.b, st);
            for (int i = 0; i < N; i++)
            {
                m[i] = a[i] && b[i];
            }
            break;
        }
        case SelNode::Or:
        {
            auto a = evalSel(*n.a, st), b = evalSel(*n.b, st);
            for (int i = 0; i < N; i++)
            {
                m[i] = a[i] || b[i];
            }
            break;
        }
        case SelNode::Not:
        {
            auto a = evalSel(*n.a, st);
            for (int i = 0; i < N; i++)
            {
                m[i] = !a[i];
            }
            break;
        }
        case SelNode::Within:
        {
            auto   ps = evalPos(*n.pos, st);
            double r2 = n.cutoff * n.cutoff;
            for (int i = 0; i < N; i++)
            {
                for (const auto& pp : ps)
                {
                    if (dist2(st.ctx, (*st.ctx.x)[i], pp) <= r2)
                    {
                        m[i] = 1;
                        break;
                    }
                }
            }
            break;
        }
        case SelNode::SolidAngle:
        {
            auto   c     = evalPos(*n.pos, st);
            auto   span  = evalPos(*n.pos2, st);
            double cosc  = std::cos(n.cutoff * M_PI / 180.0);
            if (c.empty())
            {
                break;
            }
            for (int i = 0; i < N; i++)
            {
                double dx[3];
                pbcDx(st.ctx, (*st.ctx.x)[i], c[0], dx);
                double l = std::sqrt(dx[0] * dx[0] + dx[1] * dx[1] + dx[2] * dx[2]);
                for (const auto& sp : span)
                {
                    double dy[3];
                    pbcDx(st.ctx, sp, c[0], dy);
                    double l2 = std::sqrt(dy[0] * dy[0] + dy[1] * dy[1] + dy[2] * dy[2]);
                    if (l > 0 && l2 > 0)
                    {
                        double cs = (dx[0] * dy[0] + dx[1] * dy[1] + dx[2] * dy[2]) / (l * l2);
                        if (cs >= cosc)
                        {
                            m[i] = 1;
                            break;
                        }
                    }
                }
            }
            break;
        }
        case SelNode::Group:
        {
            const IndexGroup* g = findGroup(st.sc, n);
            if (g)
            {
                for (int a : g->atoms)
                {
                    if (a >= 0 && a < N)
                    {
                        m[a] = 1;
                    }
                }
            }
            break;
        }
        case SelNode::Var: return evalSel(*n.a, st);
        case SelNode::Pos:
        {
            // atoms involved in the position computation
            if (n.pos->sel)
            {
                return evalSel(*n.pos->sel, st);
            }
            break;
        }
        case SelNode::TopKw: break;
    }
    return m;
}

static bool nodeUsesGroups(const SelNode* n)
{
    return false;
}

// ---------------------------------------------------------------------------

static std::string normalizeText(const std::vector<Token>& toks, size_t b, size_t e, const std::string& src,
                                 bool trailingSpace)
{
    std::string r;
    for (size_t i = b; i < e; i++)
    {
        const Token& t = toks[i];
        if (i > b && t.spaceBefore)
        {
            r += ' ';
        }
        // use the source text for the token
        size_t len = 0;
        if (i + 1 < toks.size())
        {
            // compute source span: from t.pos to next token pos minus whitespace
            size_t endPos = toks[i + 1].pos;
            while (endPos > t.pos && isspace((unsigned char)src[endPos - 1]))
            {
                endPos--;
            }
            len = endPos - t.pos;
        }
        r += src.substr(t.pos, len);
    }
    if (trailingSpace)
    {
        r += ' ';
    }
    return r;
}

std::vector<Selection> SelectionCollection::parse(const std::string& text, bool fromStdin)
{
    std::vector<Token>     toks = tokenize(text);
    std::vector<Selection> out;
    size_t                 p = 0;
    while (true)
    {
        while (toks[p].type == Token::Sep)
        {
            p++;
        }
        if (toks[p].type == Token::End)
        {
            break;
        }
        size_t start = p;
        Parser ps(toks, *this);
        ps.p = p;
        // variable assignment?
        if (toks[p].type == Token::Ident && toks[p + 1].type == Token::Op && toks[p + 1].text == "=")
        {
            std::string var = toks[p].text;
            ps.p            = p + 2;
            auto node       = ps.parseSel();
            if (ps.cur().type != Token::Sep && ps.cur().type != Token::End)
            {
                ps.error();
            }
            variables[var] = node;
            if (ps.needsTop)
            {
                requiresTopology = true;
            }
            p = ps.p;
            continue;
        }
        std::string customName;
        if (toks[p].type == Token::Str
            && (toks[p + 1].type != Token::Sep && toks[p + 1].type != Token::End))
        {
            customName = toks[p].text;
            ps.p       = p + 1;
            start      = p + 1;
        }
        auto node = ps.parseSel();
        if (ps.cur().type != Token::Sep && ps.cur().type != Token::End)
        {
            ps.error();
        }
        Selection sel;
        sel.root         = node;
        sel.dynamic      = ps.dynamic;
        sel.requiresTopology = ps.needsTop;
        if (ps.needsTop)
        {
            requiresTopology = true;
        }
        sel.isPositions = node->kind == SelNode::Pos;
        bool trailing   = ps.cur().type == Token::End ? toks[ps.p].spaceBefore
                                                      : (toks[ps.p].spaceBefore || toks[ps.p].text == "\n");
        if (ps.cur().type == Token::Sep && toks[ps.p].text == ";")
        {
            trailing = false;
        }
        sel.selText = normalizeText(toks, start, ps.p, text, trailing);
        sel.name    = customName.empty() ? sel.selText : customName;
        // dynamic if contains variable that is dynamic: approximated by checking variables
        out.push_back(sel);
        p = ps.p;
    }
    (void)fromStdin;
    return out;
}

void SelectionCollection::evaluate(Selection& sel, const SelEvalContext& ctx)
{
    EvalState st{ ctx, *this };
    sel.atoms.clear();
    sel.positions.clear();
    sel.posAtom.clear();
    if (sel.root->kind == SelNode::Pos)
    {
        sel.positions = evalPos(*sel.root->pos, st);
        auto m        = sel.root->pos->sel ? evalSel(*sel.root->pos->sel, st) : std::vector<char>();
        for (int i = 0; i < (int)m.size(); i++)
        {
            if (m[i])
            {
                sel.atoms.push_back(i);
            }
        }
        for (size_t k = 0; k < sel.positions.size(); k++)
        {
            sel.posAtom.push_back((int)k);
        }
        return;
    }
    auto m = evalSel(*sel.root, st);
    for (int i = 0; i < ctx.natoms; i++)
    {
        if (m[i])
        {
            sel.atoms.push_back(i);
            sel.positions.push_back((*ctx.x)[i]);
            sel.posAtom.push_back(i);
        }
    }
}

static void collectGroupRefs(const SelNode* n, std::vector<const SelNode*>& out)
{
    if (!n)
    {
        return;
    }
    if (n->kind == SelNode::Group)
    {
        out.push_back(n);
    }
    collectGroupRefs(n->a.get(), out);
    collectGroupRefs(n->b.get(), out);
    if (n->pos)
    {
        collectGroupRefs(n->pos->sel.get(), out);
    }
    if (n->pos2)
    {
        collectGroupRefs(n->pos2->sel.get(), out);
    }
    if (n->l && n->l->pos)
    {
        collectGroupRefs(n->l->pos->sel.get(), out);
    }
    if (n->r && n->r->pos)
    {
        collectGroupRefs(n->r->pos->sel.get(), out);
    }
}

void SelectionCollection::checkGroups(const std::vector<Selection>& sels)
{
    std::vector<const SelNode*> refs;
    for (const auto& s : sels)
    {
        collectGroupRefs(s.root.get(), refs);
    }
    for (const auto& kv : variables)
    {
        collectGroupRefs(kv.second.get(), refs);
    }
    GmxError e(ErrKind::InconsistentInput, "Invalid index group reference(s)",
               "src/gromacs/selection/selectioncollection.cpp", 702,
               "void gmx::SelectionCollection::setIndexGroups(gmx_ana_indexgrps_t*)");
    for (const SelNode* n : refs)
    {
        if (!findGroup(*this, *n))
        {
            ErrNode c;
            if (n->groupNr >= 0)
            {
                c.msg = formatStr("Cannot match 'group %d', because no such index group can be found.", n->groupNr);
            }
            else
            {
                c.msg = "Cannot match 'group \"" + n->group + "\"', because no such index group can be found.";
            }
            e.root.children.push_back(c);
        }
    }
    if (!e.root.children.empty())
    {
        throw e;
    }
}

