#include "trajectory.h"

namespace gmx
{

void printFrameProgress(const char* label, int frame, double t)
{
    const int skip1 = 10, skip2 = 100, skip3 = 1000;
    if ((frame < 2 * skip1 || frame % skip1 == 0) && (frame < 2 * skip2 || frame % skip2 == 0)
        && (frame < 2 * skip3 || frame % skip3 == 0))
    {
        fprintf(stderr, "\r%-14s %6d time %8.3f   ", label, frame, t);
        fflush(stderr);
    }
}

TrajectoryReader::TrajectoryReader(const std::string& fn) : fn_(fn), type_(fileTypeOf(fn))
{
    if (type_ == FileType::GRO || type_ == FileType::PDB || type_ == FileType::G96)
    {
        fp_ = fopen(fn.c_str(), "r");
        if (!fp_)
        {
            gmx_fatal("src/gromacs/utility/futil.cpp", 472, "Cannot open file '%s'", fn.c_str());
        }
    }
}

TrajectoryReader::~TrajectoryReader()
{
    if (fp_)
    {
        fclose(fp_);
    }
}

static bool readLineF(FILE* fp, std::string& line)
{
    line.clear();
    int  c;
    bool any = false;
    while ((c = fgetc(fp)) != EOF)
    {
        any = true;
        if (c == '\n')
        {
            break;
        }
        line += (char)c;
    }
    if (!line.empty() && line.back() == '\r')
    {
        line.pop_back();
    }
    return any;
}

static double parseTitleTime(const std::string& title, bool& found)
{
    size_t p = title.find("t=");
    found    = false;
    if (p == std::string::npos)
    {
        return 0;
    }
    found = true;
    return strtod(title.c_str() + p + 2, nullptr);
}

bool TrajectoryReader::readGroFrame(Frame& fr)
{
    // Reuse the structure reader on a temp in-memory approach: parse directly
    std::string title;
    if (!readLineF(fp_, title))
    {
        return false;
    }
    std::string nl;
    if (!readLineF(fp_, nl))
    {
        return false;
    }
    int natoms = 0;
    if (sscanf(nl.c_str(), "%d", &natoms) != 1)
    {
        gmx_fatal("src/gromacs/fileio/groio.cpp", 66, "gro file does not have the number of atoms on the second line");
    }
    Structure& s = fr.conf;
    s            = Structure();
    s.title      = trim(title);
    s.x.assign(natoms, RVec{ 0, 0, 0 });
    s.v.assign(natoms, RVec{ 0, 0, 0 });
    int         ddist = 8;
    bool        bVel  = false;
    int         prevResnr = -1;
    std::string prevResname, line;
    for (int i = 0; i < natoms; i++)
    {
        if (!readLineF(fp_, line))
        {
            gmx_fatal("src/gromacs/fileio/groio.cpp", 144, "Unexpected end of file in file %s at line %d", fn_.c_str(),
                      i + 2);
        }
        if (i == 0)
        {
            size_t p1 = line.find('.', 20);
            size_t p2 = p1 == std::string::npos ? std::string::npos : line.find('.', p1 + 1);
            if (p1 != std::string::npos && p2 != std::string::npos)
            {
                ddist = (int)(p2 - p1);
            }
        }
        std::string resname = line.size() > 5 ? trim(line.substr(5, 5)) : "";
        int         resnr   = atoi(line.substr(0, 5).c_str());
        if (i == 0 || resnr != prevResnr || resname != prevResname)
        {
            ResInfo r;
            r.name = resname;
            r.nr   = resnr;
            s.res.push_back(r);
            prevResnr   = resnr;
            prevResname = resname;
        }
        AtomInfo a;
        a.name   = line.size() > 10 ? trim(line.substr(10, 5)) : "";
        a.resind = (int)s.res.size() - 1;
        s.atoms.push_back(a);
        for (int d = 0; d < 3; d++)
        {
            size_t st = 20 + d * ddist;
            s.x[i][d] = st < line.size() ? (real)strtod(line.substr(st, ddist).c_str(), nullptr) : 0;
        }
        bool vok = true;
        for (int d = 0; d < 3; d++)
        {
            size_t st = 20 + 3 * ddist + d * ddist;
            if (st >= line.size())
            {
                vok = false;
                break;
            }
            s.v[i][d] = (real)strtod(line.substr(st, ddist).c_str(), nullptr);
        }
        if (i == 0)
        {
            bVel = vok;
        }
    }
    s.haveV = bVel;
    if (!readLineF(fp_, line))
    {
        gmx_fatal("src/gromacs/fileio/groio.cpp", 233, "Found an invalid box line or no box in file %s", fn_.c_str());
    }
    double b[9] = { 0 };
    int    n    = sscanf(line.c_str(), "%lf%lf%lf%lf%lf%lf%lf%lf%lf", &b[0], &b[1], &b[2], &b[3], &b[4], &b[5], &b[6],
                   &b[7], &b[8]);
    s.box[0][0] = b[0];
    s.box[1][1] = b[1];
    s.box[2][2] = b[2];
    if (n == 9)
    {
        s.box[0][1] = b[3];
        s.box[0][2] = b[4];
        s.box[1][0] = b[5];
        s.box[1][2] = b[6];
        s.box[2][0] = b[7];
        s.box[2][1] = b[8];
    }
    fr.title  = s.title;
    fr.natoms = natoms;
    fr.x      = s.x;
    fr.v      = s.v;
    fr.bV     = bVel;
    fr.bX     = true;
    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            fr.box[i][j] = s.box[i][j];
        }
    }
    fr.bBox  = true;
    bool tf  = false;
    fr.time  = parseTitleTime(s.title, tf);
    fr.bTime = tf;
    fr.prec  = std::pow(10.0, -(ddist - 5));
    fr.bPrec = true;
    return true;
}

bool TrajectoryReader::readPdbFrame(Frame& fr)
{
    // read until ENDMDL/END
    Structure&  s = fr.conf;
    s             = Structure();
    std::string line;
    bool        any = false;
    std::string prevKey;
    s.havePdb = true;
    s.pbcType = 0;
    while (readLineF(fp_, line))
    {
        std::string r6 = trim(line.substr(0, 6));
        if (r6 == "ATOM" || r6 == "HETATM")
        {
            any = true;
            char buf[128];
            memset(buf, 0, sizeof(buf));
            memcpy(buf, line.c_str(), std::min<size_t>(line.size(), 127));
            AtomInfo    a;
            a.name            = trim(std::string(buf + 12, 4));
            std::string rname = trim(std::string(buf + 17, 4));
            char        chain = buf[21] ? buf[21] : ' ';
            std::string rnr(buf + 22, 4);
            std::string key = rnr + "|" + rname + "|" + chain;
            if (s.res.empty() || key != prevKey)
            {
                ResInfo r;
                r.name  = rname;
                r.nr    = atoi(rnr.c_str());
                r.chain = chain;
                s.res.push_back(r);
                prevKey = key;
            }
            a.resind = (int)s.res.size() - 1;
            s.atoms.push_back(a);
            double x = strtod(std::string(buf + 30, 8).c_str(), nullptr);
            double y = strtod(std::string(buf + 38, 8).c_str(), nullptr);
            double z = strtod(std::string(buf + 46, 8).c_str(), nullptr);
            s.x.push_back(RVec{ (real)(x * 0.1), (real)(y * 0.1), (real)(z * 0.1) });
        }
        else if (r6 == "CRYST1")
        {
            double a = strtod(line.substr(6, 9).c_str(), nullptr), b = strtod(line.substr(15, 9).c_str(), nullptr),
                   c = strtod(line.substr(24, 9).c_str(), nullptr);
            double al = 90, be = 90, ga = 90;
            if (line.size() >= 54)
            {
                al = strtod(line.substr(33, 7).c_str(), nullptr);
                be = strtod(line.substr(40, 7).c_str(), nullptr);
                ga = strtod(line.substr(47, 7).c_str(), nullptr);
            }
            boxFromAngles((real)(a * 0.1), (real)(b * 0.1), (real)(c * 0.1), (real)al, (real)be, (real)ga, s.box);
            s.pbcType = 1;
        }
        else if (r6 == "TITLE" || r6 == "HEADER")
        {
            s.title = trim(line.size() > 6 ? line.substr(6) : "");
        }
        else if ((r6 == "ENDMDL" || r6 == "END") && any)
        {
            break;
        }
    }
    if (!any)
    {
        return false;
    }
    s.v.assign(s.x.size(), RVec{ 0, 0, 0 });
    fr.title  = s.title;
    fr.natoms = s.natoms();
    fr.x      = s.x;
    fr.bV     = false;
    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            fr.box[i][j] = s.box[i][j];
        }
    }
    fr.bBox  = true;
    fr.time  = nframe_;
    fr.bTime = false;
    fr.prec  = 0.0001;
    fr.bPrec = true;
    return true;
}

bool TrajectoryReader::next(Frame& fr)
{
    if (done_)
    {
        return false;
    }
    bool ok = false;
    switch (type_)
    {
        case FileType::GRO: ok = readGroFrame(fr); break;
        case FileType::PDB: ok = readPdbFrame(fr); break;
        case FileType::G96:
            if (nframe_ == 0)
            {
                fclose(fp_);
                fp_ = nullptr;
                readStructure(fn_, fr.conf);
                fr.natoms = fr.conf.natoms();
                fr.x      = fr.conf.x;
                fr.v      = fr.conf.v;
                fr.bV     = fr.conf.haveV;
                for (int i = 0; i < 3; i++)
                {
                    for (int j = 0; j < 3; j++)
                    {
                        fr.box[i][j] = fr.conf.box[i][j];
                    }
                }
                fr.title = fr.conf.title;
                fr.time  = 0;
                ok       = true;
            }
            break;
        default:
            gmx_fatal("src/gromacs/fileio/trxio.cpp", 1000, "Trajectory format of %s not supported", fn_.c_str());
    }
    if (!ok)
    {
        done_ = true;
        return false;
    }
    fr.index = nframe_++;
    return true;
}

} // namespace gmx
