                fr.v      = fr.conf.v;
                fr.bV     = fr.conf.haveV;
                for (int i = 0; i < 3; i++)
                {
                    for (int j = 0; j < 3; j++)
                    {
                        fr.box[i][j] = fr.conf.box[i][j];
                    }
                }
                fr.title = fr.conf.title;
                fr.time  = 0;
                ok       = true;
            }
            break;
        default:
            gmx_fatal("src/gromacs/fileio/trxio.cpp", 1000, "Trajectory format of %s not supported", fn_.c_str());
    }
    if (!ok)
    {
        done_ = true;
        return false;
    }
    fr.index = nframe_++;
    return true;
}

