static std::vector<IndexGroup> readIndexFile(const std::string& fn)
{
    std::vector<IndexGroup> groups;
    FILE*                   fp = fopen(fn.c_str(), "r");
    if (!fp)
    {
        return groups;
    }
    char buf[4096];
    while (fgets(buf, sizeof(buf), fp))
    {
        std::string l = trim(buf);
        if (l.empty())
        {
            continue;
        }
        if (l[0] == '[')
        {
            size_t     e = l.find(']');
            IndexGroup g;
            g.name = trim(l.substr(1, e == std::string::npos ? std::string::npos : e - 1));
            groups.push_back(g);
            continue;
        }
        if (groups.empty())
        {
            continue;
        }
        for (const auto& w : splitWS(l))
        {
            groups.back().atoms.push_back(atoi(w.c_str()) - 1);
        }
    }
    fclose(fp);
    return groups;
}

struct SelOptionSpec
{
    const char* name;
    int         count; // -1: any number (>=1), else exact
};

class TAContext
{
public:
    Options&               opts;
    SelectionCollection    sc;
    std::vector<std::vector<Selection>> sels; // per selection option
    XvgFormat              fmt;
    explicit TAContext(Options& o) : opts(o) { fmt = xvgFormatFromOptions(o); }
};

static std::string readAllStdin()
{
    std::string s;
    char        buf[4096];
    size_t      n;
    while ((n = fread(buf, 1, sizeof(buf), stdin)) > 0)
    {
        s.append(buf, n);
    }
    return s;
}

static void parseSelectionOptions(TAContext& c, const std::vector<SelOptionSpec>& specs)
{
    static bool stdinRead = false;
    static std::string stdinText;
    c.sels.resize(specs.size());
    for (size_t k = 0; k < specs.size(); k++)
    {
        const SelOptionSpec& sp = specs[k];
        Option*              o  = c.opts.find(sp.name);
        if (o && o->set)
        {
            for (const auto& v : o->values)
            {
                try
                {
                    auto s = c.sc.parse(v, false);
                    for (auto& x : s)
                    {
                        c.sels[k].push_back(x);
                    }
                }
                catch (const SelSyntaxError& e)
                {
                    GmxError err(ErrKind::InvalidInput, "Invalid command-line options",
                                 "src/gromacs/commandline/cmdlineparser.cpp", 271,
                                 "void gmx::CommandLineParser::parse(int*, char**)");
                    ErrNode n1;
                    n1.msg = std::string("In command-line option -") + sp.name;
                    ErrNode n2;
                    n2.msg = "Invalid selection '" + v + "'";
                    ErrNode n3;
                    n3.msg = "Near '" + e.near + "'";
                    ErrNode n4;
                    n4.msg = e.message;
                    n3.children.push_back(n4);
                    n2.children.push_back(n3);
                    n1.children.push_back(n2);
                    err.root.children.push_back(n1);
                    throw err;
                }
            }
            if (sp.count > 0 && (int)c.sels[k].size() != sp.count)
            {
                if ((int)c.sels[k].size() > sp.count)
                {
                    throwInputError(formatStr("Too many selections provided; got %d, expected %d",
                                              (int)c.sels[k].size(), sp.count),
                                    "src/gromacs/selection/selectionoption.cpp", 104,
                                    "void gmx::SelectionOptionStorage::addSelections(const SelectionList&, bool)");
                }
            }
        }
    }
    // Missing selections are read from standard input
    for (size_t k = 0; k < specs.size(); k++)
    {
        const SelOptionSpec& sp = specs[k];
        Option*              o  = c.opts.find(sp.name);
        if (o && o->set)
        {
            continue;
        }
        if (!stdinRead)
        {
            stdinText = isatty(0) ? std::string() : readAllStdin();
            stdinRead = true;
        }
        std::vector<Selection> got;
        try
        {
            if (sp.count > 0)
            {
                // read exactly count selections (line based)
                auto all = c.sc.parse(stdinText, true);
                for (int i = 0; i < (int)all.size() && i < sp.count; i++)
                {
                    got.push_back(all[i]);
                }
                stdinText.clear();
            }
            else
            {
                got       = c.sc.parse(stdinText, true);
                stdinText.clear();
            }
        }
        catch (const SelSyntaxError& e)
        {
            throwInputError("Invalid selection", "src/gromacs/selection/selectioncollection.cpp", 404, "");
        }
        if ((sp.count > 0 && (int)got.size() < sp.count))
        {
            throwInputError(formatStr("Too few selections provided; got %d, expected %d", (int)got.size(), sp.count),
                            "src/gromacs/selection/selectioncollection.cpp", 404,
                            "gmx::SelectionList gmx::{anonymous}::runParser(yyscan_t, gmx::TextInputStream*, bool, "
                            "int, const string&)");
        }
        if (got.empty())
        {
            throwInputError("Too few selections provided", "src/gromacs/selection/selectionoption.cpp", 107,
                            "void gmx::SelectionOptionStorage::addSelections(const SelectionList&, bool)");
        }
        c.sels[k] = got;
    }
}

// Module interface
struct TAModule
{
    virtual ~TAModule() = default;
    virtual std::vector<SelOptionSpec> selectionOptions() = 0;
    virtual void optionsFinished(TAContext&) {}
    virtual bool requiresTopology(TAContext&) { return false; }
    virtual void initAnalysis(TAContext&) {}
    virtual void initAfterFirstFrame(TAContext&, const Frame&) {}
    virtual void analyzeFrame(TAContext&, const Frame&, int) {}
    virtual void finishAnalysis(TAContext&, int) {}
    virtual void writeOutput(TAContext&) {}
};

static void evalAll(TAContext& c, const Frame& fr)
{
    SelEvalContext ctx;
    ctx.natoms = fr.natoms;
    ctx.x      = &fr.x;
    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            ctx.box[i][j] = fr.box[i][j];
        }
    }
    ctx.pbc = c.opts.find("pbc") ? c.opts.getBool("pbc") : true;
    for (auto& v : c.sels)
    {
        for (auto& s : v)
        {
            c.sc.evaluate(s, ctx);
        }
    }
}

static int runTA(Options& opts, TAModule& m)
{
    TAContext c(opts);
    m.optionsFinished(c);
    bool haveF = opts.isSet("f");
    bool haveS = opts.isSet("s");
    if (!haveF && !haveS)
    {
        throwInconsistent("No trajectory or topology provided, nothing to do!", kRunnerFile2, 403,
                          "void gmx::TrajectoryAnalysisRunnerCommon::optionsFinished()");
    }
    if (haveS)
    {
        Structure s;
        readTps(opts.fileName("s"), s);
        requireResidueTypes();
    }
    if (opts.isSet("n"))
    {
        c.sc.groups = readIndexFile(opts.fileName("n"));
    }
    parseSelectionOptions(c, m.selectionOptions());
    if ((c.sc.requiresTopology || m.requiresTopology(c)) && !haveS)
    {
        throwInconsistent("No topology provided, but one is required for analysis", kRunnerFile2, 193,
                          "void gmx::TrajectoryAnalysisRunnerCommon::Impl::initTopology(bool)");
    }
    std::vector<Selection> flat;
    for (auto& v : c.sels)
    {
        for (auto& s : v)
        {
            flat.push_back(s);
        }
    }
    c.sc.checkGroups(flat);
    m.initAnalysis(c);
    std::string      fn = haveF ? opts.fileName("f") : opts.fileName("s");
    TrajectoryReader rd(fn);
    Frame            fr;
    bool             tb = opts.isSet("b"), te = opts.isSet("e");
    double           tbv = opts.getReal("b"), tev = opts.getReal("e");
    int              nframes = 0;
    double           lastT   = 0;
    int              lastIdx = 0;
    bool             first   = true;
    FileType         ft      = fileTypeOf(fn);
    if (ft == FileType::GRO)
    {
        // header printed after reading the first frame (needs title)
    }
    while (rd.next(fr))
    {
        if (first)
        {
            if (ft == FileType::GRO)
            {
                fprintf(stderr, "Reading frames from gro file '%s', %d atoms.\n", fr.title.c_str(), fr.natoms);
            }
            else if (ft == FileType::PDB)
            {
                fprintf(stderr, "Reading frames from pdb file");
            }
        }
        printFrameProgress("Reading frame", fr.index, fr.time);
        if (first && ft == FileType::PDB)
        {
            fprintf(stderr, " '%s', %d atoms\n", "", fr.natoms);
        }
        if (tb && fr.time < tbv)
        {
            continue;
        }
        if (te && fr.time > tev)
        {
            break;
        }
        evalAll(c, fr);
        if (first)
        {
            for (auto& v : c.sels)
            {
                for (auto& s : v)
                {
                    if (!s.dynamic && s.atoms.empty() && !s.isPositions)
                    {
                        throwInputError("Selection '" + s.name + "' never matches any atoms.",
                                        "src/gromacs/selection/selectioncollection.cpp", 1100,
                                        "void gmx::SelectionCollection::evaluate(gmx::t_trxframe*, t_pbc*)");
                    }
                }
            }
            m.initAfterFirstFrame(c, fr);
            first = false;
        }
        m.analyzeFrame(c, fr, nframes);
        nframes++;
        lastT   = fr.time;
        lastIdx = fr.index;
    }
    fprintf(stderr, "\r%-14s %6d time %8.3f   \n", "Last frame", lastIdx, lastT);
    fprintf(stderr, "Analyzed %d frames, last time %.3f\n", nframes, lastT);
    m.finishAnalysis(c, nframes);
    fflush(stderr);
    m.writeOutput(c);
    return 0;
}

