struct SelectModule : TAModule
{
    std::vector<SelOptionSpec> selectionOptions() override { return { { "select", -1 } }; }
    std::vector<std::vector<double>> sizes, cfrac;
    std::vector<double>              times;
    std::vector<std::string>         idxLines;
    std::vector<IndexGroup>          ndxGroups;
    std::vector<std::vector<int>>    maskLines;
    std::vector<std::vector<int>>    candAtoms; // per selection: candidate atoms for mask
    std::vector<std::vector<double>> occ;      // per selection, per candidate

    void initAfterFirstFrame(TAContext& c, const Frame& fr) override
    {
        auto& s = c.sels[0];
        candAtoms.resize(s.size());
        occ.resize(s.size());
        for (size_t i = 0; i < s.size(); i++)
        {
            if (s[i].dynamic)
            {
                for (int a = 0; a < fr.natoms; a++)
                {
                    candAtoms[i].push_back(a);
                }
            }
            else
            {
                candAtoms[i] = s[i].isPositions ? s[i].posAtom : s[i].atoms;
            }
            occ[i].assign(candAtoms[i].size(), 0);
        }
    }

    void analyzeFrame(TAContext& c, const Frame& fr, int nf) override
    {
        auto&               s = c.sels[0];
        std::vector<double> sz, cf;
        std::string         line = formatStr("%11.3f", timeConv(c, fr.time));
        std::vector<int>    mask;
        for (size_t i = 0; i < s.size(); i++)
        {
            int n = s[i].posCount();
            sz.push_back(n);
            cf.push_back(candAtoms[i].empty() ? 0 : 1.0);
            line += formatStr(" %4d", n);
            const std::vector<int>& ids = s[i].isPositions ? s[i].posAtom : s[i].atoms;
            for (int a : ids)
            {
                line += formatStr(" %4d", a + 1);
            }
            std::set<int> cur(ids.begin(), ids.end());
            for (size_t k = 0; k < candAtoms[i].size(); k++)
            {
                int in = cur.count(candAtoms[i][k]) ? 1 : 0;
                mask.push_back(in);
                occ[i][k] += in;
            }
            IndexGroup g;
            g.atoms = ids;
            std::string nm = s[i].name;
            for (auto& ch : nm)
            {
                if (ch == ' ')
                {
                    ch = '_';
                }
            }
            if (s[i].dynamic)
            {
                g.name = nm + formatStr("_f%d_t%.3f", nf, timeConv(c, fr.time));
                ndxGroups.push_back(g);
            }
            else if (nf == 0)
            {
                g.name = nm;
                ndxGroups.push_back(g);
            }
        }
        sizes.push_back(sz);
        cfrac.push_back(cf);
        times.push_back(timeConv(c, fr.time));
        idxLines.push_back(line);
        maskLines.push_back(mask);
    }

    void finishAnalysis(TAContext& c, int nframes) override
    {
        for (auto& o : occ)
        {
            for (auto& v : o)
            {
                v = nframes > 0 ? v / nframes : 0;
            }
        }
        (void)c;
    }

    void writeOutput(TAContext& c) override
    {
        auto&                    s = c.sels[0];
        std::vector<std::string> legends;
        for (auto& x : s)
        {
            legends.push_back(x.name);
        }
        if (c.opts.isSet("os"))
        {
            FILE* fp = openPlot(c, c.opts.fileName("os"), "Selection size", timeLabel(c), "Number", legends);
            for (size_t f = 0; f < times.size(); f++)
            {
                fprintf(fp, "%11.3f", times[f]);
                for (double v : sizes[f])
                {
                    fprintf(fp, " %8.3f", v);
                }
                fprintf(fp, "\n");
            }
            xvgrClose(fp);
        }
        if (c.opts.isSet("oc"))
        {
            FILE* fp = openPlot(c, c.opts.fileName("oc"), "Covered fraction", timeLabel(c), "Fraction", legends);
            for (size_t f = 0; f < times.size(); f++)
            {
                fprintf(fp, "%11.3f", times[f]);
                for (double v : cfrac[f])
                {
                    fprintf(fp, " %.4f", v);
                }
                fprintf(fp, "\n");
            }
            xvgrClose(fp);
        }
        if (c.opts.isSet("oi"))
        {
            FILE* fp = openOutput(c.opts.fileName("oi"));
            for (const auto& l : idxLines)
            {
                fprintf(fp, "%s\n", l.c_str());
            }
            fclose(fp);
        }
        if (c.opts.isSet("on"))
        {
            FILE* fp = openOutput(c.opts.fileName("on"));
            for (size_t g = 0; g < ndxGroups.size(); g++)
            {
                if (g > 0)
                {
                    fprintf(fp, "\n");
                }
                fprintf(fp, "[ %s ]\n", ndxGroups[g].name.c_str());
                int k = 0;
                for (int a : ndxGroups[g].atoms)
                {
                    fprintf(fp, "%4d ", a + 1);
                    if (++k % 15 == 0)
                    {
                        fprintf(fp, "\n");
                    }
                }
                if (k % 15 != 0 || k == 0)
                {
                    fprintf(fp, "\n");
                }
            }
            fclose(fp);
        }
        if (c.opts.isSet("om"))
        {
            FILE* fp = openPlot(c, c.opts.fileName("om"), "Selection mask", timeLabel(c), "Occupancy", {});
            for (size_t f = 0; f < times.size(); f++)
            {
                fprintf(fp, "%11.3f", times[f]);
                for (int v : maskLines[f])
                {
                    fprintf(fp, " %d", v);
                }
                fprintf(fp, "\n");
            }
            xvgrClose(fp);
        }
        if (c.opts.isSet("of"))
        {
            FILE*  fp   = openPlot(c, c.opts.fileName("of"), "Fraction of time selection matches",
                                "Selected position", "Occupied fraction", legends);
            size_t maxn = 0;
            for (auto& o : occ)
            {
                maxn = std::max(maxn, o.size());
            }
            for (size_t k = 0; k < maxn; k++)
            {
                fprintf(fp, "%11.3f", (double)(k + 1));
                for (auto& o : occ)
                {
                    fprintf(fp, " %8.3f", k < o.size() ? o[k] : 0.0);
                }
                fprintf(fp, "\n");
            }
            xvgrClose(fp);
        }
    }
};

