// distance

struct DistanceModule : TAModule
{
    std::vector<SelOptionSpec> selectionOptions() override { return { { "select", -1 } }; }
    std::vector<double>              times;
    std::vector<std::vector<double>> avg;    // [frame][sel]
    std::vector<std::vector<double>> all;    // [frame][all distances]
    std::vector<std::vector<double>> xyz;
    std::vector<std::vector<double>> sum, sum2; // per sel per pair
    std::vector<int>                 npairs;
    std::vector<double>              tot, tot2;
    std::vector<int>                 nsamp;
    std::vector<std::vector<double>> histo;
    double                           len = 0.1, tol = 1, binw = 0.001;

    void initAfterFirstFrame(TAContext& c, const Frame&) override
    {
        auto& s = c.sels[0];
        for (size_t i = 0; i < s.size(); i++)
        {
            int n = s[i].posCount();
            if (n % 2 != 0)
            {
                throwInconsistent(formatStr("Selection '%s' does not evaluate into an even number of positions "
                                            "(there are %d positions)",
                                            s[i].name.c_str(), n),
                                  "src/gromacs/trajectoryanalysis/modules/distance.cpp", 230,
                                  "virtual void gmx::analysismodules::{anonymous}::Distance::initAnalysis(const "
                                  "gmx::TrajectoryAnalysisSettings&, const gmx::TopologyInformation&)");
            }
            if (s[i].dynamic)
            {
                throwInconsistent(formatStr("Dynamic selection %d does not select a consistent set of pairs over the "
                                            "frames",
                                            (int)i + 1),
                                  "src/gromacs/trajectoryanalysis/modules/distance.cpp", 300,
                                  "virtual void gmx::analysismodules::{anonymous}::Distance::analyzeFrame(int, const "
                                  "t_trxframe&, t_pbc*, gmx::TrajectoryAnalysisModuleData*)");
            }
            npairs.push_back(n / 2);
            sum.emplace_back(n / 2, 0.0);
            sum2.emplace_back(n / 2, 0.0);
        }
        tot.assign(s.size(), 0);
        tot2.assign(s.size(), 0);
        nsamp.assign(s.size(), 0);
        len  = c.opts.getReal("len");
        tol  = c.opts.getReal("tol");
        binw = c.opts.getReal("binw");
    }

    void analyzeFrame(TAContext& c, const Frame& fr, int) override
    {
        auto&          s = c.sels[0];
        SelEvalContext ctx;
        for (int i = 0; i < 3; i++)
        {
            for (int j = 0; j < 3; j++)
            {
                ctx.box[i][j] = fr.box[i][j];
            }
        }
        bool pbc = c.opts.getBool("pbc");
        std::vector<double> av, al, xz;
        for (size_t i = 0; i < s.size(); i++)
        {
            double sm = 0;
            for (int k = 0; k < npairs[i]; k++)
            {
                const RVec& a = s[i].positions[2 * k];
                const RVec& b = s[i].positions[2 * k + 1];
                double      dx[3];
                for (int d = 0; d < 3; d++)
                {
                    dx[d] = (double)b[d] - a[d];
                }
                if (pbc && !boxIsZero(fr.box))
                {
                    for (int d = 2; d >= 0; d--)
                    {
                        double bl = fr.box[d][d];
                        if (bl <= 0)
                        {
                            continue;
                        }
                        while (dx[d] > 0.5 * bl)
                        {
                            for (int e = 0; e <= d; e++)
                            {
                                dx[e] -= fr.box[d][e];
                            }
                        }
                        while (dx[d] <= -0.5 * bl)
                        {
                            for (int e = 0; e <= d; e++)
                            {
                                dx[e] += fr.box[d][e];
                            }
                        }
                    }
                }
                real   fx[3] = { (real)dx[0], (real)dx[1], (real)dx[2] };
                double dd    = std::sqrt((double)(fx[0] * fx[0] + fx[1] * fx[1] + fx[2] * fx[2]));
                dd           = (real)dd;
                sm += dd;
                al.push_back(dd);
                xz.push_back(fx[0]);
                xz.push_back(fx[1]);
                xz.push_back(fx[2]);
                sum[i][k] += dd;
                sum2[i][k] += dd * dd;
                tot[i] += dd;
                tot2[i] += dd * dd;
                nsamp[i]++;
            }
            av.push_back(npairs[i] > 0 ? sm / npairs[i] : 0);
        }
        times.push_back(timeConv(c, fr.time));
        avg.push_back(av);
        all.push_back(al);
        xyz.push_back(xz);
    }

    void writeOutput(TAContext& c) override
    {
        auto&                    s = c.sels[0];
        std::vector<std::string> legends;
        for (auto& x : s)
        {
            legends.push_back(x.name);
        }
        for (size_t i = 0; i < s.size(); i++)
        {
            double av  = nsamp[i] > 0 ? tot[i] / nsamp[i] : 0;
            double var = nsamp[i] > 0 ? tot2[i] / nsamp[i] - av * av : 0;
            if (var < 0)
            {
                var = 0;
            }
            printf("%s:\n", s[i].name.c_str());
            printf("  Number of samples:  %d\n", nsamp[i]);
            printf("  Average distance:   %-8.5f nm\n", av);
            printf("  Standard deviation: %-8.5f nm\n", std::sqrt(var));
        }
        if (c.opts.isSet("oav"))
        {
            FILE* fp = openPlot(c, c.opts.fileName("oav"), "Average distance", timeLabel(c), "Distance (nm)", legends);
            for (size_t f = 0; f < times.size(); f++)
            {
                fprintf(fp, "%11.3f", times[f]);
                for (double v : avg[f])
                {
                    fprintf(fp, " %8.3f", v);
                }
                fprintf(fp, "\n");
            }
            xvgrClose(fp);
        }
        if (c.opts.isSet("oall"))
        {
            FILE* fp = openPlot(c, c.opts.fileName("oall"), "Distance", timeLabel(c), "Distance (nm)", {});
            for (size_t f = 0; f < times.size(); f++)
            {
                fprintf(fp, "%11.3f", times[f]);
                for (double v : all[f])
                {
                    fprintf(fp, " %8.3f", v);
                }
                fprintf(fp, "\n");
            }
            xvgrClose(fp);
        }
        if (c.opts.isSet("oxyz"))
        {
            FILE* fp = openPlot(c, c.opts.fileName("oxyz"), "Distance", timeLabel(c), "Distance (nm)", {});
            for (size_t f = 0; f < times.size(); f++)
            {
                fprintf(fp, "%11.3f", times[f]);
                for (double v : xyz[f])
                {
                    fprintf(fp, " %8.3f", v);
                }
                fprintf(fp, "\n");
            }
            xvgrClose(fp);
        }
        if (c.opts.isSet("oallstat"))
        {
            std::vector<std::string> leg2;
            for (auto& x : s)
            {
                leg2.push_back(x.name + " avg");
                leg2.push_back(x.name + " std.dev.");
            }
            FILE* fp = openPlot(c, c.opts.fileName("oallstat"), "Statistics for individual distances",
                                "Distance index", "Average/standard deviation (nm)", leg2);
            int maxp = 0;
            for (int n : npairs)
            {
                maxp = std::max(maxp, n);
            }
            int nfr = (int)times.size();
            for (int k = 0; k < maxp; k++)
            {
                fprintf(fp, "%11.3f", (double)k);
                for (size_t i = 0; i < s.size(); i++)
                {
                    double a = 0, sd = 0;
                    if (k < npairs[i] && nfr > 0)
                    {
                        a         = sum[i][k] / nfr;
                        double vv = sum2[i][k] / nfr - a * a;
                        sd        = vv > 0 ? std::sqrt(vv) : 0;
                    }
                    fprintf(fp, " %8.3f %8.3f", a, sd);
                }
                fprintf(fp, "\n");
            }
            xvgrClose(fp);
        }
        if (c.opts.isSet("oh"))
        {
            double lo   = len - 0.5 * tol * len;
            double hi   = len + 0.5 * tol * len;
            int    nbin = (int)std::lround((hi - lo) / binw);
            if (nbin < 1)
            {
                nbin = 1;
            }
            std::vector<std::vector<double>> h(s.size(), std::vector<double>(nbin, 0));
            for (size_t f = 0; f < all.size(); f++)
            {
                size_t idx = 0;
                for (size_t i = 0; i < s.size(); i++)
                {
                    for (int k = 0; k < npairs[i]; k++, idx++)
                    {
                        double d = all[f][idx];
                        int    b = (int)std::floor((d - lo) / binw);
                        if (b >= 0 && b < nbin)
                        {
                            h[i][b] += 1;
                        }
                    }
                }
            }
            FILE* fp = openPlot(c, c.opts.fileName("oh"), "Distance histogram", "Distance (nm)", "Probability",
                                legends);
            for (int b = 0; b < nbin; b++)
            {
                fprintf(fp, "%11.3f", lo + (b + 0.5) * binw);
                for (size_t i = 0; i < s.size(); i++)
                {
                    double tot3 = nsamp[i] > 0 ? nsamp[i] * binw : 1;
                    fprintf(fp, " %8.3f", h[i][b] / tot3);
                }
                fprintf(fp, "\n");
            }
            xvgrClose(fp);
        }
    }
};

// ---------------------------------------------------------------------------
// pairdist

struct PairdistModule : TAModule
{
    std::vector<SelOptionSpec> selectionOptions() override { return { { "ref", 1 }, { "sel", -1 } }; }
    std::vector<double>              times;
    std::vector<std::vector<double>> vals;
    bool                             maxMode = false;

    void analyzeFrame(TAContext& c, const Frame& fr, int) override
    {
        maxMode           = c.opts.getEnum("type") == "max";
        double cutoff     = c.opts.getReal("cutoff");
        bool   pbc        = c.opts.getBool("pbc");
        Selection& ref    = c.sels[0][0];
        std::vector<double> row;
        SelEvalContext      ctx;
        for (int i = 0; i < 3; i++)
        {
            for (int j = 0; j < 3; j++)
            {
                ctx.box[i][j] = fr.box[i][j];
            }
        }
        ctx.pbc = pbc;
        for (auto& s : c.sels[1])
        {
            double best = maxMode ? 0 : (cutoff > 0 ? cutoff : 1e30);
            for (const auto& a : ref.positions)
            {
                for (const auto& b : s.positions)
                {
                    double dx[3];
                    for (int d = 0; d < 3; d++)
                    {
                        dx[d] = (double)a[d] - b[d];
                    }
                    if (pbc && !boxIsZero(fr.box))
                    {
                        for (int d = 2; d >= 0; d--)
                        {
                            double bl = fr.box[d][d];
                            if (bl <= 0)
                            {
                                continue;
                            }
                            while (dx[d] > 0.5 * bl)
                            {
                                for (int e = 0; e <= d; e++)
                                {
                                    dx[e] -= fr.box[d][e];
                                }
                            }
                            while (dx[d] <= -0.5 * bl)
                            {
                                for (int e = 0; e <= d; e++)
                                {
                                    dx[e] += fr.box[d][e];
                                }
                            }
                        }
                    }
                    double dd = std::sqrt(dx[0] * dx[0] + dx[1] * dx[1] + dx[2] * dx[2]);
                    if (maxMode ? dd > best : dd < best)
                    {
                        best = dd;
                    }
                }
            }
            row.push_back(best);
        }
        times.push_back(timeConv(c, fr.time));
        vals.push_back(row);
    }

    void writeOutput(TAContext& c) override
    {
        std::vector<std::string> legends;
        for (auto& x : c.sels[1])
        {
            legends.push_back(x.name);
        }
        FILE* fp = openPlot(c, c.opts.fileName("o"), maxMode ? "Maximum distance" : "Minimum distance", timeLabel(c),
                            "Distance (nm)", legends);
        for (size_t f = 0; f < times.size(); f++)
        {
            fprintf(fp, "%11.3f", times[f]);
            for (double v : vals[f])
            {
                fprintf(fp, " %8.3f", v);
            }
            fprintf(fp, "\n");
        }
        xvgrClose(fp);
    }
};

int runSelect(Options& opts)
{
    SelectModule m;
    return runTA(opts, m);
}

int runDistance(Options& opts)
{
    DistanceModule m;
    return runTA(opts, m);
}

int runPairdistTA(Options& opts)
{
    PairdistModule m;
    return runTA(opts, m);
}

