static const char* kRunnerFile2 = "src/gromacs/trajectoryanalysis/runnercommon.cpp";

static std::vector<IndexGroup> readIndexFile(const std::string& fn)
{
    std::vector<IndexGroup> groups;
    FILE*                   fp = fopen(fn.c_str(), "r");
    if (!fp)
    {
        return groups;
    }
    char buf[4096];
    while (fgets(buf, sizeof(buf), fp))
    {
        std::string l = trim(buf);
        if (l.empty())
        {
            continue;
        }
        if (l[0] == '[')
        {
            size_t     e = l.find(']');
            IndexGroup g;
            g.name = trim(l.substr(1, e == std::string::npos ? std::string::npos : e - 1));
            groups.push_back(g);
            continue;
        }
        if (groups.empty())
        {
            continue;
        }
        for (const auto& w : splitWS(l))
        {
            groups.back().atoms.push_back(atoi(w.c_str()) - 1);
        }
    }
    fclose(fp);
    return groups;
}

struct SelOptionSpec
{
    const char* name;
    int         count; // -1: any number (>=1), else exact
};

class TAContext
{
public:
    Options&               opts;
    SelectionCollection    sc;
    std::vector<std::vector<Selection>> sels; // per selection option
    XvgFormat              fmt;
    explicit TAContext(Options& o) : opts(o) { fmt = xvgFormatFromOptions(o); }
};

static std::string readAllStdin()
{
    std::string s;
    char        buf[4096];
    size_t      n;
    while ((n = fread(buf, 1, sizeof(buf), stdin)) > 0)
    {
        s.append(buf, n);
    }
    return s;
}

static void parseSelectionOptions(TAContext& c, const std::vector<SelOptionSpec>& specs)
{
    static bool stdinRead = false;
    static std::string stdinText;
    c.sels.resize(specs.size());
    for (size_t k = 0; k < specs.size(); k++)
    {
        const SelOptionSpec& sp = specs[k];
        Option*              o  = c.opts.find(sp.name);
        if (o && o->set)
        {
            for (const auto& v : o->values)
            {
                try
                {
                    auto s = c.sc.parse(v, false);
                    for (auto& x : s)
                    {
                        c.sels[k].push_back(x);
                    }
                }
                catch (const SelSyntaxError& e)
                {
                    GmxError err(ErrKind::InvalidInput, "Invalid command-line options",
                                 "src/gromacs/commandline/cmdlineparser.cpp", 271,
                                 "void gmx::CommandLineParser::parse(int*, char**)");
                    ErrNode n1;
                    n1.msg = std::string("In command-line option -") + sp.name;
                    ErrNode n2;
                    n2.msg = "Invalid selection '" + v + "'";
                    ErrNode n3;
                    n3.msg = "Near '" + e.near + "'";
                    ErrNode n4;
                    n4.msg = e.message;
                    n3.children.push_back(n4);
                    n2.children.push_back(n3);
                    n1.children.push_back(n2);
                    err.root.children.push_back(n1);
                    throw err;
                }
            }
            if (sp.count > 0 && (int)c.sels[k].size() != sp.count)
            {
                if ((int)c.sels[k].size() > sp.count)
                {
                    throwInputError(formatStr("Too many selections provided; got %d, expected %d",
                                              (int)c.sels[k].size(), sp.count),
                                    "src/gromacs/selection/selectionoption.cpp", 104,
                                    "void gmx::SelectionOptionStorage::addSelections(const SelectionList&, bool)");
                }
            }
        }
    }
    // Missing selections are read from standard input
    for (size_t k = 0; k < specs.size(); k++)
    {
        const SelOptionSpec& sp = specs[k];
        Option*              o  = c.opts.find(sp.name);
        if (o && o->set)
        {
            continue;
        }
        if (!stdinRead)
        {
            stdinText = isatty(0) ? std::string() : readAllStdin();
            stdinRead = true;
        }
        std::vector<Selection> got;
        try
        {
            if (sp.count > 0)
            {
                // read exactly count selections (line based)
                auto all = c.sc.parse(stdinText, true);
                for (int i = 0; i < (int)all.size() && i < sp.count; i++)
                {
                    got.push_back(all[i]);
                }
                stdinText.clear();
            }
            else
            {
                got       = c.sc.parse(stdinText, true);
                stdinText.clear();
            }
        }
        catch (const SelSyntaxError& e)
        {
            throwInputError("Invalid selection", "src/gromacs/selection/selectioncollection.cpp", 404, "");
        }
        if ((sp.count > 0 && (int)got.size() < sp.count))
        {
            throwInputError(formatStr("Too few selections provided; got %d, expected %d", (int)got.size(), sp.count),
                            "src/gromacs/selection/selectioncollection.cpp", 404,
                            "gmx::SelectionList gmx::{anonymous}::runParser(yyscan_t, gmx::TextInputStream*, bool, "
                            "int, const string&)");
        }
        if (got.empty())
        {
            throwInputError("Too few selections provided", "src/gromacs/selection/selectionoption.cpp", 107,
                            "void gmx::SelectionOptionStorage::addSelections(const SelectionList&, bool)");
        }
        c.sels[k] = got;
    }
}

// Module interface
struct TAModule
{
    virtual ~TAModule() = default;
    virtual std::vector<SelOptionSpec> selectionOptions() = 0;
    virtual void optionsFinished(TAContext&) {}
    virtual bool requiresTopology(TAContext&) { return false; }
    virtual void initAnalysis(TAContext&) {}
    virtual void initAfterFirstFrame(TAContext&, const Frame&) {}
    virtual void analyzeFrame(TAContext&, const Frame&, int) {}
    virtual void finishAnalysis(TAContext&, int) {}
    virtual void writeOutput(TAContext&) {}
};

static void evalAll(TAContext& c, const Frame& fr)
{
    SelEvalContext ctx;
    ctx.natoms = fr.natoms;
    ctx.x      = &fr.x;
    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            ctx.box[i][j] = fr.box[i][j];
        }
    }
    ctx.pbc = c.opts.find("pbc") ? c.opts.getBool("pbc") : true;
    for (auto& v : c.sels)
    {
        for (auto& s : v)
        {
            c.sc.evaluate(s, ctx);
        }
    }
}

static int runTA(Options& opts, TAModule& m)
{
    TAContext c(opts);
    m.optionsFinished(c);
    bool haveF = opts.isSet("f");
    bool haveS = opts.isSet("s");
    if (!haveF && !haveS)
    {
        throwInconsistent("No trajectory or topology provided, nothing to do!", kRunnerFile2, 403,
                          "void gmx::TrajectoryAnalysisRunnerCommon::optionsFinished()");
    }
    if (haveS)
    {
        Structure s;
        readTps(opts.fileName("s"), s);
        requireResidueTypes();
    }
    if (opts.isSet("n"))
    {
        c.sc.groups = readIndexFile(opts.fileName("n"));
    }
    parseSelectionOptions(c, m.selectionOptions());
    if ((c.sc.requiresTopology || m.requiresTopology(c)) && !haveS)
    {
        throwInconsistent("No topology provided, but one is required for analysis", kRunnerFile2, 193,
                          "void gmx::TrajectoryAnalysisRunnerCommon::Impl::initTopology(bool)");
    }
    std::vector<Selection> flat;
    for (auto& v : c.sels)
    {
        for (auto& s : v)
        {
            flat.push_back(s);
        }
    }
    c.sc.checkGroups(flat);
    m.initAnalysis(c);
    std::string      fn = haveF ? opts.fileName("f") : opts.fileName("s");
    TrajectoryReader rd(fn);
    Frame            fr;
    bool             tb = opts.isSet("b"), te = opts.isSet("e");
    double           tbv = opts.getReal("b"), tev = opts.getReal("e");
    int              nframes = 0;
    double           lastT   = 0;
    int              lastIdx = 0;
    bool             first   = true;
    FileType         ft      = fileTypeOf(fn);
    if (ft == FileType::GRO)
    {
        // header printed after reading the first frame (needs title)
    }
    while (rd.next(fr))
    {
        if (first)
        {
            if (ft == FileType::GRO)
            {
                fprintf(stderr, "Reading frames from gro file '%s', %d atoms.\n", fr.title.c_str(), fr.natoms);
            }
            else if (ft == FileType::PDB)
            {
                fprintf(stderr, "Reading frames from pdb file");
            }
        }
        printFrameProgress("Reading frame", fr.index, fr.time);
        if (first && ft == FileType::PDB)
        {
            fprintf(stderr, " '%s', %d atoms\n", "", fr.natoms);
        }
        if (tb && fr.time < tbv)
        {
            continue;
        }
        if (te && fr.time > tev)
        {
            break;
        }
        evalAll(c, fr);
        if (first)
        {
            for (auto& v : c.sels)
            {
                for (auto& s : v)
                {
                    if (!s.dynamic && s.atoms.empty() && !s.isPositions)
                    {
                        throwInputError("Selection '" + s.name + "' never matches any atoms.",
                                        "src/gromacs/selection/selectioncollection.cpp", 1100,
                                        "void gmx::SelectionCollection::evaluate(gmx::t_trxframe*, t_pbc*)");
                    }
                }
            }
            m.initAfterFirstFrame(c, fr);
            first = false;
        }
        m.analyzeFrame(c, fr, nframes);
        nframes++;
        lastT   = fr.time;
        lastIdx = fr.index;
    }
    fprintf(stderr, "\r%-14s %6d time %8.3f   \n", "Last frame", lastIdx, lastT);
    fprintf(stderr, "Analyzed %d frames, last time %.3f\n", nframes, lastT);
    m.finishAnalysis(c, nframes);
    fflush(stderr);
    m.writeOutput(c);
    return 0;
}

// ---------------------------------------------------------------------------
// Data output helpers

static FILE* openPlot(TAContext& c, const std::string& fn, const std::string& title, const std::string& xlabel,
                      const std::string& ylabel, const std::vector<std::string>& legends)
{
    FILE* fp = xvgrOpen(fn, title, xlabel, ylabel, c.fmt);
    if (!legends.empty())
    {
        xvgrLegend(fp, legends, c.fmt);
    }
    return fp;
}

static std::string timeLabel(TAContext& c)
{
    std::string tu = c.opts.find("tu") ? c.opts.getEnum("tu") : "ps";
    return "Time (" + tu + ")";
}

static double timeConv(TAContext& c, double t)
{
    std::string tu = c.opts.find("tu") ? c.opts.getEnum("tu") : "ps";
    if (tu == "fs") return t * 1e3;
    if (tu == "ns") return t * 1e-3;
    if (tu == "us") return t * 1e-6;
    if (tu == "ms") return t * 1e-9;
    if (tu == "s") return t * 1e-12;
    return t;
}

// ---------------------------------------------------------------------------
// select

struct SelectModule : TAModule
{
    std::vector<SelOptionSpec> selectionOptions() override { return { { "select", -1 } }; }
    std::vector<std::vector<double>> sizes, cfrac;
    std::vector<double>              times;
    std::vector<std::string>         idxLines;
    std::vector<IndexGroup>          ndxGroups;
    std::vector<std::vector<int>>    maskLines;
    std::vector<std::vector<int>>    candAtoms; // per selection: candidate atoms for mask
    std::vector<std::vector<double>> occ;      // per selection, per candidate

    void initAfterFirstFrame(TAContext& c, const Frame& fr) override
    {
        auto& s = c.sels[0];
        candAtoms.resize(s.size());
        occ.resize(s.size());
        for (size_t i = 0; i < s.size(); i++)
        {
            if (s[i].dynamic)
            {
                for (int a = 0; a < fr.natoms; a++)
                {
                    candAtoms[i].push_back(a);
                }
            }
            else
            {
                candAtoms[i] = s[i].isPositions ? s[i].posAtom : s[i].atoms;
            }
            occ[i].assign(candAtoms[i].size(), 0);
        }
    }

    void analyzeFrame(TAContext& c, const Frame& fr, int nf) override
    {
        auto&               s = c.sels[0];
        std::vector<double> sz, cf;
        std::string         line = formatStr("%11.3f", timeConv(c, fr.time));
        std::vector<int>    mask;
        for (size_t i = 0; i < s.size(); i++)
        {
            int n = s[i].posCount();
            sz.push_back(n);
            cf.push_back(candAtoms[i].empty() ? 0 : 1.0);
            line += formatStr(" %4d", n);
            const std::vector<int>& ids = s[i].isPositions ? s[i].posAtom : s[i].atoms;
            for (int a : ids)
            {
                line += formatStr(" %4d", a + 1);
            }
            std::set<int> cur(ids.begin(), ids.end());
            for (size_t k = 0; k < candAtoms[i].size(); k++)
            {
                int in = cur.count(candAtoms[i][k]) ? 1 : 0;
                mask.push_back(in);
                occ[i][k] += in;
            }
            IndexGroup g;
            g.atoms = ids;
            std::string nm = s[i].name;
            for (auto& ch : nm)
            {
                if (ch == ' ')
                {
                    ch = '_';
                }
            }
            if (s[i].dynamic)
            {
                g.name = nm + formatStr("_f%d_t%.3f", nf, timeConv(c, fr.time));
                ndxGroups.push_back(g);
            }
            else if (nf == 0)
            {
                g.name = nm;
                ndxGroups.push_back(g);
            }
        }
        sizes.push_back(sz);
        cfrac.push_back(cf);
        times.push_back(timeConv(c, fr.time));
        idxLines.push_back(line);
        maskLines.push_back(mask);
    }

    void finishAnalysis(TAContext& c, int nframes) override
    {
        for (auto& o : occ)
        {
            for (auto& v : o)
            {
                v = nframes > 0 ? v / nframes : 0;
            }
        }
        (void)c;
    }

    void writeOutput(TAContext& c) override
    {
        auto&                    s = c.sels[0];
        std::vector<std::string> legends;
        for (auto& x : s)
        {
            legends.push_back(x.name);
        }
        if (c.opts.isSet("os"))
        {
            FILE* fp = openPlot(c, c.opts.fileName("os"), "Selection size", timeLabel(c), "Number", legends);
            for (size_t f = 0; f < times.size(); f++)
            {
                fprintf(fp, "%11.3f", times[f]);
                for (double v : sizes[f])
                {
                    fprintf(fp, " %8.3f", v);
                }
                fprintf(fp, "\n");
            }
            xvgrClose(fp);
        }
        if (c.opts.isSet("oc"))
        {
            FILE* fp = openPlot(c, c.opts.fileName("oc"), "Covered fraction", timeLabel(c), "Fraction", legends);
            for (size_t f = 0; f < times.size(); f++)
            {
                fprintf(fp, "%11.3f", times[f]);
                for (double v : cfrac[f])
                {
                    fprintf(fp, " %.4f", v);
                }
                fprintf(fp, "\n");
            }
            xvgrClose(fp);
        }
        if (c.opts.isSet("oi"))
        {
            FILE* fp = openOutput(c.opts.fileName("oi"));
            for (const auto& l : idxLines)
            {
                fprintf(fp, "%s\n", l.c_str());
            }
            fclose(fp);
        }
        if (c.opts.isSet("on"))
        {
            FILE* fp = openOutput(c.opts.fileName("on"));
            for (size_t g = 0; g < ndxGroups.size(); g++)
            {
                if (g > 0)
                {
                    fprintf(fp, "\n");
                }
                fprintf(fp, "[ %s ]\n", ndxGroups[g].name.c_str());
                int k = 0;
                for (int a : ndxGroups[g].atoms)
                {
                    fprintf(fp, "%4d ", a + 1);
                    if (++k % 15 == 0)
                    {
                        fprintf(fp, "\n");
                    }
                }
                if (k % 15 != 0 || k == 0)
                {
                    fprintf(fp, "\n");
                }
            }
            fclose(fp);
        }
        if (c.opts.isSet("om"))
        {
            FILE* fp = openPlot(c, c.opts.fileName("om"), "Selection mask", timeLabel(c), "Occupancy", {});
            for (size_t f = 0; f < times.size(); f++)
            {
                fprintf(fp, "%11.3f", times[f]);
                for (int v : maskLines[f])
                {
                    fprintf(fp, " %d", v);
                }
                fprintf(fp, "\n");
            }
            xvgrClose(fp);
        }
        if (c.opts.isSet("of"))
        {
            FILE*  fp   = openPlot(c, c.opts.fileName("of"), "Fraction of time selection matches",
                                "Selected position", "Occupied fraction", legends);
            size_t maxn = 0;
            for (auto& o : occ)
            {
                maxn = std::max(maxn, o.size());
            }
            for (size_t k = 0; k < maxn; k++)
            {
                fprintf(fp, "%11.3f", (double)(k + 1));
                for (auto& o : occ)
                {
                    fprintf(fp, " %8.3f", k < o.size() ? o[k] : 0.0);
                }
                fprintf(fp, "\n");
            }
            xvgrClose(fp);
        }
    }
};

