#include "xdrio.h"

#include <climits>

namespace gmx
{

XdrFile::XdrFile(const std::string& fn, const char* mode)
{
    fp_ = fopen(fn.c_str(), mode);
}

XdrFile::~XdrFile()
{
    if (fp_)
    {
        fclose(fp_);
    }
}

bool XdrFile::eof()
{
    int c = fgetc(fp_);
    if (c == EOF)
    {
        return true;
    }
    ungetc(c, fp_);
    return false;
}

bool XdrFile::getInt(int& v)
{
    unsigned char b[4];
    if (fread(b, 1, 4, fp_) != 4)
    {
        return false;
    }
    v = (int)((unsigned)b[0] << 24 | (unsigned)b[1] << 16 | (unsigned)b[2] << 8 | (unsigned)b[3]);
    return true;
}

bool XdrFile::getFloat(float& v)
{
    int i;
    if (!getInt(i))
    {
        return false;
    }
    memcpy(&v, &i, 4);
    return true;
}

bool XdrFile::getDouble(double& v)
{
    unsigned char b[8];
    if (fread(b, 1, 8, fp_) != 8)
    {
        return false;
    }
    uint64_t u = 0;
    for (int i = 0; i < 8; i++)
    {
        u = (u << 8) | b[i];
    }
    memcpy(&v, &u, 8);
    return true;
}

bool XdrFile::getOpaque(std::vector<unsigned char>& b, int n)
{
    int padded = (n + 3) / 4 * 4;
    b.resize(padded);
    if ((int)fread(b.data(), 1, padded, fp_) != padded)
    {
        return false;
    }
    b.resize(n);
    return true;
}

bool XdrFile::getString(std::string& s)
{
    int n;
    if (!getInt(n) || n < 0 || n > 100000)
    {
        return false;
    }
    std::vector<unsigned char> b;
    if (!getOpaque(b, n))
    {
        return false;
    }
    s.assign(b.begin(), b.end());
    return true;
}

void XdrFile::putInt(int v)
{
    unsigned      u    = (unsigned)v;
    unsigned char b[4] = { (unsigned char)(u >> 24), (unsigned char)(u >> 16), (unsigned char)(u >> 8),
                           (unsigned char)u };
    fwrite(b, 1, 4, fp_);
}

void XdrFile::putFloat(float v)
{
    int i;
    memcpy(&i, &v, 4);
    putInt(i);
}

void XdrFile::putDouble(double v)
{
    uint64_t u;
    memcpy(&u, &v, 8);
    unsigned char b[8];
    for (int i = 7; i >= 0; i--)
    {
        b[i] = (unsigned char)(u & 0xff);
        u >>= 8;
    }
    fwrite(b, 1, 8, fp_);
}

void XdrFile::putOpaque(const unsigned char* b, int n)
{
    fwrite(b, 1, n, fp_);
    static const unsigned char zeros[4] = { 0, 0, 0, 0 };
    int                        pad      = (4 - n % 4) % 4;
    fwrite(zeros, 1, pad, fp_);
}

void XdrFile::putString(const std::string& s)
{
    putInt((int)s.size());
    putOpaque((const unsigned char*)s.data(), (int)s.size());
}

// ---------------------------------------------------------------------------
// xtc compression

static const int magicints[] = { 0,        0,        0,       0,       0,       0,       0,       0,       0,
                                 8,        10,       12,      16,      20,      25,      32,      40,      50,
                                 64,       80,       101,     128,     161,     203,     256,     322,     406,
                                 512,      645,      812,     1024,    1290,    1625,    2048,    2580,    3250,
                                 4096,     5060,     6501,    8192,    10321,   13003,   16384,   20642,   26007,
                                 32768,    41285,    52015,   65536,   82570,   104031,  131072,  165140,  208063,
                                 262144,   330280,   416127,  524287,  660561,  832255,  1048576, 1321122, 1664510,
                                 2097152,  2642245,  3329021, 4194304, 5284491, 6658042, 8388607, 10568983, 13316085,
                                 16777216 };
static const int FIRSTIDX    = 9;
static const int LASTIDX     = (int)(sizeof(magicints) / sizeof(*magicints));

struct BitBuf
{
    int                        cnt = 0, lastbits = 0;
    unsigned int               lastbyte = 0;
    std::vector<unsigned char> data;
};

static int sizeofint(int size)
{
    unsigned int num         = 1;
    int          num_of_bits = 0;
    while ((unsigned)size >= num && num_of_bits < 32)
    {
        num_of_bits++;
        num <<= 1;
    }
    return num_of_bits;
}

static int sizeofints(int num_of_ints, const unsigned int sizes[])
{
    int          i, num;
    unsigned int num_of_bytes, num_of_bits, bytes[32], bytecnt, tmp;
    num_of_bytes = 1;
    bytes[0]     = 1;
    num_of_bits  = 0;
    for (i = 0; i < num_of_ints; i++)
    {
        tmp = 0;
        for (bytecnt = 0; bytecnt < num_of_bytes; bytecnt++)
        {
            tmp            = bytes[bytecnt] * sizes[i] + tmp;
            bytes[bytecnt] = tmp & 0xff;
            tmp >>= 8;
        }
        while (tmp != 0)
        {
            bytes[bytecnt++] = tmp & 0xff;
            tmp >>= 8;
        }
        num_of_bytes = bytecnt;
    }
    num = 1;
    num_of_bytes--;
    while (bytes[num_of_bytes] >= (unsigned)num)
    {
        num_of_bits++;
        num *= 2;
    }
    return num_of_bits + num_of_bytes * 8;
}

static void sendbits(BitBuf& buf, int num_of_bits, int num)
{
    unsigned int lastbyte = buf.lastbyte;
    int          lastbits = buf.lastbits;
    while (num_of_bits >= 8)
    {
        lastbyte = (lastbyte << 8) | ((num >> (num_of_bits - 8)) /* & 0xff*/);
        buf.data.push_back((unsigned char)(lastbyte >> lastbits));
        num_of_bits -= 8;
    }
    if (num_of_bits > 0)
    {
        lastbyte = (lastbyte << num_of_bits) | num;
        lastbits += num_of_bits;
        if (lastbits >= 8)
        {
            lastbits -= 8;
            buf.data.push_back((unsigned char)(lastbyte >> lastbits));
        }
    }
    buf.lastbits = lastbits;
    buf.lastbyte = lastbyte;
}

static void sendints(BitBuf& buf, const int num_of_ints, const int num_of_bits, unsigned int sizes[],
                     unsigned int nums[])
{
    int          i, num_of_bytes, bytecnt;
    unsigned int bytes[32], tmp;
    tmp          = nums[0];
    num_of_bytes = 0;
    do
    {
        bytes[num_of_bytes++] = tmp & 0xff;
        tmp >>= 8;
    } while (tmp != 0);
    for (i = 1; i < num_of_ints; i++)
    {
        tmp = nums[i];
        for (bytecnt = 0; bytecnt < num_of_bytes; bytecnt++)
        {
            tmp            = bytes[bytecnt] * sizes[i] + tmp;
            bytes[bytecnt] = tmp & 0xff;
            tmp >>= 8;
        }
        while (tmp != 0)
        {
            bytes[bytecnt++] = tmp & 0xff;
            tmp >>= 8;
        }
        num_of_bytes = bytecnt;
    }
    if (num_of_bits >= num_of_bytes * 8)
    {
        for (i = 0; i < num_of_bytes; i++)
        {
            sendbits(buf, 8, bytes[i]);
        }
        sendbits(buf, num_of_bits - num_of_bytes * 8, 0);
    }
    else
    {
        for (i = 0; i < num_of_bytes - 1; i++)
        {
            sendbits(buf, 8, bytes[i]);
        }
        sendbits(buf, num_of_bits - (num_of_bytes - 1) * 8, bytes[i]);
    }
}

struct RBuf
{
    const unsigned char* data;
    size_t               n;
    size_t               cnt      = 0;
    unsigned int         lastbits = 0;
    unsigned int         lastbyte = 0;
    unsigned char        get()
    {
        return cnt < n ? data[cnt++] : 0;
    }
};

static int receivebits(RBuf& buf, int num_of_bits)
{
    int          num;
    unsigned int lastbits = buf.lastbits, lastbyte = buf.lastbyte;
    int          mask = (num_of_bits >= 32) ? -1 : (1 << num_of_bits) - 1;
    num               = 0;
    while (num_of_bits >= 8)
    {
        lastbyte = (lastbyte << 8) | buf.get();
        num |= (lastbyte >> lastbits) << (num_of_bits - 8);
        num_of_bits -= 8;
    }
    if (num_of_bits > 0)
    {
        if ((int)lastbits < num_of_bits)
        {
            lastbits += 8;
            lastbyte = (lastbyte << 8) | buf.get();
        }
        lastbits -= num_of_bits;
        num |= (lastbyte >> lastbits) & ((1 << num_of_bits) - 1);
    }
    num &= mask;
    buf.lastbits = lastbits;
    buf.lastbyte = lastbyte;
    return num;
}

static void receiveints(RBuf& buf, const int num_of_ints, int num_of_bits, unsigned int sizes[], int nums[])
{
    int bytes[32];
    int i, j, num_of_bytes, p, num;
    bytes[0] = bytes[1] = bytes[2] = bytes[3] = 0;
    num_of_bytes                              = 0;
    while (num_of_bits > 8)
    {
        bytes[num_of_bytes++] = receivebits(buf, 8);
        num_of_bits -= 8;
    }
    if (num_of_bits > 0)
    {
        bytes[num_of_bytes++] = receivebits(buf, num_of_bits);
    }
    for (i = num_of_ints - 1; i > 0; i--)
    {
        num = 0;
        for (j = num_of_bytes - 1; j >= 0; j--)
        {
            num      = (num << 8) | bytes[j];
            p        = num / sizes[i];
            bytes[j] = p;
            num      = num - p * sizes[i];
        }
        nums[i] = num;
    }
    nums[0] = bytes[0] | (bytes[1] << 8) | (bytes[2] << 16) | (bytes[3] << 24);
}

static void xdr3dfcoordWrite(XdrFile& xd, const std::vector<RVec>& x, int natoms, float precision)
{
    xd.putInt(natoms);
    if (natoms <= 9)
    {
        for (int i = 0; i < natoms; i++)
        {
            for (int d = 0; d < 3; d++)
            {
                xd.putFloat(x[i][d]);
            }
        }
        return;
    }
