    {
        int lint[3];
        for (int d = 0; d < 3; d++)
        {
            float lf = x[i][d] * precision;
            if (lf >= 0.0)
            {
                lf += 0.5;
            }
            else
            {
                lf -= 0.5;
            }
            lint[d] = (int)lf;
            if (lint[d] < minint[d])
            {
                minint[d] = lint[d];
            }
            if (lint[d] > maxint[d])
            {
                maxint[d] = lint[d];
            }
            ip[i * 3 + d] = lint[d];
        }
        int diff = std::abs(oldlint1 - lint[0]) + std::abs(oldlint2 - lint[1]) + std::abs(oldlint3 - lint[2]);
        if (diff < mindiff && i > 0)
        {
            mindiff = diff;
        }
        oldlint1 = lint[0];
        oldlint2 = lint[1];
        oldlint3 = lint[2];
    }
    xd.putFloat(precision);
    for (int d = 0; d < 3; d++)
    {
        xd.putInt(minint[d]);
    }
    for (int d = 0; d < 3; d++)
    {
        xd.putInt(maxint[d]);
    }
    unsigned int sizeint[3], bitsizeint[3] = { 0, 0, 0 };
    int          bitsize;
    for (int d = 0; d < 3; d++)
    {
        sizeint[d] = maxint[d] - minint[d] + 1;
    }
    if ((sizeint[0] | sizeint[1] | sizeint[2]) > 0xffffff)
    {
        for (int d = 0; d < 3; d++)
        {
            bitsizeint[d] = sizeofint(sizeint[d]);
        }
        bitsize = 0;
