#include "xdrio.h"

#include <climits>

namespace gmx
{

XdrFile::XdrFile(const std::string& fn, const char* mode)
{
    fp_ = fopen(fn.c_str(), mode);
}

XdrFile::~XdrFile()
{
    if (fp_)
    {
        fclose(fp_);
    }
}

bool XdrFile::eof()
{
    int c = fgetc(fp_);
    if (c == EOF)
    {
        return true;
    }
    ungetc(c, fp_);
    return false;
}

bool XdrFile::getInt(int& v)
{
    unsigned char b[4];
    if (fread(b, 1, 4, fp_) != 4)
    {
        return false;
    }
    v = (int)((unsigned)b[0] << 24 | (unsigned)b[1] << 16 | (unsigned)b[2] << 8 | (unsigned)b[3]);
    return true;
}

bool XdrFile::getFloat(float& v)
{
    int i;
    if (!getInt(i))
    {
        return false;
    }
    memcpy(&v, &i, 4);
    return true;
}

bool XdrFile::getDouble(double& v)
{
    unsigned char b[8];
    if (fread(b, 1, 8, fp_) != 8)
    {
        return false;
    }
    uint64_t u = 0;
    for (int i = 0; i < 8; i++)
    {
        u = (u << 8) | b[i];
    }
    memcpy(&v, &u, 8);
    return true;
}

bool XdrFile::getOpaque(std::vector<unsigned char>& b, int n)
{
    int padded = (n + 3) / 4 * 4;
    b.resize(padded);
    if ((int)fread(b.data(), 1, padded, fp_) != padded)
    {
        return false;
    }
    b.resize(n);
    return true;
}

bool XdrFile::getString(std::string& s)
{
    int n;
    if (!getInt(n) || n < 0 || n > 100000)
    {
        return false;
    }
    std::vector<unsigned char> b;
    if (!getOpaque(b, n))
    {
        return false;
    }
    s.assign(b.begin(), b.end());
    return true;
}

void XdrFile::putInt(int v)
{
    unsigned      u    = (unsigned)v;
    unsigned char b[4] = { (unsigned char)(u >> 24), (unsigned char)(u >> 16), (unsigned char)(u >> 8),
                           (unsigned char)u };
    fwrite(b, 1, 4, fp_);
}

void XdrFile::putFloat(float v)
{
    int i;
    memcpy(&i, &v, 4);
    putInt(i);
}

void XdrFile::putDouble(double v)
{
    uint64_t u;
    memcpy(&u, &v, 8);
    unsigned char b[8];
    for (int i = 7; i >= 0; i--)
    {
        b[i] = (unsigned char)(u & 0xff);
        u >>= 8;
    }
    fwrite(b, 1, 8, fp_);
}

void XdrFile::putOpaque(const unsigned char* b, int n)
{
    fwrite(b, 1, n, fp_);
    static const unsigned char zeros[4] = { 0, 0, 0, 0 };
    int                        pad      = (4 - n % 4) % 4;
    fwrite(zeros, 1, pad, fp_);
}

void XdrFile::putString(const std::string& s)
{
    putInt((int)s.size());
    putOpaque((const unsigned char*)s.data(), (int)s.size());
}

// ---------------------------------------------------------------------------
// xtc compression

static const int magicints[] = { 0,        0,        0,       0,       0,       0,       0,       0,       0,
                                 8,        10,       12,      16,      20,      25,      32,      40,      50,
                                 64,       80,       101,     128,     161,     203,     256,     322,     406,
                                 512,      645,      812,     1024,    1290,    1625,    2048,    2580,    3250,
                                 4096,     5060,     6501,    8192,    10321,   13003,   16384,   20642,   26007,
                                 32768,    41285,    52015,   65536,   82570,   104031,  131072,  165140,  208063,
                                 262144,   330280,   416127,  524287,  660561,  832255,  1048576, 1321122, 1664510,
                                 2097152,  2642245,  3329021, 4194304, 5284491, 6658042, 8388607, 10568983, 13316085,
                                 16777216 };
static const int FIRSTIDX    = 9;
static const int LASTIDX     = (int)(sizeof(magicints) / sizeof(*magicints));

struct BitBuf
{
    int                        cnt = 0, lastbits = 0;
    unsigned int               lastbyte = 0;
    std::vector<unsigned char> data;
};

static int sizeofint(int size)
{
    unsigned int num         = 1;
    int          num_of_bits = 0;
    while ((unsigned)size >= num && num_of_bits < 32)
    {
        num_of_bits++;
        num <<= 1;
    }
    return num_of_bits;
}

static int sizeofints(int num_of_ints, const unsigned int sizes[])
{
    int          i, num;
    unsigned int num_of_bytes, num_of_bits, bytes[32], bytecnt, tmp;
    num_of_bytes = 1;
    bytes[0]     = 1;
    num_of_bits  = 0;
    for (i = 0; i < num_of_ints; i++)
    {
        tmp = 0;
        for (bytecnt = 0; bytecnt < num_of_bytes; bytecnt++)
        {
            tmp            = bytes[bytecnt] * sizes[i] + tmp;
            bytes[bytecnt] = tmp & 0xff;
            tmp >>= 8;
        }
        while (tmp != 0)
        {
            bytes[bytecnt++] = tmp & 0xff;
            tmp >>= 8;
        }
        num_of_bytes = bytecnt;
    }
    num = 1;
    num_of_bytes--;
    while (bytes[num_of_bytes] >= (unsigned)num)
    {
        num_of_bits++;
        num *= 2;
    }
    return num_of_bits + num_of_bytes * 8;
}

static void sendbits(BitBuf& buf, int num_of_bits, int num)
{
    unsigned int lastbyte = buf.lastbyte;
    int          lastbits = buf.lastbits;
    while (num_of_bits >= 8)
    {
        lastbyte = (lastbyte << 8) | ((num >> (num_of_bits - 8)) /* & 0xff*/);
        buf.data.push_back((unsigned char)(lastbyte >> lastbits));
        num_of_bits -= 8;
    }
    if (num_of_bits > 0)
    {
        lastbyte = (lastbyte << num_of_bits) | num;
        lastbits += num_of_bits;
        if (lastbits >= 8)
        {
            lastbits -= 8;
            buf.data.push_back((unsigned char)(lastbyte >> lastbits));
        }
    }
    buf.lastbits = lastbits;
    buf.lastbyte = lastbyte;
}

static void sendints(BitBuf& buf, const int num_of_ints, const int num_of_bits, unsigned int sizes[],
                     unsigned int nums[])
{
    int          i, num_of_bytes, bytecnt;
    unsigned int bytes[32], tmp;
    tmp          = nums[0];
    num_of_bytes = 0;
    do
    {
        bytes[num_of_bytes++] = tmp & 0xff;
        tmp >>= 8;
    } while (tmp != 0);
    for (i = 1; i < num_of_ints; i++)
    {
        tmp = nums[i];
        for (bytecnt = 0; bytecnt < num_of_bytes; bytecnt++)
        {
            tmp            = bytes[bytecnt] * sizes[i] + tmp;
            bytes[bytecnt] = tmp & 0xff;
            tmp >>= 8;
        }
        while (tmp != 0)
        {
            bytes[bytecnt++] = tmp & 0xff;
            tmp >>= 8;
        }
        num_of_bytes = bytecnt;
    }
    if (num_of_bits >= num_of_bytes * 8)
    {
        for (i = 0; i < num_of_bytes; i++)
        {
            sendbits(buf, 8, bytes[i]);
        }
        sendbits(buf, num_of_bits - num_of_bytes * 8, 0);
    }
    else
    {
        for (i = 0; i < num_of_bytes - 1; i++)
        {
            sendbits(buf, 8, bytes[i]);
        }
        sendbits(buf, num_of_bits - (num_of_bytes - 1) * 8, bytes[i]);
    }
}

struct RBuf
{
    const unsigned char* data;
    size_t               n;
    size_t               cnt      = 0;
    unsigned int         lastbits = 0;
    unsigned int         lastbyte = 0;
    unsigned char        get()
    {
        return cnt < n ? data[cnt++] : 0;
    }
};

static int receivebits(RBuf& buf, int num_of_bits)
{
    int          num;
    unsigned int lastbits = buf.lastbits, lastbyte = buf.lastbyte;
    int          mask = (num_of_bits >= 32) ? -1 : (1 << num_of_bits) - 1;
    num               = 0;
    while (num_of_bits >= 8)
    {
        lastbyte = (lastbyte << 8) | buf.get();
        num |= (lastbyte >> lastbits) << (num_of_bits - 8);
        num_of_bits -= 8;
    }
    if (num_of_bits > 0)
    {
        if ((int)lastbits < num_of_bits)
        {
            lastbits += 8;
            lastbyte = (lastbyte << 8) | buf.get();
        }
        lastbits -= num_of_bits;
        num |= (lastbyte >> lastbits) & ((1 << num_of_bits) - 1);
    }
    num &= mask;
    buf.lastbits = lastbits;
    buf.lastbyte = lastbyte;
    return num;
}

static void receiveints(RBuf& buf, const int num_of_ints, int num_of_bits, unsigned int sizes[], int nums[])
{
    int bytes[32];
    int i, j, num_of_bytes, p, num;
    bytes[0] = bytes[1] = bytes[2] = bytes[3] = 0;
    num_of_bytes                              = 0;
    while (num_of_bits > 8)
    {
        bytes[num_of_bytes++] = receivebits(buf, 8);
        num_of_bits -= 8;
    }
    if (num_of_bits > 0)
    {
        bytes[num_of_bytes++] = receivebits(buf, num_of_bits);
    }
    for (i = num_of_ints - 1; i > 0; i--)
    {
        num = 0;
        for (j = num_of_bytes - 1; j >= 0; j--)
        {
            num      = (num << 8) | bytes[j];
            p        = num / sizes[i];
            bytes[j] = p;
            num      = num - p * sizes[i];
        }
        nums[i] = num;
    }
    nums[0] = bytes[0] | (bytes[1] << 8) | (bytes[2] << 16) | (bytes[3] << 24);
}

static void xdr3dfcoordWrite(XdrFile& xd, const std::vector<RVec>& x, int natoms, float precision)
{
    xd.putInt(natoms);
    if (natoms <= 9)
    {
        for (int i = 0; i < natoms; i++)
        {
            for (int d = 0; d < 3; d++)
            {
                xd.putFloat(x[i][d]);
            }
        }
        return;
    }
    std::vector<int> ip(natoms * 3);
    int              minint[3] = { INT_MAX, INT_MAX, INT_MAX }, maxint[3] = { INT_MIN, INT_MIN, INT_MIN };
    int              mindiff = INT_MAX;
    int              oldlint1 = 0, oldlint2 = 0, oldlint3 = 0;
    for (int i = 0; i < natoms; i++)
    {
        int lint[3];
        for (int d = 0; d < 3; d++)
        {
            float lf = x[i][d] * precision;
            if (lf >= 0.0)
            {
                lf += 0.5;
            }
            else
            {
                lf -= 0.5;
            }
            lint[d] = (int)lf;
            if (lint[d] < minint[d])
            {
                minint[d] = lint[d];
            }
            if (lint[d] > maxint[d])
            {
                maxint[d] = lint[d];
            }
            ip[i * 3 + d] = lint[d];
        }
        int diff = std::abs(oldlint1 - lint[0]) + std::abs(oldlint2 - lint[1]) + std::abs(oldlint3 - lint[2]);
        if (diff < mindiff && i > 0)
        {
            mindiff = diff;
        }
        oldlint1 = lint[0];
        oldlint2 = lint[1];
        oldlint3 = lint[2];
    }
    xd.putFloat(precision);
    for (int d = 0; d < 3; d++)
    {
        xd.putInt(minint[d]);
    }
    for (int d = 0; d < 3; d++)
    {
        xd.putInt(maxint[d]);
    }
    unsigned int sizeint[3], bitsizeint[3] = { 0, 0, 0 };
    int          bitsize;
    for (int d = 0; d < 3; d++)
    {
        sizeint[d] = maxint[d] - minint[d] + 1;
    }
    if ((sizeint[0] | sizeint[1] | sizeint[2]) > 0xffffff)
    {
        for (int d = 0; d < 3; d++)
        {
            bitsizeint[d] = sizeofint(sizeint[d]);
        }
        bitsize = 0;
    }
    else
    {
        bitsize = sizeofints(3, sizeint);
    }
    int smallidx = FIRSTIDX;
    while (smallidx < LASTIDX && magicints[smallidx] < mindiff)
    {
        smallidx++;
    }
    xd.putInt(smallidx);
    int          maxidx   = std::min(LASTIDX, smallidx + 8);
    int          minidx   = maxidx - 8;
    int          smaller  = magicints[std::max(FIRSTIDX, smallidx - 1)] / 2;
    int          smallnum = magicints[smallidx] / 2;
    unsigned int sizesmall[3];
    sizesmall[0] = sizesmall[1] = sizesmall[2] = magicints[smallidx];
    int    larger                              = magicints[maxidx] / 2;
    int    i                                   = 0;
    int    prevrun                             = -1;
    BitBuf buf;
    int    prevcoord[3] = { 0, 0, 0 };
    unsigned int tmpcoord[30];
    while (i < natoms)
    {
        int  is_small = 0;
        int* thiscoord = &ip[i * 3];
        int  is_smaller;
        if (smallidx < maxidx && i >= 1 && std::abs(thiscoord[0] - prevcoord[0]) < larger
            && std::abs(thiscoord[1] - prevcoord[1]) < larger && std::abs(thiscoord[2] - prevcoord[2]) < larger)
        {
            is_smaller = 1;
        }
        else if (smallidx > minidx)
        {
            is_smaller = -1;
        }
        else
        {
            is_smaller = 0;
        }
        if (i + 1 < natoms)
        {
            if (std::abs(thiscoord[0] - thiscoord[3]) < smallnum && std::abs(thiscoord[1] - thiscoord[4]) < smallnum
                && std::abs(thiscoord[2] - thiscoord[5]) < smallnum)
            {
                std::swap(thiscoord[0], thiscoord[3]);
                std::swap(thiscoord[1], thiscoord[4]);
                std::swap(thiscoord[2], thiscoord[5]);
                is_small = 1;
            }
        }
        tmpcoord[0] = thiscoord[0] - minint[0];
        tmpcoord[1] = thiscoord[1] - minint[1];
        tmpcoord[2] = thiscoord[2] - minint[2];
        if (bitsize == 0)
        {
            sendbits(buf, bitsizeint[0], tmpcoord[0]);
            sendbits(buf, bitsizeint[1], tmpcoord[1]);
            sendbits(buf, bitsizeint[2], tmpcoord[2]);
        }
        else
        {
            sendints(buf, 3, bitsize, sizeint, tmpcoord);
        }
        prevcoord[0] = thiscoord[0];
        prevcoord[1] = thiscoord[1];
        prevcoord[2] = thiscoord[2];
        thiscoord    = thiscoord + 3;
        i++;
        int run = 0;
        if (is_small == 0 && is_smaller == -1)
        {
            is_smaller = 0;
        }
        while (is_small && run < 8 * 3)
        {
            if (is_smaller == -1
                && ((thiscoord[0] - prevcoord[0]) * (thiscoord[0] - prevcoord[0])
                            + (thiscoord[1] - prevcoord[1]) * (thiscoord[1] - prevcoord[1])
                            + (thiscoord[2] - prevcoord[2]) * (thiscoord[2] - prevcoord[2])
                    >= smaller * smaller))
            {
                is_smaller = 0;
            }
            tmpcoord[run++] = thiscoord[0] - prevcoord[0] + smallnum;
            tmpcoord[run++] = thiscoord[1] - prevcoord[1] + smallnum;
            tmpcoord[run++] = thiscoord[2] - prevcoord[2] + smallnum;
            prevcoord[0]    = thiscoord[0];
            prevcoord[1]    = thiscoord[1];
            prevcoord[2]    = thiscoord[2];
            i++;
            thiscoord = thiscoord + 3;
            is_small  = 0;
            if (i < natoms && std::abs(thiscoord[0] - prevcoord[0]) < smallnum
                && std::abs(thiscoord[1] - prevcoord[1]) < smallnum && std::abs(thiscoord[2] - prevcoord[2]) < smallnum)
            {
                is_small = 1;
            }
        }
        if (run != prevrun || is_smaller != 0)
        {
            prevrun = run;
            sendbits(buf, 1, 1);
            sendbits(buf, 5, run + is_smaller + 1);
        }
        else
        {
            sendbits(buf, 1, 0);
        }
        for (int k = 0; k < run; k += 3)
        {
            sendints(buf, 3, smallidx, sizesmall, &tmpcoord[k]);
        }
        if (is_smaller != 0)
        {
            smallidx += is_smaller;
            if (is_smaller < 0)
            {
                smallnum = smaller;
                if (smallidx > FIRSTIDX)
                {
                    smaller = magicints[smallidx - 1] / 2;
                }
                else
                {
                    smaller = 0;
                }
            }
            else if (is_smaller > 0)
            {
                smaller  = smallnum;
                smallnum = magicints[smallidx] / 2;
            }
            sizesmall[0] = sizesmall[1] = sizesmall[2] = magicints[smallidx];
        }
    }
    if (buf.lastbits != 0)
    {
        buf.data.push_back((unsigned char)(buf.lastbyte << (8 - buf.lastbits)));
    }
    xd.putInt((int)buf.data.size());
    xd.putOpaque(buf.data.data(), (int)buf.data.size());
}

static bool xdr3dfcoordRead(XdrFile& xd, std::vector<RVec>& x, int natoms, float& precision)
{
    int lsize;
    if (!xd.getInt(lsize))
    {
        return false;
    }
    x.assign(natoms, RVec{ 0, 0, 0 });
    if (lsize <= 9)
    {
        precision = -1;
        for (int i = 0; i < lsize; i++)
        {
            for (int d = 0; d < 3; d++)
            {
                float f;
                if (!xd.getFloat(f))
                {
                    return false;
                }
                if (i < natoms)
                {
                    x[i][d] = f;
                }
            }
        }
        return true;
    }
    int minint[3], maxint[3], smallidx;
    if (!xd.getFloat(precision))
    {
        return false;
    }
    for (int d = 0; d < 3; d++)
    {
        xd.getInt(minint[d]);
    }
    for (int d = 0; d < 3; d++)
    {
        xd.getInt(maxint[d]);
    }
    unsigned int sizeint[3], bitsizeint[3] = { 0, 0, 0 };
    int          bitsize;
    for (int d = 0; d < 3; d++)
    {
        sizeint[d] = maxint[d] - minint[d] + 1;
    }
    if ((sizeint[0] | sizeint[1] | sizeint[2]) > 0xffffff)
    {
        for (int d = 0; d < 3; d++)
        {
            bitsizeint[d] = sizeofint(sizeint[d]);
        }
        bitsize = 0;
    }
    else
    {
        bitsize = sizeofints(3, sizeint);
    }
    if (!xd.getInt(smallidx))
    {
        return false;
    }
    int          smaller  = magicints[std::max(FIRSTIDX, smallidx - 1)] / 2;
    int          smallnum = magicints[smallidx] / 2;
    unsigned int sizesmall[3];
    sizesmall[0] = sizesmall[1] = sizesmall[2] = magicints[smallidx];
    int nbytes;
    if (!xd.getInt(nbytes))
    {
        return false;
    }
    std::vector<unsigned char> bytes;
    if (!xd.getOpaque(bytes, nbytes))
    {
        return false;
    }
    RBuf buf;
    buf.data             = bytes.data();
    buf.n                = bytes.size();
    std::vector<int> ip(lsize * 3 + 30);
    float            inv = 1.0f / precision;
    int              run = 0;
    int              i   = 0;
    size_t           out = 0;
    std::vector<float> lfp(lsize * 3);
    int prevcoord[3];
    while (i < lsize)
    {
        int* thiscoord = &ip[i * 3];
        if (bitsize == 0)
        {
            thiscoord[0] = receivebits(buf, bitsizeint[0]);
            thiscoord[1] = receivebits(buf, bitsizeint[1]);
            thiscoord[2] = receivebits(buf, bitsizeint[2]);
        }
        else
        {
            receiveints(buf, 3, bitsize, sizeint, thiscoord);
        }
        i++;
        thiscoord[0] += minint[0];
        thiscoord[1] += minint[1];
        thiscoord[2] += minint[2];
        prevcoord[0] = thiscoord[0];
        prevcoord[1] = thiscoord[1];
        prevcoord[2] = thiscoord[2];
        int flag       = receivebits(buf, 1);
        int is_smaller = 0;
        if (flag == 1)
        {
            run        = receivebits(buf, 5);
            is_smaller = run % 3;
            run -= is_smaller;
            is_smaller--;
        }
        if (run > 0)
        {
            thiscoord += 3;
            for (int k = 0; k < run; k += 3)
            {
                receiveints(buf, 3, smallidx, sizesmall, thiscoord);
                i++;
                thiscoord[0] += prevcoord[0] - smallnum;
                thiscoord[1] += prevcoord[1] - smallnum;
                thiscoord[2] += prevcoord[2] - smallnum;
                if (k == 0)
                {
                    std::swap(thiscoord[0], prevcoord[0]);
                    std::swap(thiscoord[1], prevcoord[1]);
                    std::swap(thiscoord[2], prevcoord[2]);
                    if (out + 3 <= lfp.size())
                    {
                        lfp[out++] = prevcoord[0] * inv;
                        lfp[out++] = prevcoord[1] * inv;
                        lfp[out++] = prevcoord[2] * inv;
                    }
                }
                else
                {
                    prevcoord[0] = thiscoord[0];
                    prevcoord[1] = thiscoord[1];
                    prevcoord[2] = thiscoord[2];
                }
                if (out + 3 <= lfp.size())
                {
                    lfp[out++] = thiscoord[0] * inv;
                    lfp[out++] = thiscoord[1] * inv;
                    lfp[out++] = thiscoord[2] * inv;
                }
            }
        }
        else
        {
            if (out + 3 <= lfp.size())
            {
                lfp[out++] = thiscoord[0] * inv;
                lfp[out++] = thiscoord[1] * inv;
                lfp[out++] = thiscoord[2] * inv;
            }
        }
        smallidx += is_smaller;
        if (is_smaller < 0)
        {
            smallnum = smaller;
            if (smallidx > FIRSTIDX)
            {
                smaller = magicints[smallidx - 1] / 2;
            }
            else
            {
                smaller = 0;
            }
        }
        else if (is_smaller > 0)
        {
            smaller  = smallnum;
            smallnum = magicints[smallidx] / 2;
        }
        if (smallidx < 0 || smallidx >= LASTIDX)
        {
            return false;
        }
        sizesmall[0] = sizesmall[1] = sizesmall[2] = magicints[smallidx];
    }
    for (int k = 0; k < natoms && k < lsize; k++)
    {
        for (int d = 0; d < 3; d++)
        {
            x[k][d] = lfp[k * 3 + d];
        }
    }
    return true;
}

bool xtcReadFrame(XdrFile& xd, Frame& fr, bool& bOK)
{
    bOK = true;
    int magic;
    if (!xd.getInt(magic))
    {
        return false;
    }
    if (magic != 1995)
    {
        bOK = false;
        return false;
    }
    int   natoms, step;
    float t;
    if (!xd.getInt(natoms) || !xd.getInt(step) || !xd.getFloat(t))
    {
        bOK = false;
        return false;
    }
    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            float b;
            xd.getFloat(b);
            fr.box[i][j] = b;
        }
    }
    float prec = 0;
    if (!xdr3dfcoordRead(xd, fr.x, natoms, prec))
    {
        bOK = false;
        return false;
    }
    fr.natoms = natoms;
    fr.step   = step;
    fr.bStep  = true;
    fr.time   = t;
    fr.bTime  = true;
    fr.bX     = true;
    fr.bV     = false;
    fr.bF     = false;
    fr.bBox   = true;
    fr.prec   = prec;
    fr.bPrec  = prec > 0;
    return true;
}

void xtcWriteFrame(XdrFile& xd, int natoms, int64_t step, float time, const Matrix box, const std::vector<RVec>& x,
                   float prec)
{
    xd.putInt(1995);
    xd.putInt(natoms);
    xd.putInt((int)step);
    xd.putFloat(time);
    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            xd.putFloat(box[i][j]);
        }
    }
    xdr3dfcoordWrite(xd, x, natoms, prec);
}

// ---------------------------------------------------------------------------
// trr

bool trrReadFrame(XdrFile& xd, Frame& fr, bool& bOK, double* lambda)
{
    bOK = true;
    int magic;
    if (!xd.getInt(magic))
    {
        return false;
    }
    if (magic != 1993)
    {
        bOK = false;
        return false;
    }
    int         slen;
    std::string ver;
    if (!xd.getInt(slen) || !xd.getString(ver))
    {
        bOK = false;
        return false;
    }
    int sz[13];
    for (int i = 0; i < 13; i++)
    {
        if (!xd.getInt(sz[i]))
        {
            bOK = false;
            return false;
        }
    }
    int ir_size = sz[0], e_size = sz[1], box_size = sz[2], vir_size = sz[3], pres_size = sz[4], top_size = sz[5],
        sym_size = sz[6], x_size = sz[7], v_size = sz[8], f_size = sz[9], natoms = sz[10], step = sz[11];
    (void)ir_size;
    (void)e_size;
    (void)top_size;
    (void)sym_size;
    bool bDouble = false;
    int  nflsize = 0;
    if (box_size)
    {
        nflsize = box_size / 9;
    }
    else if (x_size && natoms)
    {
        nflsize = x_size / (natoms * 3);
    }
    else if (v_size && natoms)
    {
        nflsize = v_size / (natoms * 3);
    }
    else if (f_size && natoms)
    {
        nflsize = f_size / (natoms * 3);
    }
    bDouble = nflsize == 8;
    auto getReal = [&](double& v) -> bool {
        if (bDouble)
        {
            return xd.getDouble(v);
        }
        float f;
        bool  ok = xd.getFloat(f);
        v        = f;
        return ok;
    };
    double t, lam;
    if (!getReal(t) || !getReal(lam))
    {
        bOK = false;
        return false;
    }
    if (lambda)
    {
        *lambda = lam;
    }
    auto readMat = [&](Matrix m) {
        for (int i = 0; i < 3; i++)
        {
            for (int j = 0; j < 3; j++)
            {
                double v;
                getReal(v);
                m[i][j] = (real)v;
            }
        }
    };
    Matrix dummy;
    fr.bBox = box_size > 0;
    if (box_size)
    {
        readMat(fr.box);
    }
    if (vir_size)
    {
        readMat(dummy);
    }
    if (pres_size)
    {
        readMat(dummy);
    }
    auto readVecs = [&](std::vector<RVec>& vv) {
        vv.assign(natoms, RVec{ 0, 0, 0 });
        for (int i = 0; i < natoms; i++)
        {
            for (int d = 0; d < 3; d++)
            {
                double v;
                getReal(v);
                vv[i][d] = (real)v;
            }
        }
    };
    fr.bX = x_size > 0;
    fr.bV = v_size > 0;
    fr.bF = f_size > 0;
    if (x_size)
    {
        readVecs(fr.x);
    }
    if (v_size)
    {
        readVecs(fr.v);
    }
    if (f_size)
    {
        readVecs(fr.f);
    }
    fr.natoms = natoms;
    fr.step   = step;
    fr.bStep  = true;
    fr.time   = t;
    fr.bTime  = true;
    fr.bPrec  = false;
    return true;
}

void trrWriteFrame(XdrFile& xd, int64_t step, float time, float lambda, const Matrix* box, int natoms,
                   const std::vector<RVec>* x, const std::vector<RVec>* v, const std::vector<RVec>* f)
{
    xd.putInt(1993);
    std::string ver = "GMX_trn_file";
    xd.putInt((int)ver.size() + 1);
    xd.putString(ver);
    int fl = 4;
    xd.putInt(0);                                  // ir_size
    xd.putInt(0);                                  // e_size
    xd.putInt(box ? 9 * fl : 0);                   // box_size
    xd.putInt(0);                                  // vir
    xd.putInt(0);                                  // pres
    xd.putInt(0);                                  // top
    xd.putInt(0);                                  // sym
    xd.putInt(x ? natoms * 3 * fl : 0);
    xd.putInt(v ? natoms * 3 * fl : 0);
    xd.putInt(f ? natoms * 3 * fl : 0);
    xd.putInt(natoms);
    xd.putInt((int)step);
    xd.putInt(0); // nre
    xd.putFloat(time);
    xd.putFloat(lambda);
    if (box)
    {
        for (int i = 0; i < 3; i++)
        {
            for (int j = 0; j < 3; j++)
            {
                xd.putFloat((*box)[i][j]);
            }
        }
    }
    auto wr = [&](const std::vector<RVec>* vv) {
        if (!vv)
        {
            return;
        }
        for (int i = 0; i < natoms; i++)
        {
            for (int d = 0; d < 3; d++)
            {
                xd.putFloat((*vv)[i][d]);
            }
        }
    };
    wr(x);
    wr(v);
    wr(f);
}

