static const char* ftpDescription(FileType t)
{
    switch (t)
    {
        case FileType::XTC: return "xtc: Compressed trajectory (portable xdr format): xtc";
        case FileType::TRR: return "trr: Trajectory in portable xdr format";
        case FileType::GRO: return "gro: Coordinate file in Gromos-87 format";
        case FileType::PDB: return "pdb: Protein data bank file";
        case FileType::G96: return "g96: Coordinate file in Gromos-96 format";
        case FileType::TNG: return "tng: Trajectory file (tng format)";
        default: return "";
    }
}

static void printReadingHeader(const std::string& fn, const Frame& fr)
{
    FileType ft = fileTypeOf(fn);
    if (ft == FileType::GRO)
    {
        fprintf(stderr, "Reading frames from gro file '%s', %d atoms.\n", fr.title.c_str(), fr.natoms);
    }
}

int runTrjconv(Options& opts)
{
    printMajorChangesNote("trjconv");
