    {
        gmx_fatal("src/gromacs/fileio/tngio.cpp", 100, "TNG output is not supported");
    }
    double prec = opts.getReal("ndec");
    prec        = std::pow(10.0, prec);
    // first pass for header messages
    {
        TrajectoryReader rd(fin);
        Frame            fr;
        if (rd.next(fr))
        {
