    XdrFile*         xd       = nullptr;
    int              nwritten = 0;
    double           lastT    = 0;
    int              lastIdx  = 0;
    bool             first    = true;
    double           tb = opts.getReal("b"), te = opts.getReal("e");
    bool             bTb = opts.isSet("b"), bTe = opts.isSet("e");
    while (rd.next(fr))
    {
        if (first)
        {
            printReadingHeader(fin, fr);
            printFrameProgress("Reading frame", fr.index, fr.time);
            fprintf(stderr, "\n");
            if (fr.bPrec)
            {
                fprintf(stderr, "Precision of %s is %g (nm)\n", fin.c_str(), fr.prec);
            }
            if (ftOut == FileType::XTC)
            {
                fprintf(stderr, "Using output precision of %g (nm)\n", 1.0 / prec);
            }
            makeBackup(out);
            xd = new XdrFile(out, "wb");
            if (!xd->ok())
            {
                gmx_fatal("src/gromacs/utility/futil.cpp", 472, "Cannot open file '%s'", out.c_str());
            }
        }
        else
        {
            printFrameProgress("Reading frame", fr.index, fr.time);
        }
        lastT   = fr.time;
        lastIdx = fr.index;
        if ((bTb && fr.time < tb) || (bTe && fr.time > te))
        {
            first = false;
            continue;
        }
        int64_t step = fr.bStep ? fr.step : fr.index;
        if (ftOut == FileType::XTC)
        {
            xtcWriteFrame(*xd, fr.natoms, step, (float)fr.time, fr.box, fr.x, (float)prec);
        }
        else if (ftOut == FileType::TRR)
        {
            trrWriteFrame(*xd, step, (float)fr.time, 0, &fr.box, fr.natoms, &fr.x, fr.bV ? &fr.v : nullptr,
                          fr.bF ? &fr.f : nullptr);
        }
        if (!first)
        {
            fprintf(stderr, " ->  frame %6d time %8.3f      \r", nwritten, fr.time);
        }
        nwritten++;
        first = false;
    }
    delete xd;
    fprintf(stderr, "\r%-14s %6d time %8.3f   \n", "Last frame", lastIdx, lastT);
    fprintf(stderr, " ->  frame %6d time %8.3f      \r\n", nwritten - 1, lastT);
    fprintf(stderr, "Last written: frame %6d time %8.3f\n\n", nwritten - 1, lastT);
    return 0;
}

int runCheck(Options& opts)
{
    if (opts.isSet("f"))
    {
        std::string fn = opts.fileName("f");
        if (opts.isSet("f2"))
        {
            fprintf(stderr, "Comparing trajectory files %s and %s\n", fn.c_str(), opts.fileName("f2").c_str());
