        requireResidueTypes();
    }
    if (opts.isSet("s1") || opts.isSet("s2"))
    {
        if (opts.isSet("s1"))
        {
            readTprFail(opts.fileName("s1"));
        }
        readTprFail(opts.fileName("s2"));
    }
    return 0;
}

