{"command":"cat >> /workspace/src/tools/trjconv.cpp <<'EOF'

namespace gmx
{

int runTrjcat2(Options& opts)
{
    printMajorChangesNote("trjcat");
    fflush(stdout);
    std::vector<std::string> files = opts.fileNames("f");
    for (const auto& f : files)
    {
        FileType t = fileTypeOf(f);
        if (t != FileType::XTC && t != FileType::TRR && t != FileType::TNG)
        {
            gmx_fatal("src/gromacs/tools/trjcat.cpp", 595,
                      "gmx trjcat can only handle binary trajectory formats (trr, xtc, tng)");
        }
    }
    std::string out   = opts.fileName("o");
    FileType    ftOut = fileTypeOf(out);
    bool        bCat  = opts.getBool("cat");
    bool        bSort = opts.getBool("sort");
    struct FInfo
    {
        std::string fn;
        double      start = 0, dt = 0;
        int         order = 0;
    };
    std::vector<FInfo> info;
    fprintf(stderr, "\n");
    for (size_t i = 0; i < files.size(); i++)
    {
        FInfo fi;
        fi.fn    = files[i];
        fi.order = (int)i;
        TrajectoryReader rd(files[i]);
        Frame            fr;
        if (rd.next(fr))
        {
            printFrameProgress("Reading frame", 0, fr.time);
            fprintf(stderr, "\n");
            fi.start = fr.time;
            if (rd.next(fr))
            {
                printFrameProgress("Reading frame", 1, fr.time);
                fprintf(stderr, "\n");
                fi.dt = fr.time - fi.start;
            }
        }
        info.push_back(fi);
    }
    if (bSort && !bCat)
    {
        std::stable_sort(info.begin(), info.end(), [](const FInfo& a, const FInfo& b) { return a.start < b.start; });
    }
    fprintf(stderr, "\nSummary of files and start times used:\n\n");
    fprintf(stderr, "          File                Start time       Time step\n");
    fprintf(stderr, "---------------------------------------------------------\n");
    for (size_t i = 0; i < info.size(); i++)
    {
        fprintf(stderr, "%25s   %10.3f ps   %10.3f ps", info[i].fn.c_str(), info[i].start, info[i].dt);
        if (i > 0 && info[i].start == info[i - 1].start)
        {
            fprintf(stderr, " WARNING: same Start time as previous");
        }
        fprintf(stderr, "\n");
    }
    fprintf(stderr, "\n");
    makeBackup(out);
    XdrFile xd(out, "wb");
    if (!xd.ok())
    {
        gmx_fatal("src/gromacs/utility/futil.cpp", 472, "Cannot open file '%s'", out.c_str());
    }
    double lasttime = 0;
    int    nwritten = 0;
    double lastWrittenT = 0;
    for (size_t i = 0; i < info.size(); i++)
    {
        printf("\nlasttime %g\n", lasttime);
        fprintf(stderr, "\n");
        bool             hasNext = (i + 1 < info.size()) && !bCat;
        double           tnext   = hasNext ? info[i + 1].start : 0;
        TrajectoryReader rd(info[i].fn);
        Frame            fr;
        bool             firstInFile = true;
        int              lastIdx     = 0;
        double           lastT       = 0;
        while (rd.next(fr))
        {
            printFrameProgress("Reading frame", fr.index, fr.time);
            lastIdx = fr.index;
            lastT   = fr.time;
            if (hasNext && fr.time >= tnext)
            {
                continue;
            }
            if (firstInFile)
            {
                fprintf(stderr, "\nContinue writing frames from %s t=%g ps, frame=%d      \n", info[i].fn.c_str(),
                        fr.time, nwritten);
                firstInFile = false;
            }
            float prec = fr.bPrec && fr.prec > 0 ? (float)(1.0 / fr.prec) : 1000.0f;
            if (ftOut == FileType::XTC)
            {
                xtcWriteFrame(xd, fr.natoms, fr.step, (float)fr.time, fr.box, fr.x, prec);
            }
            else
            {
                trrWriteFrame(xd, fr.step, (float)fr.time, 0, &fr.box, fr.natoms, &fr.x, fr.bV ? &fr.v : nullptr,
                              fr.bF ? &fr.f : nullptr);
            }
            fprintf(stderr, " ->  frame %6d time %8.3f ps     \n", nwritten, fr.time);
            nwritten++;
            lastWrittenT = fr.time;
            lasttime     = fr.time;
        }
        fprintf(stderr, "\r%-14s %6d time %8.3f   \n", "Last frame", lastIdx, lastT);
    }
    fprintf(stderr, "\nLast frame written was %d, time %f ps\n", nwritten - 1, lastWrittenT);
    return 0;
}

} // namespace gmx
