// gmx grompp (very small subset: emulates early failures).
#include <random>

#include "../modules.h"
#include "../toolcommon.h"

namespace gmx
{

static std::string mdpValue(const std::string& fn, const std::string& key, bool& found)
{
    found    = false;
    FILE* fp = fopen(fn.c_str(), "r");
    if (!fp)
    {
        return "";
    }
    char        buf[4096];
    std::string val;
    while (fgets(buf, sizeof(buf), fp))
    {
        std::string l = buf;
        size_t      c = l.find(';');
        if (c != std::string::npos)
        {
            l = l.substr(0, c);
        }
        size_t eq = l.find('=');
        if (eq == std::string::npos)
        {
            continue;
        }
        std::string k = trim(l.substr(0, eq));
        for (auto& ch : k)
        {
            if (ch == '_')
            {
                ch = '-';
            }
        }
        if (k == key)
        {
            val   = trim(l.substr(eq + 1));
            found = true;
        }
    }
    fclose(fp);
    return val;
}

static void checkIncludes(const std::string& fn, int depth)
{
    FILE* fp = fopen(fn.c_str(), "r");
    if (!fp)
    {
        return;
    }
    char buf[4096];
    std::string dir = fn.find('/') == std::string::npos ? "" : fn.substr(0, fn.rfind('/') + 1);
    while (fgets(buf, sizeof(buf), fp))
    {
        std::string l = trim(buf);
        if (startsWith(l, "#include"))
        {
            size_t a = l.find('"');
            size_t b = a == std::string::npos ? std::string::npos : l.find('"', a + 1);
            if (a == std::string::npos || b == std::string::npos)
            {
                continue;
            }
            std::string inc = l.substr(a + 1, b - a - 1);
            std::string path;
            if (fileExists(dir + inc))
            {
                path = dir + inc;
            }
            else if (fileExists(inc))
            {
                path = inc;
            }
            else
            {
                std::string lib = libSearchFile(inc, false);
                if (!lib.empty())
                {
                    path = lib;
                }
            }
            if (path.empty())
            {
                fclose(fp);
                gmx_fatal("src/gromacs/gmxpreprocess/gmxcpp.cpp", 297, "Topology include file \"%s\" not found",
                          inc.c_str());
            }
            if (depth < 20)
            {
                checkIncludes(path, depth + 1);
            }
        }
    }
    fclose(fp);
}

int runGrompp(Options& opts)
{
    std::string mdp = opts.fileName("f");
    bool        found;
    std::string seed = mdpValue(mdp, "ld-seed", found);
    long long   s    = found ? atoll(seed.c_str()) : -1;
    if (s == -1)
    {
        std::random_device rd;
        int                v = (int)(rd() & 0x7fffffff);
        if (rd() & 1)
        {
            v = -v;
        }
        printf("Setting the LD random seed to %d\n", v);
    }
    fflush(stdout);
    checkIncludes(opts.fileName("p"), 0);
    Structure st;
    readTps(opts.fileName("c"), st);
    requireResidueTypes();
    return 0;
}

} // namespace gmx
