output.arguments:
{"command":"cat > /workspace/src/tools/editconf.cpp <<'EOF'
// gmx editconf (subset, used when residuetypes.dat is available).
#include "../modules.h"
#include "../toolcommon.h"

namespace gmx
{

static double vnorm(const real* v)
{
    return std::sqrt((double)v[0] * v[0] + (double)v[1] * v[1] + (double)v[2] * v[2]);
}

static double vangle(const real* a, const real* b)
{
    // GROMACS gmx_angle: atan2(|a x b|, a.b)
    double w[3] = { (double)a[1] * b[2] - (double)a[2] * b[1], (double)a[2] * b[0] - (double)a[0] * b[2],
                    (double)a[0] * b[1] - (double)a[1] * b[0] };
    double wl   = std::sqrt(w[0] * w[0] + w[1] * w[1] + w[2] * w[2]);
    double ip   = (double)a[0] * b[0] + (double)a[1] * b[1] + (double)a[2] * b[2];
    return std::atan2(wl, ip);
}

static double det3(const Matrix b)
{
    return (double)b[0][0] * b[1][1] * b[2][2] - (double)b[0][0] * b[2][1] * b[1][2] - (double)b[1][0] * b[0][1] * b[2][2]
           + (double)b[1][0] * b[2][1] * b[0][2] + (double)b[2][0] * b[0][1] * b[1][2] - (double)b[2][0] * b[1][1] * b[0][2];
}

static void printBox(const char* prefix, const Matrix box)
{
    const double r2d = 180.0 / M_PI;
    printf("%sbox vectors :%7.3f%7.3f%7.3f (nm)\n", prefix, vnorm(box[0]), vnorm(box[1]), vnorm(box[2]));
    auto n2 = [](const real* v) { return (double)v[0] * v[0] + (double)v[1] * v[1] + (double)v[2] * v[2]; };
    printf("%sbox angles  :%7.2f%7.2f%7.2f (degrees)\n", prefix,
           n2(box[2]) == 0 ? 0 : r2d * vangle(box[1], box[2]), n2(box[2]) == 0 ? 0 : r2d * vangle(box[0], box[2]),
           n2(box[1]) == 0 ? 0 : r2d * vangle(box[0], box[1]));
    printf("%sbox volume  :%7.2f               (nm^3)\n", prefix, det3(box));
}

struct Geom
{
    real   min[3], max[3], size[3], center[3];
    double diam = 0;
};

static Geom calcGeom(const Structure& s, bool bDiam)
{
    Geom g;
    int  n = s.natoms();
    for (int d = 0; d < 3; d++)
    {
        g.min[d] = n ? s.x[0][d] : 0;
        g.max[d] = n ? s.x[0][d] : 0;
    }
    double sum[3] = { 0, 0, 0 };
    for (int i = 0; i < n; i++)
    {
        for (int d = 0; d < 3; d++)
        {
            g.min[d] = std::min(g.min[d], s.x[i][d]);
            g.max[d] = std::max(g.max[d], s.x[i][d]);
            sum[d] += s.x[i][d];
        }
    }
    for (int d = 0; d < 3; d++)
    {
        g.size[d]   = g.max[d] - g.min[d];
        g.center[d] = n ? (real)(sum[d] / n) : 0;
    }
    if (bDiam)
    {
        double best = 0;
        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                double d2 = 0;
                for (int d = 0; d < 3; d++)
                {
                    double dx = (double)s.x[i][d] - s.x[j][d];
                    d2 += dx * dx;
                }
                best = std::max(best, d2);
            }
        }
        g.diam = std::sqrt(best);
    }
    return g;
}

int runEditconfFull(Options& opts)
{
    printMajorChangesNote("editconf");
    fflush(stdout);
    requireResidueTypes();
    std::string infile = opts.fileName("f");
    Structure   s;
    if (fileTypeOf(infile) == FileType::PDB)
    {
        libSearchFile("elements.dat", true);
    }
    readTps(infile, s);
    if (opts.getBool("princ") || opts.isSet("density"))
    {
        libSearchFile("atommass.dat", true);
    }
    int natoms = s.natoms();
    printf("Read %d atoms\n", natoms);
    double vol = det3(s.box);
    printf("Volume: %g nm^3, corresponds to roughly %d electrons\n", vol, 100 * (int)(vol * 4.5));
    if (s.haveV)
    {
        printf("Velocities found\n");
    }
    double boxv[3], ang[3], ctr[3], trans[3], rot[3], scale[3];
    opts.getVec("box", boxv);
    opts.getVec("angles", ang);
    opts.getVec("center", ctr);
    opts.getVec("translate", trans);
    opts.getVec("rotate", rot);
    opts.getVec("scale", scale);
    double      dist     = opts.getReal("d");
    std::string bt       = opts.getEnum("bt");
    bool        bSetBox  = opts.isSet("box");
    bool        bDist    = opts.isSet("d");
    bool        bSetAng  = opts.isSet("angles");
    bool        bSetSize = bSetBox || bDist;
    bool        bSetCenter = opts.isSet("center");
    bool        bCenter;
    if (opts.isSet("c"))
    {
        bCenter = opts.getBool("c");
    }
    else
    {
        bCenter = bSetSize;
    }
    bool bTranslate = opts.isSet("translate");
    bool bRotate    = opts.isSet("rotate");
    bool bScale     = opts.isSet("scale");
    bool bTric      = bt == "triclinic";
    bool bCalcDiam  = !bTric && (bSetSize || bDist);
    bool bCalcGeom  = bCenter || bSetCenter || bRotate || bScale || bDist || bCalcDiam;

    if (bDist && bSetAng)
    {
        gmx_fatal("src/gromacs/gmxpreprocess/editconf.cpp", 950, "Cannot use -angles with -d");
    }

    Geom g{};
    if (bCalcGeom)
    {
        g = calcGeom(s, bCalcDiam);
        printf("    system size :%7.3f%7.3f%7.3f (nm)\n", g.size[0], g.size[1], g.size[2]);
        if (bCalcDiam)
        {
            printf("    diameter    :%7.3f               (nm)\n", g.diam);
        }
        printf("    center      :%7.3f%7.3f%7.3f (nm)\n", g.center[0], g.center[1], g.center[2]);
        printBox("    ", s.box);
    }
    if (bTranslate)
    {
        printf("Translating %d atoms (out of %d) by %g %g %g nm\n", natoms, natoms, trans[0], trans[1], trans[2]);
        for (int i = 0; i < natoms; i++)
        {
            for (int d = 0; d < 3; d++)
            {
                s.x[i][d] += (real)trans[d];
            }
        }
    }
    bool bBoxChanged = false;
    if (bScale)
    {
        for (int i = 0; i < natoms; i++)
        {
            for (int d = 0; d < 3; d++)
            {
                s.x[i][d] *= (real)scale[d];
            }
        }
        for (int i = 0; i < 3; i++)
        {
            for (int d = 0; d < 3; d++)
            {
                s.box[i][d] *= (real)scale[d];
            }
        }
        bBoxChanged = true;
    }
    if (bRotate)
    {
        printf("Rotating %g, %g, %g degrees around the X, Y and Z axis respectively\n", rot[0], rot[1], rot[2]);
        for (int k = 0; k < 3; k++)
        {
            real a  = (real)(rot[k] * M_PI / 180.0);
            real ca = std::cos(a), sa = std::sin(a);
            auto rotv = [&](RVec& v) {
                real x = v[0], y = v[1], z = v[2];
                if (k == 0)
                {
                    v[1] = ca * y - sa * z;
                    v[2] = sa * y + ca * z;
                }
                else if (k == 1)
                {
                    v[0] = ca * x + sa * z;
                    v[2] = -sa * x + ca * z;
                }
                else
                {
                    v[0] = ca * x - sa * y;
                    v[1] = sa * x + ca * y;
                }
            };
            for (int i = 0; i < natoms; i++)
            {
                rotv(s.x[i]);
                rotv(s.v[i]);
            }
        }
    }
    if (bRotate || bScale)
    {
        g = calcGeom(s, false);
        printf("new system size :%7.3f%7.3f%7.3f\n", g.size[0], g.size[1], g.size[2]);
    }
    if (bTranslate && bCalcGeom)
    {
        g = calcGeom(s, false);
    }
    if (bSetSize)
    {
        double a[3];
        if (bDist)
        {
            for (int d = 0; d < 3; d++)
            {
                a[d] = bTric ? g.size[d] + 2 * dist : g.diam + 2 * dist;
            }
        }
        else
        {
            for (int d = 0; d < 3; d++)
            {
                a[d] = bTric ? boxv[d] : boxv[0];
            }
        }
        for (int i = 0; i < 3; i++)
        {
            for (int j = 0; j < 3; j++)
            {
                s.box[i][j] = 0;
            }
        }
        if (bt == "triclinic" || bt == "cubic")
        {
            for (int d = 0; d < 3; d++)
            {
                s.box[d][d] = (real)a[d];
            }
            if (bSetAng && bTric)
            {
                real alpha = (real)ang[0], beta = (real)ang[1], gamma = (real)ang[2];
                const real deg2rad = (real)(M_PI / 180.0);
                s.box[1][0] = s.box[1][1] * std::cos(gamma * deg2rad);
                s.box[1][1] = s.box[1][1] * std::sin(gamma * deg2rad);
                s.box[2][0] = s.box[2][2] * std::cos(beta * deg2rad);
                s.box[2][1] = s.box[2][2] * (std::cos(alpha * deg2rad) - std::cos(beta * deg2rad) * std::cos(gamma * deg2rad))
                              / std::sin(gamma * deg2rad);
                s.box[2][2] = std::sqrt(s.box[2][2] * s.box[2][2] - s.box[2][0] * s.box[2][0] - s.box[2][1] * s.box[2][1]);
            }
        }
        else if (bt == "dodecahedron")
        {
            real d = (real)a[0];
            s.box[0][0] = d;
            s.box[1][1] = d;
            s.box[2][0] = d / 2;
            s.box[2][1] = d / 2;
            s.box[2][2] = (real)(d * std::sqrt(2.0) / 2);
        }
        else if (bt == "octahedron")
        {
            real d = (real)a[0];
            s.box[0][0] = d;
            s.box[1][0] = d / 3;
            s.box[1][1] = (real)(d * 2 * std::sqrt(2.0) / 3);
            s.box[2][0] = -d / 3;
            s.box[2][1] = (real)(d * std::sqrt(2.0) / 3);
            s.box[2][2] = (real)(d * std::sqrt(6.0) / 3);
        }
        bBoxChanged = true;
    }
    if (bCenter || bSetCenter)
    {
        real target[3];
        if (bSetCenter)
        {
            for (int d = 0; d < 3; d++)
            {
                target[d] = (real)ctr[d];
            }
        }
        else
        {
            for (int d = 0; d < 3; d++)
            {
                target[d] = (s.box[0][d] + s.box[1][d] + s.box[2][d]) / 2;
            }
        }
        real shift[3];
        for (int d = 0; d < 3; d++)
        {
            shift[d] = target[d] - g.center[d];
        }
        printf("    shift       :%7.3f%7.3f%7.3f (nm)\n", shift[0], shift[1], shift[2]);
        for (int i = 0; i < natoms; i++)
        {
            for (int d = 0; d < 3; d++)
            {
                s.x[i][d] += shift[d];
            }
        }
        for (int d = 0; d < 3; d++)
        {
            g.center[d] += shift[d];
        }
    }
    if (bCalcGeom)
    {
        if (bRotate || bScale)
        {
            if (!(bCenter || bSetCenter))
            {
                g = calcGeom(s, false);
            }
        }
        printf("new center      :%7.3f%7.3f%7.3f (nm)\n", g.center[0], g.center[1], g.center[2]);
    }
    if (bBoxChanged || bSetAng)
    {
        printBox("new ", s.box);
    }
    if (bDist && bTric)
    {
        fprintf(stderr, "\nWARNING: No boxtype specified - distance condition applied in each dimension.\n"
                        "If the molecule rotates the actual distance will be smaller. You might want\n"
                        "to use a cubic box instead, or why not try a dodecahedron today?\n");
    }
    if (det3(s.box) < 0)
    {
        fprintf(stderr, "\nWARNING: Triclinic box is too skewed.\n"
                        "See the GROMACS manual for a description of the requirements that\n"
                        "must be satisfied by descriptions of simulation cells.\n");
    }
    if (opts.isSet("resnr"))
    {
        int r0 = opts.getInt("resnr");
        for (size_t r = 0; r < s.res.size(); r++)
        {
            s.res[r].nr = r0 + (int)r;
        }
    }
    if (opts.isSet("o") || true)
    {
        std::string out = opts.fileName("o");
        if (fileTypeOf(out) == FileType::PDB && opts.isSet("label"))
        {
            std::string lab = opts.getString("label");
            for (auto& r : s.res)
            {
                r.chain = lab.empty() ? ' ' : lab[0];
            }
        }
        writeStructure(out, s);
    }
    return 0;
}

} // namespace gmx
