        sys.atoms.push_back(i);
    }
    g.push_back(sys);
    printf("Analysing residue names:\n");
    std::vector<std::string> rtype(s.res.size());
    std::vector<std::string> order;
    std::map<std::string, int> count;
    for (size_t r = 0; r < s.res.size(); r++)
    {
        rtype[r] = residueTypeOf(s.res[r].name);
        if (!count.count(rtype[r]))
        {
            order.push_back(rtype[r]);
        }
        count[rtype[r]]++;
    }
    for (const auto& t : order)
    {
        printf("There are: %5d %10s residues\n", count[t], t.c_str());
    }
    auto atype = [&](int i) { return rtype[s.atoms[i].resind]; };
    bool bProt = count.count("Protein") > 0;
    if (bProt)
    {
        printf("Analysing Protein...\n");
        NGroup prot{ "Protein", {} }, pnoh{ "Protein-H", {} }, ca{ "C-alpha", {} }, bb{ "Backbone", {} },
                mc{ "MainChain", {} }, mcb{ "MainChain+Cb", {} }, mch{ "MainChain+H", {} }, sc{ "SideChain", {} },
                sch{ "SideChain-H", {} }, pm{ "Prot-Masses", {} }, np{ "non-Protein", {} };
        for (int i = 0; i < n; i++)
        {
            const std::string& an = s.atoms[i].name;
            if (atype(i) != "Protein")
            {
                np.atoms.push_back(i);
                continue;
            }
            bool isH   = !an.empty() && (an[0] == 'H' || (an.size() > 1 && isdigit((unsigned char)an[0]) && an[1] == 'H'));
            bool isMC  = nameIn(an, { "N", "CA", "C", "O", "O1", "O2", "OC1", "OC2", "OT", "OXT" });
            bool isMCH = isMC || nameIn(an, { "H1", "H2", "H3", "H", "HN" });
            prot.atoms.push_back(i);
            if (!isH)
            {
                pnoh.atoms.push_back(i);
            }
            if (an == "CA")
            {
                ca.atoms.push_back(i);
            }
            if (nameIn(an, { "N", "CA", "C" }))
            {
                bb.atoms.push_back(i);
            }
            if (isMC)
            {
                mc.atoms.push_back(i);
            }
            if (isMC || an == "CB")
            {
                mcb.atoms.push_back(i);
            }
            if (isMCH)
            {
                mch.atoms.push_back(i);
            }
            if (!isMCH)
            {
                sc.atoms.push_back(i);
                if (!isH)
                {
                    sch.atoms.push_back(i);
                }
            }
            if (!startsWith(an, "MN"))
            {
                pm.atoms.push_back(i);
            }
        }
        for (auto* x : { &prot, &pnoh, &ca, &bb, &mc, &mcb, &mch, &sc, &sch, &pm })
        {
            g.push_back(*x);
        }
        if (!np.atoms.empty())
        {
            g.push_back(np);
        }
    }
    bool bWater = count.count("Water") > 0;
    bool bIon   = count.count("Ion") > 0;
    if (bWater)
    {
        NGroup w{ "Water", {} }, nw{ "non-Water", {} };
        std::vector<std::string> wnames;
        for (int i = 0; i < n; i++)
        {
            if (atype(i) == "Water")
            {
                w.atoms.push_back(i);
                const std::string& rn = s.res[s.atoms[i].resind].name;
                if (std::find(wnames.begin(), wnames.end(), rn) == wnames.end())
                {
                    wnames.push_back(rn);
                }
            }
            else
            {
                nw.atoms.push_back(i);
            }
        }
        g.push_back(w);
        for (const auto& rn : wnames)
        {
            NGroup x{ rn, {} };
            for (int i = 0; i < n; i++)
            {
                if (atype(i) == "Water" && s.res[s.atoms[i].resind].name == rn)
                {
                    x.atoms.push_back(i);
                }
            }
            g.push_back(x);
        }
        if (!nw.atoms.empty())
        {
            g.push_back(nw);
        }
    }
    if (bIon)
    {
        NGroup x{ "Ion", {} };
        for (int i = 0; i < n; i++)
        {
            if (atype(i) == "Ion")
            {
                x.atoms.push_back(i);
            }
        }
        g.push_back(x);
    }
    bool bOther = false;
    for (const auto& t : order)
    {
        if (t != "Protein" && t != "DNA" && t != "RNA" && t != "Water")
        {
            bOther = true;
        }
    }
    if (bOther)
    {
        if (count.count("Other"))
        {
            NGroup x{ "Other", {} };
            for (int i = 0; i < n; i++)
            {
                if (atype(i) == "Other")
                {
                    x.atoms.push_back(i);
                }
            }
            g.push_back(x);
        }
        printf("Analysing residues not classified as Protein/DNA/RNA/Water and splitting into groups...\n");
        std::vector<std::string> names;
        for (size_t r = 0; r < s.res.size(); r++)
        {
            const std::string& t = rtype[r];
            if (t == "Protein" || t == "DNA" || t == "RNA" || t == "Water")
            {
                continue;
            }
            if (std::find(names.begin(), names.end(), s.res[r].name) == names.end())
            {
                names.push_back(s.res[r].name);
            }
        }
        for (const auto& rn : names)
        {
            NGroup x{ rn, {} };
            for (int i = 0; i < n; i++)
            {
                const std::string& t = atype(i);
                if (t != "Protein" && t != "DNA" && t != "RNA" && t != "Water"
                    && s.res[s.atoms[i].resind].name == rn)
                {
                    x.atoms.push_back(i);
                }
            }
            g.push_back(x);
        }
    }
    if (bWater && bIon)
    {
        NGroup x{ "Water_and_ions", {} };
        for (int i = 0; i < n; i++)
        {
            if (atype(i) == "Water" || atype(i) == "Ion")
            {
                x.atoms.push_back(i);
            }
        }
        g.push_back(x);
    }
    return g;
}

static bool parseGroupRef(const std::string& tok, const std::vector<NGroup>& groups, int& idx)
{
    char* end = nullptr;
    long  v   = strtol(tok.c_str(), &end, 10);
    if (end && *end == '\0' && !tok.empty())
    {
        if (v >= 0 && v < (long)groups.size())
        {
            idx = (int)v;
            return true;
        }
        return false;
    }
    std::string name = tok;
    if (name.size() >= 2 && name.front() == '"' && name.back() == '"')
    {
        name = name.substr(1, name.size() - 2);
    }
    for (size_t i = 0; i < groups.size(); i++)
    {
        if (strcasecmp(groups[i].name.c_str(), name.c_str()) == 0)
        {
            idx = (int)i;
            return true;
        }
    }
    return false;
}

int runMakeNdxFull(Options& opts)
{
    fprintf(stderr, "\nReading structure file\n");
    Structure s;
    bool      haveS = opts.isSet("f") || !opts.isSet("n");
    if (haveS)
    {
        readTps(opts.fileName("f"), s);
    }
    int nold = 0;
    std::vector<NGroup> groups;
    if (opts.isSet("n"))
    {
        nold = (int)opts.fileNames("n").size();
    }
    printf("Going to read %d old index file(s)\n", nold);
    fflush(stdout);
    if (haveS)
    {
        requireResidueTypes();
        groups = defaultGroups(s);
    }
    int natoms = s.natoms();
    listGroups(groups);
    printHelpBlock();
    printf("\n> ");
    fflush(stdout);
    char buf[4096];
    while (fgets(buf, sizeof(buf), stdin))
    {
        std::string line = trim(buf);
        printf("\n");
        if (line.empty())
        {
            listGroups(groups);
            printHelpBlock();
        }
        else if (line == "q")
        {
            break;
        }
        else if (line == "l")
        {
            for (size_t r = 0; r < s.res.size(); r++)
            {
                printf("%4d %-5s", s.res[r].nr, s.res[r].name.c_str());
                if ((r + 1) % 6 == 0)
                {
                    printf("\n");
                }
            }
            printf("\n");
        }
        else if (line[0] == 'a' && (line.size() == 1 || line[1] == ' '))
        {
            std::vector<std::string> toks = splitWS(line.substr(1));
            NGroup                   ng;
            ng.name = "a";
            for (const auto& t : toks)
            {
                ng.name += "_" + t;
            }
            for (const auto& t : toks)
            {
                size_t dash = t.find('-');
                if (dash != std::string::npos && isdigit((unsigned char)t[0]))
                {
                    int a = atoi(t.substr(0, dash).c_str()), b = atoi(t.substr(dash + 1).c_str());
                    for (int i = a; i <= b; i++)
                    {
                        if (i >= 1 && i <= natoms)
                        {
                            ng.atoms.push_back(i - 1);
                        }
                    }
                    printf("Found %d atoms in range %d-%d\n", (int)ng.atoms.size(), a, b);
                }
                else if (isdigit((unsigned char)t[0]))
                {
                    int i = atoi(t.c_str());
                    if (i >= 1 && i <= natoms)
                    {
                        ng.atoms.push_back(i - 1);
                    }
                }
                else
                {
                    int cnt = 0;
                    for (int i = 0; i < natoms; i++)
                    {
                        if (s.atoms[i].name == t)
                        {
                            ng.atoms.push_back(i);
                            cnt++;
                        }
                    }
                    printf("Found %d atoms with name %s\n", cnt, t.c_str());
                }
            }
            std::sort(ng.atoms.begin(), ng.atoms.end());
            ng.atoms.erase(std::unique(ng.atoms.begin(), ng.atoms.end()), ng.atoms.end());
            groups.push_back(ng);
        }
        else if (line[0] == 'r' && (line.size() == 1 || line[1] == ' '))
        {
            std::vector<std::string> toks = splitWS(line.substr(1));
            NGroup                   ng;
            ng.name = "r";
            for (const auto& t : toks)
            {
                ng.name += "_" + t;
            }
            for (const auto& t : toks)
            {
                if (isdigit((unsigned char)t[0]))
                {
                    size_t dash = t.find('-');
                    int    a = atoi(t.c_str()), b = dash != std::string::npos ? atoi(t.substr(dash + 1).c_str()) : a;
                    for (int i = 0; i < natoms; i++)
                    {
                        int rn = s.res[s.atoms[i].resind].nr;
                        if (rn >= a && rn <= b)
                        {
                            ng.atoms.push_back(i);
                        }
                    }
                    if (dash != std::string::npos)
                    {
                        printf("Found %d atoms with res.nr. in range %d-%d\n", (int)ng.atoms.size(), a, b);
                    }
                }
                else
                {
                    int cnt = 0;
                    for (int i = 0; i < natoms; i++)
                    {
                        if (s.res[s.atoms[i].resind].name == t)
                        {
                            ng.atoms.push_back(i);
                            cnt++;
                        }
                    }
                    printf("Found %d atoms with residue name %s\n", cnt, t.c_str());
                }
            }
            if (toks.size() == 1 && !isdigit((unsigned char)toks[0][0]))
            {
                ng.name = toks[0];
            }
            std::sort(ng.atoms.begin(), ng.atoms.end());
            ng.atoms.erase(std::unique(ng.atoms.begin(), ng.atoms.end()), ng.atoms.end());
            groups.push_back(ng);
        }
        else if (startsWith(line, "name "))
        {
            std::vector<std::string> toks = splitWS(line.substr(5));
            int                      idx;
            if (toks.size() >= 2 && parseGroupRef(toks[0], groups, idx))
            {
                groups[idx].name = toks[1];
            }
        }
        else if (startsWith(line, "del "))
        {
            int idx;
            if (parseGroupRef(trim(line.substr(4)), groups, idx))
            {
                printf("Removed group %d '%s'\n", idx, groups[idx].name.c_str());
                groups.erase(groups.begin() + idx);
            }
        }
        else if (startsWith(line, "keep "))
        {
            int idx;
            if (parseGroupRef(trim(line.substr(5)), groups, idx))
            {
                NGroup k = groups[idx];
                groups.clear();
                groups.push_back(k);
            }
        }
        else if (line[0] == '!')
        {
            int idx;
            if (parseGroupRef(trim(line.substr(1)), groups, idx))
            {
                printf("Copied index group %d '%s'\n", idx, groups[idx].name.c_str());
                NGroup ng;
                ng.name = "!" + groups[idx].name;
                std::set<int> in(groups[idx].atoms.begin(), groups[idx].atoms.end());
                for (int i = 0; i < natoms; i++)
                {
                    if (!in.count(i))
                    {
                        ng.atoms.push_back(i);
                    }
                }
                printf("Complemented group: %d atoms\n", (int)ng.atoms.size());
                groups.push_back(ng);
            }
        }
        else if (line.find('|') != std::string::npos || line.find('&') != std::string::npos)
        {
            bool        isOr = line.find('|') != std::string::npos;
            size_t      p    = line.find(isOr ? '|' : '&');
            std::string a = trim(line.substr(0, p)), b = trim(line.substr(p + 1));
            int         ia, ib;
            if (parseGroupRef(a, groups, ia) && parseGroupRef(b, groups, ib))
            {
                printf("Copied index group %d '%s'\n", ia, groups[ia].name.c_str());
                printf("Copied index group %d '%s'\n", ib, groups[ib].name.c_str());
                NGroup        ng;
                std::set<int> sa(groups[ia].atoms.begin(), groups[ia].atoms.end());
                std::set<int> sb(groups[ib].atoms.begin(), groups[ib].atoms.end());
                if (isOr)
                {
                    ng.name = groups[ia].name + "_" + groups[ib].name;
                    std::set<int> u = sa;
                    u.insert(sb.begin(), sb.end());
                    ng.atoms.assign(u.begin(), u.end());
                    printf("Merged two groups with OR: %d %d -> %d\n", (int)sa.size(), (int)sb.size(),
                           (int)ng.atoms.size());
                }
                else
                {
                    ng.name = groups[ia].name + "_&_" + groups[ib].name;
                    for (int x : sa)
                    {
                        if (sb.count(x))
                        {
                            ng.atoms.push_back(x);
                        }
                    }
                    printf("Merged two groups with AND: %d %d -> %d\n", (int)sa.size(), (int)sb.size(),
                           (int)ng.atoms.size());
                }
                groups.push_back(ng);
            }
        }
        printf("\n> ");
        fflush(stdout);
    }
    printf("\n");
    writeNdx(opts.fileName("o"), groups);
    return 0;
}

