struct GyrateModule : TAModule
{
    std::vector<SelOptionSpec>       selectionOptions() override { return { { "sel", 1 } }; }
    std::vector<double>              times;
    std::vector<std::vector<double>> vals;
    void optionsFinished(TAContext& c) override
    {
        if (c.opts.getEnum("mode") == "charge" && !c.opts.isSet("s"))
        {
            // charges require a topology
        }
    }
    void analyzeFrame(TAContext& c, const Frame& fr, int) override
    {
        Selection& s = c.sels[0][0];
        int        n = s.posCount();
        double     cm[3] = { 0, 0, 0 };
        for (const auto& p : s.positions)
        {
            for (int d = 0; d < 3; d++)
            {
                cm[d] += p[d];
            }
        }
        for (int d = 0; d < 3; d++)
        {
            cm[d] /= (n > 0 ? n : 1);
        }
        double tot = 0, ax[3] = { 0, 0, 0 };
        for (const auto& p : s.positions)
        {
            double d2[3];
            for (int d = 0; d < 3; d++)
            {
                d2[d] = ((double)p[d] - cm[d]) * ((double)p[d] - cm[d]);
            }
            tot += d2[0] + d2[1] + d2[2];
            ax[0] += d2[1] + d2[2];
            ax[1] += d2[0] + d2[2];
            ax[2] += d2[0] + d2[1];
        }
        std::vector<double> row;
        row.push_back(n > 0 ? std::sqrt(tot / n) : 0);
        for (int d = 0; d < 3; d++)
        {
            row.push_back(n > 0 ? std::sqrt(ax[d] / n) : 0);
        }
        times.push_back(timeConv(c, fr.time));
        vals.push_back(row);
    }
    void writeOutput(TAContext& c) override
    {
        FILE* fp = openPlot(c, c.opts.fileName("o"), "Radius of gyration (total and around axes)", timeLabel(c),
                            "Radius (nm)", { "Rg", "Rg\\\\sX\\\\N", "Rg\\\\sY\\\\N", "Rg\\\\sZ\\\\N" });
        for (size_t f = 0; f < times.size(); f++)
        {
            fprintf(fp, "%11.3f", times[f]);
            for (double v : vals[f])
            {
                fprintf(fp, " %.6f", v);
            }
            fprintf(fp, "\\n");
        }
        xvgrClose(fp);
    }
};

struct MsdModule : TAModule
{
    std::vector<SelOptionSpec> selectionOptions() override { return { { "sel", -1 } }; }
    double                     t0 = 0;
    void beforeFrame(TAContext& c, const Frame& fr, int nf) override
    {
        if (nf == 0)
        {
            t0 = fr.time;
        }
        else if (nf == 1)
        {
            double dt       = fr.time - t0;
            double trestart = c.opts.getReal("trestart");
            double r        = dt > 0 ? std::fmod(trestart, dt) : 0;
            if (dt > 0 && std::fabs(r) > 1e-6 && std::fabs(r - dt) > 1e-6)
            {
                throwInconsistent(formatStr("-trestart (default 10 ps) must be divisible by -dt for useful results."),
                                  "src/gromacs/trajectoryanalysis/modules/msd.cpp", 699,
                                  "virtual void gmx::analysismodules::Msd::analyzeFrame(int, const t_trxframe&, "
                                  "t_pbc*, gmx::TrajectoryAnalysisModuleData*)");
            }
        }
    }
    void afterAllFrames(TAContext&, int nframes) override
    {
        if (nframes < 2)
        {
            emulateCrash();
        }
    }
};

