    double                           nrefSum = 0;
    void initAfterFirstFrame(TAContext& c, const Frame& fr) override
    {
        binw = c.opts.getReal("bin");
        cut  = c.opts.getReal("cut");
        rmax = c.opts.getReal("rmax");
        if (rmax <= 0)
        {
            double minl2 = 1e30;
            for (int d = 0; d < 3; d++)
            {
                double l2 = (double)fr.box[d][0] * fr.box[d][0] + (double)fr.box[d][1] * fr.box[d][1]
                            + (double)fr.box[d][2] * fr.box[d][2];
                minl2 = std::min(minl2, l2);
            }
            rmax = std::sqrt(0.99 * 0.99 * 0.25 * minl2);
        }
        nbins = (int)(rmax / binw) + 1;
        counts.assign(c.sels[1].size(), std::vector<double>(nbins, 0));
        nselSum.assign(c.sels[1].size(), 0);
    }
    void analyzeFrame(TAContext& c, const Frame& fr, int) override
    {
        bool  pbc = c.opts.getBool("pbc");
        auto& ref = c.sels[0][0];
        double vol = (double)fr.box[0][0] * fr.box[1][1] * fr.box[2][2];
        volSum += vol;
        nfr++;
        nrefSum += ref.posCount();
        for (size_t g = 0; g < c.sels[1].size(); g++)
        {
            auto& s = c.sels[1][g];
            nselSum[g] += s.posCount();
            for (const auto& a : ref.positions)
            {
                for (const auto& b : s.positions)
                {
                    double dx[3];
                    for (int d = 0; d < 3; d++)
                    {
                        dx[d] = (double)b[d] - a[d];
                    }
                    if (pbc && !boxIsZero(fr.box))
                    {
                        for (int d = 2; d >= 0; d--)
                        {
                            double bl = fr.box[d][d];
                            if (bl <= 0)
                            {
                                continue;
                            }
                            while (dx[d] > 0.5 * bl)
                            {
                                for (int e = 0; e <= d; e++)
                                {
                                    dx[e] -= fr.box[d][e];
                                }
                            }
                            while (dx[d] <= -0.5 * bl)
                            {
                                for (int e = 0; e <= d; e++)
                                {
                                    dx[e] += fr.box[d][e];
                                }
                            }
                        }
                    }
                    double r = std::sqrt(dx[0] * dx[0] + dx[1] * dx[1] + dx[2] * dx[2]);
                    if (r == 0 || r < cut || r >= rmax)
                    {
                        continue;
                    }
                    int k = (int)(r / binw + 0.5);
                    if (k >= 0 && k < nbins)
                    {
                        counts[g][k] += 1;
                    }
                }
            }
        }
    }
    void writeOutput(TAContext& c) override
    {
        std::string              norm = c.opts.getEnum("norm");
        std::vector<std::string> legends;
        for (auto& x : c.sels[1])
        {
            legends.push_back(x.name);
        }
        double nref = nfr > 0 ? nrefSum / nfr : 1;
        double vol  = nfr > 0 ? volSum / nfr : 1;
        auto   addSubtitle = [&](FILE* fp) {
            if (c.fmt != XvgFormat::None)
            {
                fprintf(fp, "@ subtitle \\"reference %s\\"\\n", c.sels[0][0].name.c_str());
            }
        };
        {
            FILE* fp = xvgrOpen(c.opts.fileName("o"), "Radial distribution", "r (nm)",
                                norm == "rdf" ? "g(r)" : norm == "number_density" ? "number density (nm\\\\S-3\\\\N)" : "number",
                                c.fmt);
            addSubtitle(fp);
            xvgrLegend(fp, legends, c.fmt);
            for (int k = 0; k < nbins; k++)
            {
                double r  = k * binw;
                double sv = k == 0 ? 4.0 / 3.0 * M_PI * std::pow(0.5 * binw, 3)
                                   : 4.0 / 3.0 * M_PI * (std::pow((k + 0.5) * binw, 3) - std::pow((k - 0.5) * binw, 3));
                fprintf(fp, "%11.6f", (double)(real)r);
                for (size_t g = 0; g < counts.size(); g++)
                {
                    double v   = counts[g][k] / (nfr * nref);
                    double rho = (nselSum[g] / nfr) / vol;
                    if (norm == "rdf")
                    {
                        v = v / sv / rho;
                    }
                    else if (norm == "number_density")
                    {
                        v = v / sv;
                    }
                    fprintf(fp, " %11.6f", (double)(real)v);
                }
                fprintf(fp, "\\n");
            }
            xvgrClose(fp);
        }
        if (c.opts.isSet("cn"))
        {
            FILE* fp = xvgrOpen(c.opts.fileName("cn"), "Cumulative Number RDF", "r (nm)", "number", c.fmt);
            addSubtitle(fp);
            xvgrLegend(fp, legends, c.fmt);
            std::vector<double> cum(counts.size(), 0);
            for (int k = 0; k < nbins; k++)
            {
                fprintf(fp, "%11.3f", (double)(real)((k + 1) * binw));
                for (size_t g = 0; g < counts.size(); g++)
                {
                    cum[g] += counts[g][k] / (nfr * nref);
                    fprintf(fp, " %8.3f", cum[g]);
                }
                fprintf(fp, "\\n");
            }
            xvgrClose(fp);
        }
    }
};''')
