            {
                y[i] = val[s][i] - (bSubAv ? av : 0);
            }
            std::vector<double> c(acflen, 0);
            for (int k = 0; k < acflen; k++)
            {
                double sm = 0;
                for (int i = 0; i + k < n; i++)
                {
                    sm += y[i] * y[i + k];
                }
                c[k] = (n - k) > 0 ? sm / (n - k) : 0;
            }
            double c0 = c.empty() ? 1 : c[0];
            if (bNorm && c0 != 0)
            {
                for (auto& v : c)
