    {
        for (auto* x : outs)
        {
            delete x;
        }
    }
    void initAnalysis(TAContext& c) override
    {
        clusters  = readIndexFile(c.opts.fileName("clusters"));
        int total = 0, maxf = -1;
        for (const auto& g : clusters)
        {
            total += (int)g.atoms.size();
            for (int a : g.atoms)
            {
                maxf = std::max(maxf, a);
            }
        }
        printf("There are %d clusters containing %d structures, highest framenr is %d\\n", (int)clusters.size(),
