        fflush(stdout);
        std::string o = c.opts.fileName("o");
        ext           = fileExtension(o);
        prefix        = stripExtension(o);
        outs.assign(clusters.size(), nullptr);
    }
    void analyzeFrame(TAContext&, const Frame& fr, int nf) override
    {
        for (size_t g = 0; g < clusters.size(); g++)
        {
            if (std::find(clusters[g].atoms.begin(), clusters[g].atoms.end(), nf) == clusters[g].atoms.end())
            {
                continue;
            }
            if (!outs[g])
            {
                std::string fn = prefix + "_" + clusters[g].name + ext;
                makeBackup(fn);
                outs[g] = new XdrFile(fn, "wb");
            }
            int64_t step = fr.bStep ? fr.step : 0;
            if (ext == ".xtc")
            {
                float prec = fr.bPrec && fr.prec > 0 ? (float)(1.0 / fr.prec) : 1000.0f;
                xtcWriteFrame(*outs[g], fr.natoms, step, (float)fr.time, fr.box, fr.x, prec);
            }
            else if (ext == ".trr")
            {
                trrWriteFrame(*outs[g], step, (float)fr.time, 0, &fr.box, fr.natoms, &fr.x, fr.bV ? &fr.v : nullptr,
                              nullptr);
            }
        }
    }
