    for (size_t k = 0; k < specs.size(); k++)
    {
        const SelOptionSpec& sp = specs[k];
        Option*              o  = c.opts.find(sp.name);
        if (o && o->set)
        {
            continue;
        }
        if (sp.count == -2)
        {
            continue;
        }
        if (!queueLoaded)
        {
            queueLoaded = true;
            std::string text;
            if (c.opts.find("sf") && c.opts.isSet("sf"))
            {
                FILE* fp = fopen(c.opts.getString("sf").c_str(), "r");
                if (fp)
                {
                    char   buf[4096];
                    size_t n;
                    while ((n = fread(buf, 1, sizeof(buf), fp)) > 0)
                    {
                        text.append(buf, n);
                    }
                    fclose(fp);
                }
            }
            else if (!stdinRead)
            {
                stdinText = isatty(0) ? std::string() : readAllStdin();
                stdinRead = true;
                text      = stdinText;
            }
            try
            {
                queue = c.sc.parse(text, true);
            }
            catch (const SelSyntaxError& e)
            {
                GmxError err(ErrKind::InvalidInput, "Invalid selection '" + e.text + "'", "", 0, "");
                ErrNode  n1;
                n1.msg = "Near '" + e.near + "'";
                ErrNode n2;
                n2.msg = e.message;
                n1.children.push_back(n2);
                err.root.children.push_back(n1);
                throw err;
            }
        }
        std::vector<Selection> got;
        if (sp.count > 0)
        {
            while ((int)got.size() < sp.count && !queue.empty())
            {
                got.push_back(queue.front());
                queue.erase(queue.begin());
            }
            if ((int)got.size() < sp.count)
            {
                throwInputError(formatStr("Too few selections provided; got %d, expected %d", (int)got.size(),
                                          sp.count),
                                "src/gromacs/selection/selectioncollection.cpp", 404,
                                "gmx::SelectionList gmx::{anonymous}::runParser(yyscan_t, gmx::TextInputStream*, "
                                "bool, int, const string&)");
            }
        }
        else
        {
            got = queue;
            queue.clear();
        }
        if (got.empty())
        {
            throwInputError("Too few selections provided", "src/gromacs/selection/selectionoption.cpp", 107,
                            "void gmx::SelectionOptionStorage::addSelections(const SelectionList&, bool)");
        }
        c.sels[k] = got;
    }
}

